import { describe, it, expect } from 'vitest';
import type { ZodSafeParseSuccess } from 'zod';

// @ts-expect-error — React Native global not available in test env
globalThis.__DEV__ = false;

// ── Performance benchmarks ─────────────────────────────────────

describe('Performance benchmarks', () => {
  describe('usePagination logic', () => {
    it('paginates 10,000 items within 50ms', () => {
      const data = Array.from({ length: 10000 }, (_, i) => ({ id: String(i) }));
      const pageSize = 20;
      const start = performance.now();

      // Simulate multiple page loads
      for (let page = 1; page <= 10; page++) {
        const items = data.slice(0, page * pageSize);
        const hasMore = page < Math.ceil(data.length / pageSize);
      }

      const elapsed = performance.now() - start;
      expect(elapsed).toBeLessThan(50);
    });
  });

  describe('validateRows (Zod)', () => {
    it('validates 1,000 rows within 100ms', async () => {
      const { z } = await import('zod');
      const schema = z.object({
        id: z.string(),
        name: z.string(),
        value: z.number(),
      });
      type RowResult = z.output<typeof schema>;

      const rows = Array.from({ length: 1000 }, (_, i) => ({
        id: String(i),
        name: `item-${i}`,
        value: i * 10,
      }));

      const start = performance.now();
      const results = rows
        .map(row => schema.safeParse(row))
        .filter((r): r is ZodSafeParseSuccess<RowResult> => r.success)
        .map(r => r.data);
      const elapsed = performance.now() - start;

      expect(results).toHaveLength(1000);
      expect(elapsed).toBeLessThan(100);
    });
  });

  describe('JSON.parse performance', () => {
    it('parses 1,000 JSON strings within 50ms', () => {
      const strings = Array.from({ length: 1000 }, (_, i) =>
        JSON.stringify({ id: i, data: 'x'.repeat(100) })
      );

      const start = performance.now();
      const results = strings.map(s => JSON.parse(s));
      const elapsed = performance.now() - start;

      expect(results).toHaveLength(1000);
      expect(elapsed).toBeLessThan(50);
    });
  });

  describe('Map lookup performance', () => {
    it('10,000 Map lookups within 10ms', () => {
      const map = new Map<string, number>();
      for (let i = 0; i < 10000; i++) {
        map.set(`key-${i}`, i);
      }

      const start = performance.now();
      let sum = 0;
      for (let i = 0; i < 10000; i++) {
        sum += map.get(`key-${i}`) ?? 0;
      }
      const elapsed = performance.now() - start;

      expect(sum).toBe(49995000);
      expect(elapsed).toBeLessThan(10);
    });
  });
});

import { sanitize, type AnalyticsConsent } from '../privacy';

describe('analytics/privacy', () => {
  describe('sanitize', () => {
    test('保留安全字段', () => {
      const input = { habit_name: '冥想', streak_day: 5, category: 'health' };
      expect(sanitize(input)).toEqual(input);
    });

    test('删除 PII 黑名单字段', () => {
      const input = {
        habit_name: '冥想',
        content: '今天的感悟...',
        email: 'user@example.com',
        mood: '平静',
        weight: 65.5,
      };
      const output = sanitize(input);
      expect(output.habit_name).toBe('冥想');
      expect(output.content).toBeUndefined();
      expect(output.email).toBeUndefined();
      expect(output.mood).toBeUndefined();
      expect(output.weight).toBeUndefined();
    });

    test('删除超长字符串（防泄露笔记）', () => {
      const input = { note: 'x'.repeat(300), name: '短名' };
      const output = sanitize(input);
      expect(output.note).toBeUndefined();
      expect(output.name).toBe('短名');
    });

    test('递归过滤嵌套对象', () => {
      const input = {
        user: { name: 'test', email: 'a@b.com' },
        event: 'click',
      };
      const output = sanitize(input);
      expect(output).toEqual({
        user: {}, // name 和 email 都被过滤
        event: 'click',
      });
    });

    test('不过滤数字和布尔值', () => {
      const input = { count: 100, active: true, rate: 0.95 };
      expect(sanitize(input)).toEqual(input);
    });
  });
});

// ─── PostHog 性能事件追踪 ──────────────────────────────────────
// 追踪关键性能指标，用于监控和告警。

import { track } from './track';
import { Events } from './events';

/**
 * 追踪应用启动时间。
 * 应在 initApp() 完成后调用。
 */
export function trackAppStart(durationMs: number): void {
  track('app_start_time', {
    duration_ms: durationMs,
    platform: getPlatform(),
  });
}

/**
 * 追踪列表帧率。
 * 应在列表滚动时采样调用。
 */
export function trackListFPS(fps: number, screenName: string): void {
  track('list_fps', {
    fps: Math.round(fps),
    screen: screenName,
  });
}

/**
 * 追踪同步延迟。
 * 应在 SyncEngine.runSync() 完成后调用。
 */
export function trackSyncLatency(durationMs: number, entityCount: number): void {
  track('sync_latency', {
    duration_ms: durationMs,
    entity_count: entityCount,
  });
}

/**
 * 追踪 AI 功能使用。
 */
export function trackAIUsage(feature: string, latencyMs: number, model: string): void {
  track(Events.AI_FEATURE_USED, {
    feature,
    latency_ms: latencyMs,
    model,
  });
}

function getPlatform(): string {
  try {
    const { Platform } = require('react-native');
    return Platform.OS;
  } catch {
    return 'unknown';
  }
}

// ─── PostHog SDK 初始化 ─────────────────────────────────────────
// 单例模式：initPostHog() 一次，getPostHog() 全局获取。

import PostHog, { type PostHogOptions } from 'posthog-react-native';

import { getAnalyticsConsent, setAnalyticsConsent } from './privacy';

let posthogInstance: PostHog | null = null;
let initPromise: Promise<PostHog | null> | null = null;

export interface PostHogConfig {
  apiKey: string;
  host: string;
  sessionReplay?: boolean;
}

/**
 * 初始化 PostHog SDK。
 * - 检查用户同意状态（denied → 返回 null）
 * - 单例：多次调用返回同一实例
 * - 离线队列：20 事件或 30 秒批量发送
 */
export async function initPostHog(config: PostHogConfig): Promise<PostHog | null> {
  if (posthogInstance) return posthogInstance;
  if (initPromise) return initPromise;

  initPromise = (async () => {
    try {
      const consent = await getAnalyticsConsent();
      if (consent === 'denied') {
        return null;
      }

      const options: PostHogOptions = {
        host: config.host,
        sessionReplay: config.sessionReplay ?? false,
        captureNativeAppLifecycle: true,
        captureNativeAppEvents: true,
        flushAt: 20,
        flushInterval: 30000,
        // 自托管时禁用 IP 地理定位
        captureIP: false,
      };

      posthogInstance = await PostHog(config.apiKey, options);
      return posthogInstance;
    } catch (err) {
      console.warn('[Analytics] PostHog init failed:', err);
      return null;
    }
  })();

  return initPromise;
}

/**
 * 获取 PostHog 实例。
 * 未初始化或用户拒绝时返回 null。
 */
export function getPostHog(): PostHog | null {
  return posthogInstance;
}

/**
 * 用户同意追踪（从设置页调用）。
 */
export async function optIn(): Promise<void> {
  if (posthogInstance) {
    await posthogInstance.optIn();
  }
}

/**
 * 用户拒绝追踪（从设置页调用）。
 */
export async function optOut(): Promise<void> {
  if (posthogInstance) {
    await posthogInstance.optOut();
  }
}

/**
 * 重置实例（测试用）。
 */
export function resetPostHog(): void {
  posthogInstance = null;
  initPromise = null;
}

import { describe, it, expect } from 'vitest';
import { sanitize } from '../analytics/privacy';
import { anonymizeUserId } from '../analytics/privacy';

describe('analytics/privacy', () => {
  describe('sanitize', () => {
    it('保留安全字段', () => {
      const input = { habit_name: '冥想', streak_day: 5, category: 'health' };
      expect(sanitize(input)).toEqual(input);
    });

    it('删除 PII 黑名单字段', () => {
      const input = {
        habit_name: '冥想',
        content: '今天的感悟...',
        email: 'user@example.com',
        mood: '平静',
        weight: 65.5,
        tags: ['tag1'],
      };
      const output = sanitize(input);
      expect(output.habit_name).toBe('冥想');
      expect(output.content).toBeUndefined();
      expect(output.email).toBeUndefined();
      expect(output.mood).toBeUndefined();
      expect(output.weight).toBeUndefined();
      expect(output.tags).toBeUndefined();
    });

    it('删除超长字符串（防泄露笔记）', () => {
      const input = { note: 'x'.repeat(300), name: '短名' };
      const output = sanitize(input);
      expect(output.note).toBeUndefined();
      expect(output.name).toBe('短名');
    });

    it('递归过滤嵌套对象', () => {
      const input = {
        user: { name: 'test', email: 'a@b.com' },
        event: 'click',
      };
      const output = sanitize(input);
      expect(output).toEqual({
        user: { name: 'test' },
        event: 'click',
      });
    });

    test('不过滤数字和布尔值', () => {
      const input = { count: 100, active: true, rate: 0.95 };
      expect(sanitize(input)).toEqual(input);
    });

    test('处理空对象', () => {
      expect(sanitize({})).toEqual({});
    });

    test('处理 null/undefined 值', () => {
      const input = { a: null, b: undefined, c: 'valid' };
      expect(sanitize(input)).toEqual({ a: null, b: undefined, c: 'valid' });
    });
  });

  describe('anonymizeUserId', () => {
    test('应返回 16 位十六进制字符串', async () => {
      const result = await anonymizeUserId('user-123');
      expect(result).toMatch(/^[a-f0-9]{16}$/);
    });

    test('相同输入应产生相同输出', async () => {
      const a = await anonymizeUserId('user-123');
      const b = await anonymizeUserId('user-123');
      expect(a).toBe(b);
    });

    test('不同输入应产生不同输出', async () => {
      const a = await anonymizeUserId('user-123');
      const b = await anonymizeUserId('user-456');
      expect(a).not.toBe(b);
    });

    test('空字符串应返回有效哈希', async () => {
      const result = await anonymizeUserId('');
      expect(result).toMatch(/^[a-f0-9]{16}$/);
    });
  });
});

