import { t, formatDate, FONT_SUB, FONT_STAT_SECTION, FONT_LABEL, FONT_BODY } from '@egoless-do/core';
import { Image, type ImageSource } from 'expo-image';
import {
  Home, ClipboardList, Timer, Binary, Sparkles, Dumbbell,
  Target, BarChart3, Settings, Flame,
} from 'lucide-react-native';
import React, { useMemo, useRef } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { useAppStore, useShallowStore } from '../store/useAppStore';


import { useTheme } from './UI';


const TAB_ICONS_MAP: Record<string, React.ComponentType<{size?: number; color?: string}>> = {
  home: Home, plan: ClipboardList, fasting: Timer, meditation: Binary,
  reflections: Sparkles, exercise: Dumbbell, habits: Target,
  stats: BarChart3, settings: Settings,
};

const TABS = [
  { key: 'home',        labelKey: 'home' },
  { key: 'plan',        labelKey: 'plan' },
  { key: 'fasting',     labelKey: 'fasting' },
  { key: 'meditation',  labelKey: 'meditation' },
  { key: 'reflections', labelKey: 'reflections' },
  { key: 'exercise',    labelKey: 'exercise' },
  { key: 'habits',      labelKey: 'habits' },
];

interface AppHeaderProps {
  activeTab?: string;
  onTabChange?: (key: string) => void;
}

export default function AppHeader({ activeTab, onTabChange }: AppHeaderProps) {
  const theme = useShallowStore(s => s.theme);
  const streak = useShallowStore(s => s.streak);
  const language = useShallowStore(s => s.language);
  const insets = useSafeAreaInsets();
  const scrollRef = useRef<ScrollView>(null);
  const tabLayoutsRef = useRef<Record<string, { x: number; width: number }>>({});

  const TH = useTheme();
  const P = TH.primary;
  const T = (k: string) => t(k as import("@egoless-do/core").I18nKey, language);

  const today = formatDate(new Date(), language, {
    month: 'long', day: 'numeric', weekday: 'short',
  });

  const handleTabLayout = (key: string, x: number, width: number) => {
    tabLayoutsRef.current[key] = { x, width };
  };

  return (
    <View style={[styles.container, { backgroundColor: TH.bg, paddingTop: insets.top }]}>
      {/* Header */}
      <View style={styles.headerRow}>
        <Image
          source={require('../../assets/header-logo.png') as ImageSource}
          style={{ width: 108, height: 54 }}
          contentFit="contain"
        />
        <View style={styles.streakBox}>
            <Text style={[styles.streakLabel, { color: TH.sub }]}>{T('streak')}</Text>
            <View style={styles.streakValue}>
              <Text style={styles.streakValueText}>
                {`${String(streak)} ${T('days')} `}
              </Text>
              <Flame size={20} color="#EA6060" />
            </View>
          </View>
      </View>

      {/* Header Tabs */}
      <ScrollView
        ref={scrollRef}
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.tabsContainer}
        keyboardShouldPersistTaps="handled"
      >
        {TABS.map((tab) => (
          <TouchableOpacity
            key={tab.key}
            onPress={() => onTabChange?.(tab.key)}
            onLayout={(e) => handleTabLayout(tab.key, e.nativeEvent.layout.x, e.nativeEvent.layout.width)}
            activeOpacity={0.7}
            hitSlop={{ top: 8, bottom: 8, left: 4, right: 4 }}
            style={[
              styles.tab,
              { backgroundColor: activeTab === tab.key ? P : TH.card },
            ]}
            accessibilityRole="button"
            accessibilityLabel={T(tab.labelKey)}
          >
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
              {(() => {
                const Icon = TAB_ICONS_MAP[tab.key];
                const isActive = activeTab === tab.key;
                return Icon ? <Icon size={14} color={isActive ? '#fff' : TH.sub} strokeWidth={isActive ? 2.2 : 1.5} /> : null;
              })()}
              <Text style={[
                styles.tabText,
                { color: activeTab === tab.key ? '#fff' : TH.sub },
                activeTab === tab.key && styles.tabTextActive,
              ]}>
                {T(tab.labelKey)}
              </Text>
            </View>
          </TouchableOpacity>
        ))}
      </ScrollView>

      {/* Date line + divider */}
      <View style={[styles.dateRow, { borderBottomColor: TH.border }]}>
        <Text style={[styles.dateText, { color: TH.sub }]}>
          {T('today')} · {today}
        </Text>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    paddingBottom: 0,
  },
  headerRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    paddingHorizontal: 16,
    paddingTop: 16,
    paddingBottom: 8,
  },
  brand: {
    fontSize: FONT_BODY(),
    letterSpacing: 3,
    textTransform: 'uppercase',
    fontWeight: '500',
  },
  appName: {
    fontWeight: '700',
    fontSize: FONT_STAT_SECTION(),
    marginTop: 2,
  },
  streakBox: {
    alignItems: 'flex-end',
  },
  streakLabel: {
    fontSize: FONT_SUB(),
  },
  streakValue: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  streakValueText: {
    fontWeight: '800',
    fontSize: FONT_STAT_SECTION(),
    color: '#EA6060',
  },
  streakUnit: {
    fontSize: FONT_LABEL(),
  },
  tabsContainer: {
    paddingHorizontal: 12,
    paddingVertical: 10,
    gap: 6,
  },
  tab: {
    paddingHorizontal: 14,
    paddingVertical: 8,
    borderRadius: 12,
    minHeight: 36,
    justifyContent: 'center',
  },
  tabText: {
    fontSize: FONT_BODY(),
    fontWeight: '500',
  },
  tabTextActive: {
    fontWeight: '700',
  },
  dateRow: {
    paddingHorizontal: 16,
    paddingTop: 6,
    paddingBottom: 0,
    borderBottomWidth: StyleSheet.hairlineWidth,
  },
  dateText: {
    fontSize: FONT_SUB(),
  },
});

import { FONT_BODY, FONT_SMALL, FONT_BUTTON } from '@egoless-do/core';
import { X, AlertTriangle, Check } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity, Modal, StyleSheet } from 'react-native';

import { useTheme, useT } from './UI';

interface Props {
  visible: boolean;
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
  destructive?: boolean;
  icon?: 'warning' | 'confirm' | 'none';
  onConfirm: () => void;
  onCancel: () => void;
}

export default function ConfirmationDialog({
  visible,
  title,
  message,
  confirmText,
  cancelText,
  destructive = false,
  icon = 'warning',
  onConfirm,
  onCancel,
}: Props) {
  const TH = useTheme();
  const T = useT();

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onCancel}>
      <TouchableOpacity
        activeOpacity={1}
        onPress={onCancel}
        style={styles.overlay}
      >
        <View style={[styles.container, { backgroundColor: TH.card }]}>
          {/* Icon */}
          {icon !== 'none' && (
            <View style={styles.iconContainer}>
              {icon === 'warning' ? (
                <AlertTriangle size={48} color={destructive ? '#EF4444' : '#F59E0B'} />
              ) : (
                <Check size={48} color={TH.primary} />
              )}
            </View>
          )}

          {/* Title */}
          <Text style={[styles.title, { color: TH.text }]}>{title}</Text>

          {/* Message */}
          <Text style={[styles.message, { color: TH.sub }]}>{message}</Text>

          {/* Buttons */}
          <View style={styles.buttons}>
            <TouchableOpacity
              onPress={onCancel}
              style={[styles.button, { backgroundColor: TH.border }]}
            >
              <Text style={[styles.buttonText, { color: TH.text }]}>
                {cancelText || T('commonCancel')}
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              onPress={onConfirm}
              style={[styles.button, { backgroundColor: destructive ? '#EF4444' : TH.primary }]}
            >
              <Text style={[styles.buttonText, { color: '#fff' }]}>
                {confirmText || T('commonConfirm')}
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      </TouchableOpacity>
    </Modal>
  );
}

const styles = StyleSheet.create({
  overlay: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.5)',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  container: {
    borderRadius: 20,
    padding: 24,
    width: '100%',
    maxWidth: 340,
    alignItems: 'center',
  },
  iconContainer: {
    marginBottom: 16,
  },
  title: {
    fontSize: FONT_BODY(),
    fontWeight: '700',
    marginBottom: 8,
    textAlign: 'center',
  },
  message: {
    fontSize: FONT_SMALL(),
    textAlign: 'center',
    marginBottom: 24,
    lineHeight: 20,
  },
  buttons: {
    flexDirection: 'row',
    gap: 12,
    width: '100%',
  },
  button: {
    flex: 1,
    paddingVertical: 12,
    borderRadius: 12,
    alignItems: 'center',
  },
  buttonText: {
    fontSize: FONT_BUTTON(),
    fontWeight: '600',
  },
});

import { dateStr, FONT_TITLE, FONT_SUB, FONT_BODY, FONT_BUTTON } from '@egoless-do/core';
import { ChevronLeft, ChevronRight } from 'lucide-react-native';
import React, { useState, useMemo } from 'react';
import { View, Text, TouchableOpacity, Modal, ScrollView } from 'react-native';

import { useTheme } from './UI';

interface Props {
  visible: boolean;
  value: string; // YYYY-MM-DD
  onConfirm: (date: string) => void;
  onClose: () => void;
  minDate?: string;
  maxDate?: string;
}

const DAYS_IN_MONTH = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const MONTH_NAMES = ['1月','2月','3月','4月','5月','6月','7月','8月','9月','10月','11月','12月'];
const WEEK_LABELS = ['日','一','二','三','四','五','六'];

function parseDate(s: string): { y: number; m: number; d: number } | null {
  if (!s || s.length !== 10) return null;
  const parts = s.split('-');
  if (parts.length !== 3) return null;
  return { y: +parts[0], m: +parts[1], d: +parts[2] };
}

function daysInMonth(y: number, m: number): number {
  if (m === 1 && ((y % 4 === 0 && y % 100 !== 0) || y % 400 === 0)) return 29;
  return DAYS_IN_MONTH[m];
}

export default function DatePickerModal({ visible, value, onConfirm, onClose, minDate, maxDate }: Props) {
  const TH = useTheme();
  const parsed = parseDate(value);
  const now = new Date();
  const [year, setYear] = useState(parsed?.y ?? now.getFullYear());
  const [month, setMonth] = useState((parsed?.m ?? now.getMonth() + 1) - 1); // 0-indexed
  const [selectedDay, setSelectedDay] = useState(parsed?.d ?? now.getDate());

  // Reset when value changes
  React.useEffect(() => {
    const p = parseDate(value);
    if (p) {
      setYear(p.y);
      setMonth(p.m - 1);
      setSelectedDay(p.d);
    }
  }, [value, visible]);

  const days = daysInMonth(year, month);
  const firstDayOfWeek = new Date(year, month, 1).getDay(); // 0=Sun

  const calendarDays: (number | null)[] = [];
  for (let i = 0; i < firstDayOfWeek; i++) calendarDays.push(null);
  for (let d = 1; d <= days; d++) calendarDays.push(d);

  const formatDate = (y: number, m: number, d: number) =>
    `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

  const isDisabled = (d: number): boolean => {
    const ds = formatDate(year, month, d);
    if (minDate && ds < minDate) return true;
    if (maxDate && ds > maxDate) return true;
    return false;
  };

  const prevMonth = () => {
    if (month === 0) {
      setYear(y => y - 1);
      setMonth(11);
      setSelectedDay(d => Math.min(d, daysInMonth(year - 1, 11)));
    } else {
      setMonth(m => m - 1);
      setSelectedDay(d => Math.min(d, daysInMonth(year, month - 1)));
    }
  };

  const nextMonth = () => {
    if (month === 11) {
      setYear(y => y + 1);
      setMonth(0);
      setSelectedDay(d => Math.min(d, daysInMonth(year + 1, 0)));
    } else {
      setMonth(m => m + 1);
      setSelectedDay(d => Math.min(d, daysInMonth(year, month + 1)));
    }
  };

  const handleConfirm = () => {
    const result = formatDate(year, month, selectedDay);
    if (minDate && result < minDate) { onConfirm(minDate); return; }
    if (maxDate && result > maxDate) { onConfirm(maxDate); return; }
    onConfirm(result);
  };

  const P = TH.primary;

  return (
    <Modal visible={visible} transparent animationType="fade" onRequestClose={onClose}>
      <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.65)', justifyContent: 'center', padding: 24 }}>
        <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 20 }}>
          {/* Month navigation */}
          <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: 16 }}>
            <TouchableOpacity onPress={prevMonth} style={{ padding: 8 }}>
              <ChevronLeft size={20} color={TH.text} />
            </TouchableOpacity>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>{year}年 {MONTH_NAMES[month]}</Text>
            <TouchableOpacity onPress={nextMonth} style={{ padding: 8 }}>
              <ChevronRight size={20} color={TH.text} />
            </TouchableOpacity>
          </View>

          {/* Week labels */}
          <View style={{ flexDirection: 'row', marginBottom: 8 }}>
            {WEEK_LABELS.map(label => (
              <View key={label} style={{ flex: 1, alignItems: 'center' }}>
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{label}</Text>
              </View>
            ))}
          </View>

          {/* Day grid */}
          <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>
            {calendarDays.map((d, idx) => {
              if (d === null) return <View key={`e${idx}`} style={{ width: '14.28%', aspectRatio: 1 }} />;
              const disabled = isDisabled(d);
              const isSelected = d === selectedDay;
              const isToday = formatDate(year, month, d) === dateStr();
              return (
                <TouchableOpacity
                  key={d}
                  disabled={disabled}
                  onPress={() => setSelectedDay(d)}
                  style={{
                    width: '14.28%', aspectRatio: 1, alignItems: 'center', justifyContent: 'center',
                    opacity: disabled ? 0.3 : 1,
                  }}
                >
                  <View style={{
                    width: 32, height: 32, borderRadius: 16, alignItems: 'center', justifyContent: 'center',
                    backgroundColor: isSelected ? P : 'transparent',
                  }}>
                  <Text style={{
                    fontSize: FONT_BODY(), fontWeight: isSelected ? '700' : '400',
                    color: isSelected ? '#fff' : isToday ? P : TH.text,
                  }}>{d}</Text>
                  </View>
                </TouchableOpacity>
              );
            })}
          </View>

          {/* Buttons */}
          <View style={{ flexDirection: 'row', gap: 10, marginTop: 16 }}>
            <TouchableOpacity onPress={onClose}
              style={{ flex: 1, padding: 12, borderRadius: 12, borderWidth: 1, borderColor: TH.border, alignItems: 'center' }}>
              <Text style={{ color: TH.sub, fontSize: FONT_BUTTON() }}>取消</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={handleConfirm}
              style={{ flex: 1, padding: 12, borderRadius: 12, backgroundColor: P, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BUTTON() }}>确定</Text>
            </TouchableOpacity>
          </View>
        </View>
      </View>
    </Modal>
  );
}

