import { FONT_BACK, FONT_BODY, FONT_SUB, FONT_BADGE, COLORS } from '@egoless-do/core';
import React, { useState, useMemo } from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

export interface CalendarGridProps {
  /** checkin history entries */
  history: Array<{ date: string; done: boolean; grace?: boolean; deleted?: boolean }>;
  primaryColor: string;
  textColor: string;
  subColor: string;
  borderColor: string;
  onDayPress?: (date: string) => void;
}

const DAY_LABELS = ['一', '二', '三', '四', '五', '六', '日'];
const MONTH_NAMES = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];

function dateStr(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export default function CalendarGrid({
  history, primaryColor, textColor, subColor, borderColor, onDayPress,
}: CalendarGridProps) {
  const today = new Date();
  const [viewYear, setViewYear] = useState(today.getFullYear());
  const [viewMonth, setViewMonth] = useState(today.getMonth());

  const doneSet = useMemo(() => new Set(history.filter(e => e.done && !e.deleted).map(e => e.date)), [history]);
  const graceSet = useMemo(() => new Set(history.filter(e => e.grace && !e.deleted).map(e => e.date)), [history]);

  const weeks = useMemo(() => {
    const firstDay = new Date(viewYear, viewMonth, 1);
    let startDow = firstDay.getDay() - 1;
    if (startDow < 0) startDow = 6;

    const result: Array<Array<{ day: number; date: string; done: boolean; grace: boolean; isToday: boolean; inMonth: boolean }>> = [];
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - startDow);

    const cur = new Date(startDate);
    const todayStr = dateStr(today);
    for (let w = 0; w < 6; w++) {
      const row: Array<{ day: number; date: string; done: boolean; grace: boolean; isToday: boolean; inMonth: boolean }> = [];
      for (let d = 0; d < 7; d++) {
        const ds = dateStr(cur);
        row.push({
          day: cur.getDate(),
          date: ds,
          done: doneSet.has(ds),
          grace: graceSet.has(ds),
          isToday: ds === todayStr,
          inMonth: cur.getMonth() === viewMonth,
        });
        cur.setDate(cur.getDate() + 1);
      }
      result.push(row);
    }
    return result;
  }, [viewYear, viewMonth, doneSet, graceSet]);

  const goPrev = () => {
    if (viewMonth === 0) { setViewYear(y => y - 1); setViewMonth(11); }
    else setViewMonth(m => m - 1);
  };
  const goNext = () => {
    if (viewMonth === 11) { setViewYear(y => y + 1); setViewMonth(0); }
    else setViewMonth(m => m + 1);
  };

  const isCurrentMonth = viewYear === today.getFullYear() && viewMonth === today.getMonth();
  const monthDone = weeks.flat().filter(c => c.inMonth && c.done).length;
  const monthTotal = new Date(viewYear, viewMonth + 1, 0).getDate();

  return (
    <View>
      {/* Header */}
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
        <TouchableOpacity onPress={goPrev} style={{ padding: 4, paddingHorizontal: 8 }}>
          <Text style={{ fontSize: FONT_BACK(), color: subColor }}>{'‹'}</Text>
        </TouchableOpacity>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: textColor }}>
            {viewYear}年 {MONTH_NAMES[viewMonth]}
          </Text>
          <Text style={{ fontSize: FONT_SUB(), color: subColor }}>
            {monthDone}/{monthTotal} 天
          </Text>
        </View>
        <TouchableOpacity onPress={goNext} disabled={isCurrentMonth}
          style={{ padding: 4, paddingHorizontal: 8, opacity: isCurrentMonth ? 0.3 : 1 }}>
          <Text style={{ fontSize: FONT_BACK(), color: subColor }}>{'›'}</Text>
        </TouchableOpacity>
      </View>

      {/* Day-of-week headers */}
      <View style={{ flexDirection: 'row', marginBottom: 4 }}>
        {DAY_LABELS.map(d => (
          <View key={d} style={{ flex: 1, alignItems: 'center' }}>
            <Text style={{ fontSize: FONT_BADGE(), color: 'rgba(128,128,128,.5)', fontWeight: '500' }}>{d}</Text>
          </View>
        ))}
      </View>

      {/* Calendar grid */}
      {weeks.map((week, wi) => (
        <View key={wi} style={{ flexDirection: 'row', marginBottom: 4 }}>
          {week.map((cell, di) => {
            const bg = !cell.inMonth ? 'transparent'
              : cell.done ? primaryColor : `${primaryColor}18`;
            const fg = !cell.inMonth ? 'rgba(128,128,128,.2)'
              : cell.done ? '#fff' : 'rgba(128,128,128,.5)';
            // Grace days get dashed border; today gets solid border
            const hasBorder = cell.isToday || cell.grace;
            const borderWidth = cell.isToday ? 2 : cell.grace ? 1.5 : 0;
            const borderColor = cell.isToday ? primaryColor : cell.grace ? COLORS.ORANGE : 'transparent';
            // React Native doesn't support borderStyle: 'dashed' on all platforms,
            // so we render a dashed effect via an overlay View for grace cells
            return (
              <TouchableOpacity key={di} activeOpacity={0.7} onPress={() => onDayPress?.(cell.date)}
                disabled={!cell.inMonth || !cell.done}
                style={{
                  flex: 1, aspectRatio: 1, marginHorizontal: 2,
                  borderRadius: 8, alignItems: 'center', justifyContent: 'center',
                  backgroundColor: bg,
                  borderWidth: hasBorder ? borderWidth : 0,
                  borderColor,
                  borderStyle: cell.grace && !cell.isToday ? 'dashed' : 'solid',
                }}>
                <Text style={{
                  fontSize: FONT_SUB(), fontWeight: cell.isToday ? '700' : '400',
                  color: fg,
                }}>{cell.day}</Text>
              </TouchableOpacity>
            );
          })}
        </View>
      ))}
    </View>
  );
}

import { COLORS } from '@egoless-do/core';
import React from 'react';
import { View, Text } from 'react-native';
import Svg, { Rect, Text as SvgText } from 'react-native-svg';

export interface HeatmapCell {
  date: string;
  done: boolean;
  grace: boolean;
  isToday: boolean;
}

export interface HeatmapGridProps {
  grid: HeatmapCell[][];
  cellSize?: number;
  gap?: number;
  activeColor: string;
  inactiveColor: string;
  todayBorderColor: string;
}

const DAY_LABELS = ['一', '二', '三', '四', '五', '六', '日'];

export default function HeatmapGrid({
  grid, cellSize = 28, gap = 4,
  activeColor, inactiveColor, todayBorderColor,
}: HeatmapGridProps) {
  if (!grid.length) return null;

  const weeks = grid.length;
  const labelW = 16;
  const svgW = labelW + weeks * (cellSize + gap) + gap;
  const svgH = 7 * (cellSize + gap) + gap;

  return (
    <View>
      <Svg width={svgW} height={svgH}>
        {/* Day labels on left */}
        {DAY_LABELS.map((label, i) => (
          <SvgText key={label} x={0} y={gap + i * (cellSize + gap) + cellSize * 0.7}
            fontSize={10} fill="rgba(128,128,128,.5)">{label}</SvgText>
        ))}

        {/* Grid cells */}
        {grid.map((week, wi) =>
          week.map((cell, di) => {
            const x = labelW + wi * (cellSize + gap);
            const y = di * (cellSize + gap);
            const fill = cell.done ? activeColor : inactiveColor;
            const hasBorder = cell.isToday || cell.grace;
            const strokeColor = cell.isToday ? todayBorderColor : cell.grace ? COLORS.ORANGE : 'transparent';
            const strokeWidth = cell.isToday ? 2 : cell.grace ? 1.5 : 0;
            return (
              <React.Fragment key={`${wi}-${di}`}>
                <Rect x={x} y={y} width={cellSize} height={cellSize}
                  rx={6} ry={6} fill={fill}
                  stroke={hasBorder ? strokeColor : 'transparent'}
                  strokeWidth={strokeWidth}
                  strokeDasharray={cell.grace && !cell.isToday ? '4 2' : undefined} />
                {/* Date number inside cell */}
                <SvgText x={x + cellSize / 2} y={y + cellSize / 2 + 4}
                  fontSize={10} textAnchor="middle"
                  fill={cell.done ? '#fff' : 'rgba(128,128,128,.4)'}>
                  {parseInt(cell.date.slice(-2))}
                </SvgText>
              </React.Fragment>
            );
          })
        )}
      </Svg>
    </View>
  );
}

