          <X size={22} color={TH.sub} />
        </TouchableOpacity>
      </View>
      <ScrollView contentContainerStyle={{ padding: 16, paddingBottom: 40 }}>
        <Text style={[styles.prepSubtitle, { color: TH.sub }]}>
          {T(preset.enKey)} · {T('breathPhaseRatio')} {T(preset.ratioKey)}
