// ─── ComboProgressHeader ─────────────────────────────────────────
// 底部引导：横向滚动卡片式，叠加在页面内容上

import { FONT_SMALL, scaleFontSize, type ExerciseDef } from '@egoless-do/core';
import { CheckCircle2, Play } from 'lucide-react-native';
import React, { useCallback, useRef } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Alert, StyleSheet } from 'react-native';

export interface ExerciseResult {
  sportKey: string;
  icon: string;
  nameZh: string;
  durationSec: number;
  calories: number;
  reps: number;
  timestamp: number;
}

interface Props {
  exercises: ExerciseDef[];
  currentIndex: number;
  results: ExerciseResult[];
  onJumpTo: (index: number) => void;
  safeAreaBottom?: number;
  T: (key: string, params?: Record<string, string | number>) => string;
}

const COLORS = {
  done: '#10b981',
  current: '#f59e0b',
  doneBg: '#10b98130',
  currentBg: '#f59e0b30',
  inactiveBg: 'rgba(255,255,255,0.08)',
  inactiveBorder: 'rgba(255,255,255,0.15)',
  text: '#fff',
  textSecondary: 'rgba(255,255,255,0.5)',
};

export default function ComboProgressHeader({ exercises, currentIndex, results, onJumpTo, safeAreaBottom = 0, T }: Props) {
  const scrollRef = useRef<ScrollView>(null);

  const handlePress = useCallback((index: number) => {
    if (index === currentIndex) return;
    if (index < currentIndex) {
      Alert.alert(
        T('bodyComboJumpTo').replace('{name}', `#${index + 1}`),
        T('bodyComboJumpConfirm'),
        [
          { text: T('commonCancel'), style: 'cancel' },
          { text: T('bodyComboJump'), onPress: () => onJumpTo(index) },
        ]
      );
      return;
    }
    Alert.alert(
      T('bodyComboJumpTo').replace('{name}', `#${index + 1}`),
      undefined,
      [
        { text: T('commonCancel'), style: 'cancel' },
        { text: T('bodyComboJump'), onPress: () => onJumpTo(index) },
      ]
    );
  }, [onJumpTo, currentIndex, T]);

  React.useEffect(() => {
    const timer = setTimeout(() => {
      scrollRef.current?.scrollTo({ x: Math.max(0, currentIndex * 90 - 60), animated: true });
    }, 100);
    return () => clearTimeout(timer);
  }, [currentIndex]);

  return (
    <View style={[styles.container, { paddingBottom: safeAreaBottom }]}>
      <View style={styles.progressTrack}>
        <View style={[styles.progressFill, { width: `${exercises.length > 1 ? (currentIndex / (exercises.length - 1)) * 100 : 100}%` }]} />
      </View>

      <ScrollView ref={scrollRef} horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.scrollContent}>
        {exercises.map((ex, i) => {
          const done = i < currentIndex;
          const isCurrent = i === currentIndex;
          const result = results[i];

          return (
            <TouchableOpacity key={ex.id || i} onPress={() => handlePress(i)} activeOpacity={0.7}
              style={[styles.chip, {
                backgroundColor: done ? COLORS.doneBg : isCurrent ? COLORS.currentBg : COLORS.inactiveBg,
                borderColor: done ? COLORS.done : isCurrent ? COLORS.current : COLORS.inactiveBorder,
                borderWidth: isCurrent ? 2 : 1,
              }]}>
              <View style={styles.chipTop}>
                <Text style={styles.chipIcon}>{ex.icon}</Text>
                {done && <CheckCircle2 size={12} color={COLORS.done} style={styles.chipBadge} />}
                {isCurrent && <Play size={12} color={COLORS.current} style={styles.chipBadge} />}
              </View>
              <Text style={[styles.chipName, { color: done ? COLORS.done : isCurrent ? COLORS.current : COLORS.text }]} numberOfLines={1}>
                {ex.nameZh}
              </Text>
              {result ? (
                <Text style={[styles.chipMeta, { color: COLORS.textSecondary }]}>
                  {Math.floor(result.durationSec / 60)}:{(result.durationSec % 60).toString().padStart(2, '0')}
                </Text>
              ) : (
                <Text style={[styles.chipMeta, { color: COLORS.textSecondary }]} numberOfLines={1}>
                  {ex.defaultSets && ex.defaultReps ? T('bodyComboSetsReps', { sets: ex.defaultSets, reps: ex.defaultReps }) : ''}
                  {ex.defaultDurationSec ? T('bodyComboMinutes', { min: Math.round(ex.defaultDurationSec / 60) }) : ''}
                </Text>
              )}
            </TouchableOpacity>
          );
        })}
      </ScrollView>
    </View>
  );
}

