import { EXERCISE_SOUNDS } from '@egoless-do/core';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useAudioPlayer, setAudioModeAsync } from 'expo-audio';
import { useState, useEffect, useCallback, useRef } from 'react';

import { audioSessionManager } from '../../../services/AudioSessionManager';

const SOUND_FILES: Record<string, number> = {
  '海潮': require('../../../../assets/sounds/ocean.mp3') as number,
  '雨声': require('../../../../assets/sounds/rain.mp3') as number,
  '钵声': require('../../../../assets/sounds/bowl.mp3') as number,
  '鸟叫': require('../../../../assets/sounds/birds.mp3') as number,
  '流水': require('../../../../assets/sounds/flowing-stream.mp3') as number,
  '风铃': require('../../../../assets/sounds/wind-chimes.mp3') as number,
};
const BELL_FILE = require('../../../../assets/sounds/temple_bell.mp3') as number;

export function useExerciseAudio() {
  const [selectedSound, setSelectedSound] = useState<string>('无');
  const [showSoundPicker, setShowSoundPicker] = useState(false);
  const shouldAutoPlayRef = useRef(false);

  // 环境音播放器
  const bgSource = SOUND_FILES[selectedSound];
  const bgPlayer = useAudioPlayer(bgSource ?? undefined);

  // 钟声播放器（独立，不受管理器影响）
  const bellPlayer = useAudioPlayer(BELL_FILE);

  useEffect(() => {
    bgPlayer.loop = true;
    bgPlayer.volume = 0.25;
  }, [bgPlayer]);

  useEffect(() => {
    bellPlayer.volume = 0.5;
  }, [bellPlayer]);

  // Auto-play when bgPlayer source changes after selectSound
  useEffect(() => {
    if (shouldAutoPlayRef.current) {
      shouldAutoPlayRef.current = false;
      const allowed = audioSessionManager.requestPlay('ambient');
      if (allowed) {
        bgPlayer.play();
      }
    }
  }, [bgSource, bgPlayer, audioSessionManager]);

  // Init audio session + restore last selected sound
  useEffect(() => {
    setAudioModeAsync({ playsInSilentMode: true, shouldPlayInBackground: false }).catch(() => {});
    AsyncStorage.getItem('sport_selected_sound').then(v => {
      if (v && EXERCISE_SOUNDS.some(s => s.key === v)) setSelectedSound(v);
    }).catch(() => {});
  }, []);

  // Persist selected sound
  useEffect(() => {
    AsyncStorage.setItem('sport_selected_sound', selectedSound).catch(() => {});
  }, [selectedSound]);

  const playBell = useCallback(() => {
    void bellPlayer.seekTo(0);
    bellPlayer.play();
  }, [bellPlayer]);

  const selectSound = useCallback((key: string) => {
    setSelectedSound(key);

    if (key === '无') {
      shouldAutoPlayRef.current = false;
      bgPlayer.pause();
      audioSessionManager.notifyStopped('ambient');
    } else {
      // Mark for auto-play; actual play happens in useEffect after source updates
      shouldAutoPlayRef.current = true;
    }
    setShowSoundPicker(false);
  }, [bgPlayer]);

  // 环境音和钟声在组件卸载时停止，并通知管理器
  const selectedSoundRef = useRef(selectedSound);
  const bgPlayerRef = useRef(bgPlayer);
  const bellPlayerRef = useRef(bellPlayer);
  useEffect(() => { selectedSoundRef.current = selectedSound; }, [selectedSound]);
  useEffect(() => { bgPlayerRef.current = bgPlayer; }, [bgPlayer]);
  useEffect(() => { bellPlayerRef.current = bellPlayer; }, [bellPlayer]);
  useEffect(() => {
    return () => {
      // remove() releases native resources; best-effort since hook may release first
      try { bgPlayerRef.current.remove(); } catch {}
      try { bellPlayerRef.current.remove(); } catch {}
      if (selectedSoundRef.current !== '无') {
        audioSessionManager.notifyStopped('ambient');
      }
    };
  }, []);

  const cycleSound = useCallback(() => {
    setSelectedSound(prev => {
      const idx = EXERCISE_SOUNDS.findIndex(s => s.key === prev);
      const next = EXERCISE_SOUNDS[(idx + 1) % EXERCISE_SOUNDS.length];
      if (next.key === '无') {
        bgPlayer.pause();
        audioSessionManager.notifyStopped('ambient');
      } else {
        shouldAutoPlayRef.current = true;
      }
      setShowSoundPicker(false);
      return next.key;
    });
  }, [bgPlayer]);

  /** Stop all audio immediately (call on exercise end, not unmount) */
  const stopAll = useCallback(() => {
    try { bgPlayer.pause(); } catch {}
    try { bellPlayer.pause(); } catch {}
    audioSessionManager.notifyStopped('ambient');
  }, [bgPlayer, bellPlayer]);

  // Unmount cleanup — best-effort; stopAll should be called explicitly before navigation
  useEffect(() => {
    return () => {
      try { bgPlayerRef.current.remove(); } catch {}
      try { bellPlayerRef.current.remove(); } catch {}
      if (selectedSoundRef.current !== '无') {
        audioSessionManager.notifyStopped('ambient');
      }
    };
  }, []);

  return {
    selectedSound, setSelectedSound,
    showSoundPicker, setShowSoundPicker,
    bgPlayer, bellPlayer,
    playBell, selectSound, cycleSound, stopAll,
  };
}

import { REP_MILESTONES, TIME_MILESTONES, getSoftTarget, TARGET_PRESETS, getSportType } from '@egoless-do/core';
import type { SportType } from '@egoless-do/core';
import * as Haptics from 'expo-haptics';
import { useState, useRef, useCallback } from 'react';
import { Animated, Easing } from 'react-native';

export interface UseExerciseTargetsParams {
  sportName: string;
  sportType: SportType;
  mode: 'free' | 'target';
  targetType: string;
  targetValue: number;
  sec: number;
  distKm: number;
  calories: number;
  totalReps: number;
  playBell: () => void;
  T: (key: string) => string;
}

export function useExerciseTargets(params: UseExerciseTargetsParams) {
  const { sportName, sportType, mode, targetType, targetValue, sec, distKm, calories, totalReps, playBell, T } = params;

  const reachedMilestonesRef = useRef(new Set<number>());
  const [milestoneText, setMilestoneText] = useState<string | null>(null);
  const milestoneAnim = useRef(new Animated.Value(0)).current;
  const softTargetBellPlayedRef = useRef(false);
  const pulseAnim = useRef(new Animated.Value(0.6)).current;
  const [showCelebration, setShowCelebration] = useState(false);
  const celebrateAnim = useRef(new Animated.Value(0)).current;

  // Pulse animation
  // Caller should start the loop in a useEffect

  // Target progress
  const targetProgress = mode === 'target' ? (() => {
    if (targetValue <= 0) return 0;
    if (targetType === 'distance') return Math.min(distKm / targetValue, 1);
    if (targetType === 'time')     return Math.min(sec / targetValue, 1);
    if (targetType === 'calories') return Math.min(calories / targetValue, 1);
    if (targetType === 'reps')     return Math.min(totalReps / targetValue, 1);
    return 0;
  })() : 0;

  // Soft target
  const softTarget = mode === 'free' ? getSoftTarget(sportName) : undefined;
  const softTargetValue = softTarget ? (softTarget.unit === 'min' ? softTarget.intermediate * 60 : softTarget.intermediate) : 0;
  const softTargetProgress = softTargetValue > 0
    ? Math.min((sportType === 'repetition' ? totalReps : sec) / softTargetValue, 1)
    : 0;
  const softTargetReached = softTargetProgress >= 1;
  const softTargetLabel = softTarget
    ? (softTarget.unit === 'min' ? T('exerciseSoftTargetMin').replace('{n}', String(softTarget.intermediate)) : T('exerciseSoftTargetReps').replace('{n}', String(softTarget.intermediate)))
    : '';

  // Celebration
  const triggerCelebration = useCallback(() => {
    setShowCelebration(true);
    celebrateAnim.setValue(0);
    Animated.sequence([
      Animated.timing(celebrateAnim, { toValue: 1, duration: 300, easing: Easing.out(Easing.back(1.5)), useNativeDriver: true }),
      Animated.delay(600),
      Animated.timing(celebrateAnim, { toValue: 0, duration: 200, useNativeDriver: true }),
    ]).start(() => setShowCelebration(false));
  }, [celebrateAnim]);

  // Check target reached (fire once)
  const targetReachedRef = useRef(false);
  const checkTargetReached = useCallback(() => {
    if (mode !== 'target') return;
    let reached = false;
    if (targetType === 'distance' && distKm >= targetValue) reached = true;
    if (targetType === 'time' && sec >= targetValue) reached = true;
    if (targetType === 'calories' && calories >= targetValue) reached = true;
    if (targetType === 'reps' && totalReps >= targetValue) reached = true;
    if (reached && !targetReachedRef.current) {
      targetReachedRef.current = true;
      void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
      triggerCelebration();
      playBell();
    }
  }, [mode, targetType, targetValue, sec, distKm, calories, totalReps, triggerCelebration, playBell]);

  // Milestone check
  const checkMilestone = useCallback(() => {
    const milestones = sportType === 'repetition' ? REP_MILESTONES : TIME_MILESTONES;
    const currentValue = sportType === 'repetition' ? totalReps : sec;
    for (const m of milestones) {
      if (currentValue >= m.value && !reachedMilestonesRef.current.has(m.value)) {
        reachedMilestonesRef.current.add(m.value);
        setMilestoneText(m.label);
        void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
        playBell();
        milestoneAnim.setValue(0);
        Animated.sequence([
          Animated.timing(milestoneAnim, { toValue: 1, duration: 300, useNativeDriver: true }),
          Animated.delay(1500),
          Animated.timing(milestoneAnim, { toValue: 0, duration: 300, useNativeDriver: true }),
        ]).start(() => setMilestoneText(null));
        break;
      }
    }
  }, [sportType, totalReps, sec, playBell, milestoneAnim]);

  // Soft target bell
  const checkSoftTargetBell = useCallback(() => {
    if (softTargetReached && !softTargetBellPlayedRef.current) {
      softTargetBellPlayedRef.current = true;
      void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
      playBell();
    }
    if (!softTargetReached) {
      softTargetBellPlayedRef.current = false;
    }
  }, [softTargetReached, playBell]);

  return {
    targetProgress,
    softTarget, softTargetProgress, softTargetReached, softTargetLabel,
    milestoneText, milestoneAnim,
    showCelebration, celebrateAnim, triggerCelebration,
    pulseAnim,
    checkTargetReached, checkMilestone, checkSoftTargetBell,
  };
}

import * as Haptics from 'expo-haptics';
import { useState, useEffect, useRef, useCallback } from 'react';
import { Animated, Easing } from 'react-native';

export type Page = 'prep' | 'countdown' | 'active' | 'paused' | 'report' | 'transition' | 'combo_report';

export function useExerciseTimer() {
  const [page, setPage]         = useState<Page>('prep');
  const [sec, setSec]           = useState(0);
  const [active, setActive]     = useState(false);
  const [countdown, setCountdown] = useState(3);
  const [pausedSec, setPausedSec] = useState(0);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const holdTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const holdAnim = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const pulseAnim = useRef(new Animated.Value(0)).current;

  // Main timer
  useEffect(() => {
    if (page === 'active' && active) {
      timerRef.current = setInterval(() => setSec(s => s + 1), 1000);
    } else {
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [page, active]);

  // Countdown
  useEffect(() => {
    if (page !== 'countdown') return;
    if (countdown <= 0) {
      setPage('active');
      setActive(true);
      return;
    }
    void Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium);
    const t = setTimeout(() => setCountdown(c => c - 1), 1000);
    return () => clearTimeout(t);
  }, [page, countdown]);

  // Cleanup hold timeout and animation listener on unmount
  useEffect(() => () => {
    if (holdTimeoutRef.current) clearTimeout(holdTimeoutRef.current);
    holdAnim.removeAllListeners();
    holdAnim.stopAnimation();
  }, []);

  const handleGo = useCallback(() => { setCountdown(3); setPage('countdown'); }, []);

  const handlePause = useCallback(() => {
    setActive(false);
    setPage('paused');
  }, []);

  const handleContinue = useCallback(() => {
    setPage('active');
    setActive(true);
  }, []);

  const handleHoldStart = useCallback(() => {
    if (holdTimeoutRef.current) { clearTimeout(holdTimeoutRef.current); holdTimeoutRef.current = null; }
    holdAnim.setValue(0);
    holdAnim.removeAllListeners();

    // Spring scale: overshoot to 1.2 then settle
    Animated.spring(scaleAnim, {
      toValue: 1.2, damping: 8, stiffness: 200, useNativeDriver: true,
    }).start();

    // Linear progress ring fill over 3s
    const anim = Animated.timing(holdAnim, {
      toValue: 1, duration: 3000, easing: Easing.linear, useNativeDriver: false,
    });
    holdAnim.addListener(({ value }) => {
      if (value >= 1) {
        holdAnim.removeAllListeners();
        void Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success);
        // Pulse wave
        pulseAnim.setValue(0);
        Animated.timing(pulseAnim, { toValue: 1, duration: 400, easing: Easing.out(Easing.ease), useNativeDriver: true }).start();
        // Spring back scale
        Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
        holdTimeoutRef.current = setTimeout(() => {
          if (holdTimeoutRef.current !== null) setPage('report');
        }, 400);
      }
    });
    anim.start();
  }, [holdAnim, scaleAnim, pulseAnim]);

  const handleHoldEnd = useCallback(() => {
    if (holdTimeoutRef.current) { clearTimeout(holdTimeoutRef.current); holdTimeoutRef.current = null; }
    holdAnim.removeAllListeners();
    // Spring back scale
    Animated.spring(scaleAnim, { toValue: 1, damping: 10, useNativeDriver: true }).start();
    // Clear ring
    holdAnim.stopAnimation(() => {
      Animated.timing(holdAnim, { toValue: 0, duration: 200, useNativeDriver: false }).start();
    });
  }, [holdAnim, scaleAnim]);

  const reset = useCallback(() => {
    if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
    if (holdTimeoutRef.current) { clearTimeout(holdTimeoutRef.current); holdTimeoutRef.current = null; }
    setSec(0);
    setPage('prep');
    setActive(false);
    setCountdown(3);
    setPausedSec(0);
    holdAnim.setValue(0);
    scaleAnim.setValue(1);
    pulseAnim.setValue(0);
  }, [holdAnim, scaleAnim, pulseAnim]);

  return {
    page, setPage, sec, setSec, active, setActive,
    countdown, pausedSec,
    holdAnim, scaleAnim, pulseAnim, timerRef,
    handleGo, handlePause, handleContinue, handleHoldStart, handleHoldEnd,
    reset,
  };
}

import { COLORS, FONT_HERO, FONT_SUB, FONT_TITLE, formatPace } from '@egoless-do/core';
import type { MusicTrack } from '@egoless-do/core';
import { Pause } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import MeditationMusicBar from '../../../components/MeditationMusicBar';


interface GpsActiveProps {
  MapView: React.ComponentType<Record<string, unknown>>;
  Polyline: React.ComponentType<Record<string, unknown>>;
  amapReady: boolean;
  mapRef: React.RefObject<unknown>;
  initialPos: { latitude: number; longitude: number };
  coords: { latitude: number; longitude: number }[];
  color: string;
  mode: 'free' | 'target';
  targetProgress: number;
  distKm: number;
  sec: number;
  calories: number;
  handlePause: () => void;
  T: (key: string) => string;
  musicTrack?: MusicTrack | null;
  musicIsPlaying?: boolean;
  musicLoop?: boolean;
  onMusicTogglePlay?: () => void;
  onMusicToggleLoop?: () => void;
  onMusicPress?: () => void;
}

export default function GpsActive({
  MapView, Polyline, amapReady, mapRef, initialPos, coords, color,
  mode, targetProgress, distKm, sec, calories, handlePause, T,
  musicTrack, musicIsPlaying, musicLoop, onMusicTogglePlay, onMusicToggleLoop, onMusicPress,
}: GpsActiveProps) {
  return (
    <View style={{ flex: 1, backgroundColor: '#000' }}>
      <View style={{ flex: 4 }}>
        {amapReady && MapView ? (
          <MapView ref={mapRef} style={{ flex: 1 }} initialCameraPosition={{ target: initialPos, zoom: 16 }} myLocationEnabled>
            {coords.length > 1 && <Polyline points={coords} color={color} width={4} />}
          </MapView>
        ) : (
          <View style={{ flex: 1, backgroundColor: '#1a1a2e' }} />
        )}
      </View>
      <View style={{ flex: 6, backgroundColor: '#1a1a2e', padding: 20 }}>
        {mode === 'target' && (
          <View style={{ marginBottom: 16 }}>
            <View style={{ height: 6, backgroundColor: 'rgba(255,255,255,.1)', borderRadius: 3, overflow: 'hidden' }}>
              <View style={{ height: 6, width: `${Math.min(targetProgress * 100, 100)}%`, backgroundColor: COLORS.GREEN, borderRadius: 3 }} />
            </View>
          </View>
        )}
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 24 }}>
          <View style={{ alignItems: 'center', flex: 1 }}>
            <Text style={{ fontSize: FONT_HERO(), fontWeight: '900', color: '#fff', fontVariant: ['tabular-nums'] }}>{distKm.toFixed(2)}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)', marginTop: 4 }}>km</Text>
          </View>
          <View style={{ alignItems: 'center', flex: 1 }}>
            <Text style={{ fontSize: FONT_HERO(), fontWeight: '900', color: '#fff', fontVariant: ['tabular-nums'] }}>{Math.floor(sec / 60)}:{String(sec % 60).padStart(2, '0')}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)', marginTop: 4 }}>{T('exerciseTime')}</Text>
          </View>
          <View style={{ alignItems: 'center', flex: 1 }}>
            <Text style={{ fontSize: FONT_HERO(), fontWeight: '900', color: '#fff', fontVariant: ['tabular-nums'] }}>{formatPace(distKm > 0 ? sec / distKm : 0)}</Text>
            <Text style={{ fontSize: FONT_SUB(), color: 'rgba(255,255,255,.7)', marginTop: 4 }}>{T('exercisePace')}</Text>
          </View>
        </View>
        <View style={{ alignItems: 'center', marginBottom: 24 }}>
          <Text style={{ fontSize: FONT_TITLE(), color: COLORS.ORANGE, fontWeight: '700' }}>{calories} kcal</Text>
        </View>
        <TouchableOpacity onPress={handlePause}
          style={{ width: 88, height: 88, borderRadius: 44, backgroundColor: '#fff', alignItems: 'center', justifyContent: 'center', alignSelf: 'center' }}>
          <Pause size={36} color="#333" />
        </TouchableOpacity>
        {musicTrack && (
          <View style={{ marginTop: 16 }}>
            <MeditationMusicBar
              track={musicTrack}
              isActive
              isPlaying={musicIsPlaying ?? false}
              primaryColor={COLORS.GREEN}
              loop={musicLoop}
              onTogglePlay={onMusicTogglePlay}
              onToggleLoop={onMusicToggleLoop}
              onPress={onMusicPress}
            />
          </View>
        )}
      </View>
    </View>
  );
}

import { COLORS, FONT_HERO, FONT_SUB, FONT_STAT_CARD, FONT_STAT_SECTION, FONT_BODY, fmt } from '@egoless-do/core';
import { LinearGradient } from 'expo-linear-gradient';
import { Minus, Plus, Pause } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity, Animated, StyleSheet } from 'react-native';

import MeditationMusicBar from '../../../components/MeditationMusicBar';
import CelebrationOverlay from '../shared/CelebrationOverlay';
import EmbeddedRest from '../shared/EmbeddedRest';
import ExerciseTopBar from '../shared/ExerciseTopBar';
import RestOverlay from '../shared/RestOverlay';

import type { ExerciseLayoutProps } from './types';

/* Resolve font constants once at module level for StyleSheet */
const FONT_SUB_SIZE = FONT_SUB();
const FONT_HERO_SIZE = FONT_HERO();
const FONT_BODY_SIZE = FONT_BODY();
const FONT_STAT_SECTION_SIZE = FONT_STAT_SECTION();
const FONT_STAT_CARD_SIZE = FONT_STAT_CARD();

export default function StrengthActive(props: ExerciseLayoutProps) {
  const {
    icon, sportName, sec, mode, targetType, targetValue, targetProgress, targetInfo,
    sets, currentSetReps, totalReps, currentSet,
    isResting, restSec, skipRest, restMode = 'overlay',
    selectedSound, showSoundPicker, onToggleSoundPicker, onSelectSound,
    bounceAnim, plusRippleAnim, minusRippleAnim, pulseAnim,
    showCelebration, celebrateAnim, milestoneText, milestoneAnim,
    handlePause, handleCompleteSet, startLongPress, stopLongPress, setCurrentSetReps,
    onPressInPauseLong, onPressOutPauseLong, pauseHoldAnim,
    calories, softTargetReached, softTargetLabel, softTargetProgress, softTarget,
    musicTrack, musicIsPlaying, musicLoop, onMusicTogglePlay, onMusicToggleLoop, onMusicPressTrackName,
    T, topInset, currentExercise,
  } = props;

  const lastSetReps = sets.length > 0 ? sets[sets.length - 1].reps : null;
  const plannedSets = currentExercise?.defaultSets ?? 0;
  const plannedReps = currentExercise?.defaultReps ?? 0;
  const allSetsCompleted = plannedSets > 0 && sets.length >= plannedSets;

  return (
    <LinearGradient colors={['#2e1a1a', '#1f0f0f', '#150a0a']} style={s.root}>
      {/* Rest */}
      {isResting && restMode === 'inline' ? (
        <EmbeddedRest restSec={restSec} onSkip={skipRest} T={T} />
      ) : isResting ? (
        <RestOverlay restSec={restSec} lastSetReps={lastSetReps} setIndex={sets.length}
          targetReps={mode === 'target' && targetType === 'reps' ? targetValue : undefined}
          onSkip={skipRest} label={T('exerciseResting')} T={T} />
      ) : null}

      {/* Celebration */}
      <CelebrationOverlay showCelebration={showCelebration} celebrateAnim={celebrateAnim} milestoneText={milestoneText} milestoneAnim={milestoneAnim} />

      {/* Zone 1: Top bar */}
      <ExerciseTopBar
        icon={icon} sportName={sportName}
        targetInfo={targetInfo}
        selectedSound={selectedSound} showSoundPicker={showSoundPicker}
        onToggleSoundPicker={onToggleSoundPicker} onSelectSound={onSelectSound}
        topInset={topInset}
        rightSlot={
          <View style={{ alignItems: 'flex-end' }}>
            {currentExercise && (
              <Text style={s.exerciseName} numberOfLines={1}>{currentExercise.nameZh}</Text>
            )}
            <Text style={s.setLabel}>
              {currentExercise ? `${sets.length}/${plannedSets} ${T('exerciseSet')}` : T('exerciseSet').replace('{n}', String(currentSet))}
              {plannedReps ? ` × ${plannedReps}` : ''}
            </Text>
          </View>
        }
      />

      {/* Music bar — meditation style */}
      <View style={s.musicBarWrap}>
        <MeditationMusicBar
          track={musicTrack} isActive isPlaying={musicIsPlaying} primaryColor={COLORS.ORANGE}
          loop={musicLoop} onPress={onMusicPressTrackName} onTogglePlay={onMusicTogglePlay} onToggleLoop={onMusicToggleLoop}
        />
      </View>

      {/* Zone 2: Main interaction */}
      <View style={s.interactionZone}>
        {/* +5 quick button */}
        <TouchableOpacity onPress={() => setCurrentSetReps(r => r + 5)}
          style={s.quickPlusBtn}>
          <Text style={s.quickPlusLabel}>+5</Text>
        </TouchableOpacity>

        {/* Main number + controls */}
        <View style={s.controlsRow}>
          <Animated.View style={{ transform: [{ scale: minusRippleAnim }] }}>
            <TouchableOpacity
              onPressIn={() => startLongPress(-1)}
              onPressOut={() => stopLongPress(-1)}
              style={s.minusBtn}>
              <Minus size={24} color="#fff" />
            </TouchableOpacity>
          </Animated.View>

          <Animated.View style={{ transform: [{ scale: bounceAnim }] }}>
            <Text style={s.mainReps}>
              {currentSetReps}
            </Text>
          </Animated.View>

          <Animated.View style={{ transform: [{ scale: plusRippleAnim }] }}>
            <TouchableOpacity
              onPressIn={() => startLongPress(1)}
              onPressOut={() => stopLongPress(1)}
              style={s.plusBtn}>
              <Plus size={32} color="#fff" />
            </TouchableOpacity>
          </Animated.View>
        </View>

        <Text style={s.repsLabel}>{plannedReps ? `${currentSetReps}/${plannedReps} ${T('exerciseReps')}` : T('exerciseReps')}</Text>

        {/* Complete set button */}
        {currentSetReps > 0 && (
          <TouchableOpacity onPress={handleCompleteSet}
            style={s.completeSetBtn}>
            <Text style={s.completeSetLabel}>
              {allSetsCompleted ? (T('bodyFlowFinish')) : T('exerciseSetComplete')}
            </Text>
          </TouchableOpacity>
        )}

        {/* Set history cards */}
        {sets.length > 0 && (
          <View style={s.setHistoryRow}>
            {sets.slice(-4).map((setItem, i) => {
              const idx = sets.length - 4 + i;
              return (
                <View key={idx} style={[s.setHistoryCard, plannedReps > 0 && setItem.reps >= plannedReps && s.setHistoryCardDone]}>
                  <Text style={s.setHistoryText}>
                    {T('exerciseSet').replace('{n}', String(idx + 1))}: {setItem.reps}
                  </Text>
                </View>
              );
            })}
            {sets.length > 4 && (
              <View style={s.setHistoryOverflowCard}>
                <Text style={s.setHistoryOverflowText}>+{sets.length - 4}</Text>
              </View>
            )}
          </View>
        )}

        {/* Target progress */}
        {mode === 'target' && (
          <View style={s.targetSection}>
            <View style={s.progressTrack}>
              <Animated.View style={{ height: 6, width: `${Math.min(targetProgress * 100, 100)}%`, backgroundColor: COLORS.GREEN, borderRadius: 3, opacity: pulseAnim }} />
            </View>
            <Text style={s.targetProgressText}>
              {targetType === 'reps' ? `${totalReps} / ${targetValue} ${T('exerciseReps')}` : `${Math.round(targetProgress * 100)}%`}
            </Text>
          </View>
        )}

        {/* Soft target (free mode) */}
        {mode === 'free' && softTarget && (
          <View style={s.targetSection}>
            <Text style={{ fontSize: FONT_SUB_SIZE, color: softTargetReached ? COLORS.GREEN : 'rgba(255,255,255,.35)', textAlign: 'center', marginBottom: 4 }}>
              {softTargetReached ? T('exerciseTargetReached') : softTargetLabel}
            </Text>
            <View style={s.softProgressTrack}>
              <View style={{ height: 4, width: `${softTargetProgress * 100}%`, backgroundColor: softTargetReached ? COLORS.GREEN : 'rgba(255,255,255,.2)', borderRadius: 2 }} />
            </View>
          </View>
        )}
      </View>

      {/* Zone 3: Bottom bar — duration + pause + calories */}
      <View style={s.bottomBar}>
        <View style={s.bottomStat}>
          <Text style={s.durationValue}>
            {Math.floor(sec / 60)}:{String(sec % 60).padStart(2, '0')}
          </Text>
          <Text style={s.durationLabel}>{T('exerciseDuration')}</Text>
        </View>

        <Animated.View style={{ transform: [{ scale: pauseHoldAnim }] }}>
          <TouchableOpacity
            onPress={handlePause}
            onPressIn={onPressInPauseLong}
            onPressOut={onPressOutPauseLong}
            style={s.pauseBtn}>
            <Pause size={36} color="#333" />
          </TouchableOpacity>
        </Animated.View>

        <View style={s.bottomStat}>
          <Text style={s.caloriesValue}>{calories}</Text>
          <Text style={s.caloriesLabel}>kcal</Text>
        </View>
      </View>
    </LinearGradient>
  );
}

const s = StyleSheet.create({
  /* Containers */
  root: { flex: 1 },
  musicBarWrap: { paddingHorizontal: 16 },
  interactionZone: { flex: 1, alignItems: 'center', justifyContent: 'center', paddingHorizontal: 28 },
  controlsRow: { flexDirection: 'row', alignItems: 'center', gap: 16 },
  setHistoryRow: { flexDirection: 'row', marginTop: 20, gap: 8, flexWrap: 'wrap', justifyContent: 'center' },
  targetSection: { marginTop: 20, width: '100%', paddingHorizontal: 20 },
  bottomBar: { paddingBottom: 48, paddingHorizontal: 20, flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between' },
  bottomStat: { alignItems: 'center', flex: 1 },

  /* Text */
  exerciseName: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.7)', fontWeight: '600', marginBottom: 2 },
  setLabel: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.5)' },
  quickPlusLabel: { color: '#fff', fontWeight: '700', fontSize: FONT_BODY_SIZE },
  mainReps: { fontSize: FONT_HERO_SIZE + 8, fontWeight: '900', color: '#fff', fontVariant: ['tabular-nums'], minWidth: 80, textAlign: 'center' },
  repsLabel: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.65)', marginTop: 6 },
  completeSetLabel: { color: COLORS.GREEN, fontSize: FONT_BODY_SIZE, fontWeight: '700' },
  setHistoryText: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.5)' },
  setHistoryOverflowText: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.7)' },
  targetProgressText: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.7)', marginTop: 4, textAlign: 'center' },
  durationValue: { fontSize: FONT_STAT_SECTION_SIZE, fontWeight: '800', color: '#fff', fontVariant: ['tabular-nums'] },
  durationLabel: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.7)', marginTop: 2 },
  caloriesValue: { fontSize: FONT_STAT_CARD_SIZE, fontWeight: '700', color: COLORS.ORANGE },
  caloriesLabel: { fontSize: FONT_SUB_SIZE, color: 'rgba(255,255,255,.7)', marginTop: 2 },

  /* Buttons */
  quickPlusBtn: { marginBottom: 8, paddingHorizontal: 16, paddingVertical: 6, borderRadius: 16, backgroundColor: 'rgba(255,255,255,.1)' },
  minusBtn: { width: 56, height: 56, borderRadius: 28, backgroundColor: 'rgba(255,255,255,.15)', alignItems: 'center', justifyContent: 'center' },
  plusBtn: { width: 72, height: 72, borderRadius: 36, backgroundColor: COLORS.GREEN, alignItems: 'center', justifyContent: 'center' },
  completeSetBtn: { marginTop: 20, paddingHorizontal: 32, paddingVertical: 14, borderRadius: 24, backgroundColor: `${COLORS.GREEN}30`, borderWidth: 1, borderColor: COLORS.GREEN },
  pauseBtn: { width: 88, height: 88, borderRadius: 44, backgroundColor: '#fff', alignItems: 'center', justifyContent: 'center' },

  /* Cards */
  setHistoryCard: { paddingHorizontal: 12, paddingVertical: 6, borderRadius: 12, backgroundColor: 'rgba(255,255,255,.08)' },
  setHistoryCardDone: { backgroundColor: `${COLORS.GREEN}20`, borderColor: COLORS.GREEN, borderWidth: 1 },
  setHistoryOverflowCard: { paddingHorizontal: 12, paddingVertical: 6, borderRadius: 12, backgroundColor: 'rgba(255,255,255,.05)' },

  /* Progress */
  progressTrack: { height: 6, backgroundColor: 'rgba(255,255,255,.1)', borderRadius: 3, overflow: 'hidden' },
  softProgressTrack: { height: 4, backgroundColor: 'rgba(255,255,255,.08)', borderRadius: 2, overflow: 'hidden' },
});

import { FONT_BACK, FONT_BODY, FONT_SUB, FONT_HERO, FONT_STAT_SECTION, fmt, TARGET_PRESETS, getSoftTarget } from '@egoless-do/core';
import type { MusicTrack , ExerciseEntry } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React, { useState } from 'react';
import { View, Text, TouchableOpacity, TextInput, Alert, KeyboardAvoidingView, Platform, StyleSheet } from 'react-native';

import type { ExercisePageProps } from './types';

export default function PrepPage(props: ExercisePageProps) {
  const {
    sportName, sportType, bg, mode, setMode, targetType, setTargetType, targetValue, setTargetValue,
    breathGuideEnabled, setBreathGuideEnabled, isMeditative,
    handleGo, onGoBack, exerciseLog, T, TH,
    musicTrack, onPressMusic,
  } = props;

  const presets: Record<string, Array<{ label: string; labelEn: string; value: number }> | undefined> = TARGET_PRESETS[sportType] ?? {};
  const availableTargetTypes = Object.keys(presets) as Array<'distance' | 'time' | 'calories' | 'reps'>;
  const [showCustomInput, setShowCustomInput] = useState(false);
  const [customInputValue, setCustomInputValue] = useState('');
  const [customTargetValue, setCustomTargetValue] = useState<Record<string, number>>({});
  const isCustomActive = (t: string) => !!customTargetValue[t] && !presets[t]?.some((p: { value: number }) => p.value === targetValue);

  const modeLabels = {
    free: sportType === 'repetition' ? T('exerciseFreeReps') : sportType === 'timed' ? T('exerciseFreeSport') : T('exerciseFreeRun'),
    target: sportType === 'repetition' ? T('exerciseTargetReps') : sportType === 'timed' ? T('exerciseTargetSport') : T('exerciseTargetRun'),
  };

  const targetTypeLabels: Record<string, string> = {
    distance: T('exerciseDistanceGoal'),
    time: T('exerciseTimeGoal'),
    calories: T('exerciseCalGoal'),
    reps: T('exerciseRepsGoal'),
  };

  return (
    <KeyboardAvoidingView
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      style={[styles.container, { backgroundColor: bg }]}
    >
      {/* Header */}
      <View style={styles.header}>
        <View style={styles.headerRow}>
          <Text style={styles.headerTitle}>{sportName}</Text>
          <TouchableOpacity onPress={onGoBack}>
            <X size={22} color="rgba(255,255,255,.9)" />
          </TouchableOpacity>
        </View>

        {/* Music selector — inline compact */}
        <View style={styles.musicBar}>
          <TouchableOpacity onPress={onPressMusic} style={styles.musicBarButton}>
            <Text style={[styles.musicBarText, { color: musicTrack ? '#fff' : 'rgba(255,255,255,.6)' }]}>
              {musicTrack ? `🎵 ${musicTrack.name}` : `🎵 ${T('exerciseAddMusic')}`}
            </Text>
            <Text style={styles.musicBarArrow}>▸</Text>
          </TouchableOpacity>
        </View>

        {/* Mode toggle */}
        <View style={styles.modeToggle}>
          {(['free', 'target'] as const).map(m => (
            <TouchableOpacity key={m} onPress={() => setMode(m)}
              style={mode === m ? styles.modeOptionActive : styles.modeOptionInactive}>
              <Text style={{ color: '#fff', fontWeight: mode === m ? '700' : '400', fontSize: FONT_BODY() }}>
                {modeLabels[m]}
              </Text>
            </TouchableOpacity>
          ))}
        </View>

        {/* Target selection */}
        {mode === 'target' && (
          <View style={styles.targetSection}>
            <View style={styles.targetTypeRow}>
              {availableTargetTypes.map(t => (
                <TouchableOpacity key={t} onPress={() => { setTargetType(t); setTargetValue(presets[t]?.[0]?.value ?? 0); setShowCustomInput(false); setCustomInputValue(''); }}
                  style={targetType === t ? styles.targetTypePillActive : styles.targetTypePillInactive}>
                  <Text style={{ color: '#fff', fontSize: FONT_SUB(), fontWeight: targetType === t ? '700' : '400' }}>
                    {targetTypeLabels[t] ?? t}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>
            <View style={styles.presetRow}>
              {(presets[targetType as keyof typeof presets] ?? []).map((p: { label: string; value: number }) => (
                <TouchableOpacity key={p.label} onPress={() => { setTargetValue(p.value); setShowCustomInput(false); setCustomInputValue(''); setCustomTargetValue(v => { const n = { ...v }; delete n[targetType]; return n; }); }}
                  style={targetValue === p.value ? styles.presetPillActive : styles.presetPillInactive}>
                  <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: targetValue === p.value ? '700' : '400' }}>{p.label}</Text>
                </TouchableOpacity>
              ))}
              {(targetType === 'time' || targetType === 'calories') && (() => {
                const customActive = isCustomActive(targetType);
                const customLabel = customActive
                  ? (targetType === 'time' ? `${customTargetValue[targetType] / 60} ${T('exerciseMin')}` : `${customTargetValue[targetType]} kcal`)
                  : T('exerciseCustom');
                return (
                  <TouchableOpacity onPress={() => {
                    if (customActive) {
                      setShowCustomInput(false);
                      setCustomInputValue('');
                      setCustomTargetValue(v => { const n = { ...v }; delete n[targetType]; return n; });
                      const firstPreset = presets[targetType]?.[0]?.value ?? 0;
                      setTargetValue(firstPreset);
                    } else {
                      setShowCustomInput(v => !v);
                    }
                  }}
                    style={customActive || showCustomInput ? styles.presetPillActive : styles.presetPillInactive}>
                    <Text style={{ color: '#fff', fontSize: FONT_BODY(), fontWeight: customActive || showCustomInput ? '700' : '400' }}>{customLabel}</Text>
                  </TouchableOpacity>
                );
              })()}
            </View>
            {showCustomInput && (targetType === 'time' || targetType === 'calories') && (
              <View style={styles.customInputRow}>
                <TextInput
                  value={customInputValue}
                  onChangeText={setCustomInputValue}
                  keyboardType="numeric"
                  placeholder={targetType === 'time' ? '30' : '200'}
                  placeholderTextColor="rgba(255,255,255,.7)"
                  style={styles.customInput}
                />
                <Text style={styles.customUnitLabel}>
                  {targetType === 'time' ? T('exerciseMin') : 'kcal'}
                </Text>
                <TouchableOpacity onPress={() => {
                  const num = parseFloat(customInputValue);
                  if (isNaN(num) || num <= 0) {
                    Alert.alert('', T('exerciseCustomInvalid'));
                    return;
                  }
                  const finalValue = targetType === 'time' ? Math.round(num * 60) : Math.round(num);
                  setTargetValue(finalValue);
                  setCustomTargetValue(v => ({ ...v, [targetType]: finalValue }));
                  setCustomInputValue('');
                  setShowCustomInput(false);
                }}
                  style={styles.customConfirmBtn}>
                  <Text style={styles.customConfirmText}>{T('commonConfirm')}</Text>
                </TouchableOpacity>
              </View>
            )}
          </View>
        )}

        {/* Breathing guide toggle (meditative sports) */}
        {isMeditative && (
          <TouchableOpacity onPress={() => setBreathGuideEnabled(v => !v)}
            style={styles.breathToggle}>
            <Text style={styles.breathToggleLabel}>{T('exerciseBreathGuide')}</Text>
            <View style={[styles.switchTrack, { backgroundColor: breathGuideEnabled ? (TH?.accent ?? '#18CEFF') : 'rgba(255,255,255,.2)' }]}>
              <View style={breathGuideEnabled ? styles.switchThumbOn : styles.switchThumbOff} />
            </View>
          </TouchableOpacity>
        )}

        {/* Soft target recommendation */}
        {mode === 'free' && (() => {
          const st = getSoftTarget(sportName);
          if (!st) return null;
          const label = st.unit === 'min' ? T('exerciseSoftTargetMin').replace('{n}', String(st.intermediate)) : T('exerciseSoftTargetReps').replace('{n}', String(st.intermediate));
          return (
            <View style={styles.softTargetCard}>
              <Text style={styles.softTargetText}>{label}</Text>
            </View>
          );
        })()}

        {/* Last workout data */}
        {(() => {
          const lastEntry = exerciseLog?.filter((e: ExerciseEntry) => !e.deleted && e.sportKey === sportName).slice(-1)[0];
          if (!lastEntry) return null;
          return (
            <View style={styles.lastWorkoutCard}>
              <Text style={styles.lastWorkoutText}>
                {T('exerciseLastTime')} {lastEntry.durationSec ? fmt(lastEntry.durationSec) : ''}{lastEntry.reps ? ` · ${lastEntry.reps} ${T('exerciseReps')}` : ''}{lastEntry.calories ? ` · ${lastEntry.calories}kcal` : ''}
              </Text>
            </View>
          );
        })()}
      </View>

      {/* Centered circle + GO button */}
      <View style={styles.goSection}>
        <View style={styles.circle}>
          {sportType === 'repetition' ? (
            <>
              <Text style={styles.circleValue}>0</Text>
              <Text style={styles.circleUnit}>{T('exerciseReps')}</Text>
            </>
          ) : sportType === 'timed' ? (
            <>
              <Text style={styles.circleValue}>0:00</Text>
              <Text style={styles.circleUnit}>{T('exerciseMin')}</Text>
            </>
          ) : (
            <>
              <Text style={styles.circleValue}>0.00</Text>
              <Text style={styles.circleUnit}>km</Text>
            </>
          )}
        </View>

        <TouchableOpacity onPress={handleGo}
          style={styles.goButton}>
          <Text style={{ fontSize: FONT_STAT_SECTION(), fontWeight: '900', color: bg, letterSpacing: 4 }}>GO</Text>
        </TouchableOpacity>
      </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  header: {
    paddingTop: 56,
    paddingHorizontal: 20,
  },
  headerRow: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
  },
  headerTitle: {
    fontSize: FONT_BACK(),
    fontWeight: '700',
    color: '#fff',
  },
  musicBar: {
    marginTop: 10,
  },
  musicBarButton: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
    paddingVertical: 6,
    paddingHorizontal: 10,
    borderRadius: 8,
    backgroundColor: 'rgba(255,255,255,.12)',
  },
  musicBarText: {
    fontSize: FONT_SUB(),
  },
  musicBarArrow: {
    fontSize: FONT_BODY(),
    color: 'rgba(255,255,255,.4)',
  },
  modeToggle: {
    flexDirection: 'row',
    marginTop: 20,
    backgroundColor: 'rgba(0,0,0,.2)',
    borderRadius: 12,
