          </Text>
          <View style={styles.placeholder} />
        </View>
      )}

      {/* 排序切换 - 紧凑模式下隐藏 */}
      {!compact && (
        <View style={styles.sortContainer}>
          <TouchableOpacity
            style={[styles.sortButton, sortBy === 'streak' && { backgroundColor: theme.primary }]}
            onPress={() => setSortBy('streak')}
