    checkinHabit: s.checkinHabit,
  }));

  const [filter, setFilter] = useState('all');
  const [showCal, setShowCal] = useState<string | null>(null);

  const formState = useHabitForm(tomorrow());
  const actionState = useHabitActions();

  useEffect(() => {
    checkHabitAutoStatus();
    autoSyncHabits?.();
  }, [checkHabitAutoStatus, autoSyncHabits]);

  const allHabits = useMemo(() => (habits ?? []).filter(h => !h.deleted), [habits]);

  const filtered = useMemo(() =>
    (filter === 'all' ? allHabits : allHabits.filter(h => h.status === filter))
      .slice().sort((a, b) => (STATUS_ORDER[a.status] - STATUS_ORDER[b.status]) || ((b.startDate ?? '').localeCompare(a.startDate ?? ''))),
    [allHabits, filter]);

  const filterCounts = useMemo(() => {
    const counts: Record<string, number> = { all: allHabits.length };
    allHabits.forEach(h => { counts[h.status] = (counts[h.status] || 0) + 1; });
    return counts;
  }, [allHabits]);

  const calHabit = useMemo(() => (habits ?? []).find(h => h.id === showCal && !h.deleted), [habits, showCal]);

  const handleViewDetail = useCallback((h: Habit) => nav.navigate('HabitDetail', { habitId: h.id }), [nav]);
  const handleCalendar = useCallback((id: string) => setShowCal(id), []);

  const renderHabitItem = useCallback(({ item: h }: { item: Habit }) => (
    <HabitCard
      habit={h}
      primaryColor={P}
      onPress={handleViewDetail}
      onLongPress={actionState.setActionMenuHabit}
      onCheckin={checkinHabit}
      onStart={(id) => actionState.changeStatus(id, 'inProgress')}
      onCalendar={handleCalendar}
    />
  ), [P, handleViewDetail, actionState.setActionMenuHabit, checkinHabit, actionState.changeStatus, handleCalendar]);

  const keyExtractor = useCallback((h: Habit) => h.id, []);

  const ListHeader = useMemo(() => (
    <>
      <ScreenHeader title={T('habitTitle')} compact
        right={
          <TouchableOpacity onPress={formState.openAdd}
            style={{ backgroundColor: P, paddingHorizontal: 16, paddingVertical: 8, borderRadius: 20 }}>
            <Text style={{ color: '#fff', fontWeight: '700', fontSize: FONT_BUTTON() }}>+ {T('habitAdd')}</Text>
          </TouchableOpacity>
        }
      />
      <HabitFilterBar filter={filter} filterCounts={filterCounts} primaryColor={P} onChangeFilter={setFilter} />
    </>
  ), [T, P, filter, filterCounts, formState.openAdd]);

  return (
    <SafeAreaView edges={[]} style={{ flex: 1, backgroundColor: TH.bg }}>
      <SimpleHeader routeName="Habits" />
      <FlatList
        data={filtered}
        renderItem={renderHabitItem}
        keyExtractor={keyExtractor}
        contentContainerStyle={{ padding: 16, paddingBottom: 100 }}
        removeClippedSubviews={true}
        ListHeaderComponent={ListHeader}
        ListEmptyComponent={<HabitEmptyState primaryColor={P} onCreate={formState.openAdd} />}
      />

      <HabitFormModal
        visible={formState.showAdd}
        editingId={formState.editingId}
        form={formState.form}
        setForm={formState.setForm}
        showAlarmPicker={formState.showAlarmPicker}
        setShowAlarmPicker={formState.setShowAlarmPicker}
        onSave={formState.saveHabit}
        onClose={formState.closeForm}
      />

      <HabitActionMenu
        habit={actionState.actionMenuHabit}
        onClose={actionState.closeActionMenu}
        onViewDetail={handleViewDetail}
        onStart={(id) => actionState.changeStatus(id, 'inProgress')}
        onEdit={(h) => { formState.openEdit(h); actionState.closeActionMenu(); }}
        onPause={(id) => actionState.changeStatus(id, 'paused')}
        onResume={(id) => actionState.changeStatus(id, 'inProgress')}
        onAbandon={(id) => actionState.changeStatus(id, 'abandoned')}
        onDelete={(id) => { actionState.setConfirmDelete(id); actionState.closeActionMenu(); }}
      />

      <HabitStatusReasonModal
        visible={!!actionState.statusModal}
        status={actionState.statusModal?.ns ?? null}
        reason={actionState.reason}
        onChangeReason={actionState.setReason}
        onConfirm={actionState.confirmStatus}
        onClose={actionState.closeStatusModal}
      />

      <HabitDeleteConfirmModal
        visible={!!actionState.confirmDelete}
        onConfirm={actionState.executeDelete}
        onClose={actionState.closeDeleteConfirm}
      />

      <HabitCalendarModal
        visible={!!showCal}
        habitName={calHabit?.name ?? ''}
        checkedDates={calHabit?.checkedDates ?? []}
        primaryColor={P}
        onClose={() => setShowCal(null)}
      />
    </SafeAreaView>
  );
}

// ─── HabitCard: habit card with original prominent style ─────────
import {
  COLORS, dateStr, FONT_TITLE, FONT_BODY, FONT_BUTTON, FONT_SUB,
  FONT_SMALL, FONT_BADGE, FONT_STAT_CARD,
  HABIT_LINK_COLORS,
} from '@egoless-do/core';
import type { Habit } from '@egoless-do/core';
import { Target, Pause, X, CheckCircle, Bell, BellOff } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import { useTheme, useT , Card, ProgressBar } from '../../../components/UI';
import { STATUS_COLORS, STATUS_LABELS } from '../constants';

interface Props {
  habit: Habit;
  primaryColor: string;
  onPress: (h: Habit) => void;
  onLongPress: (h: Habit) => void;
  onCheckin: (id: string, date: string) => void;
  onStart: (id: string) => void;
  onCalendar: (id: string) => void;
}

function HabitCard({
  habit: h, primaryColor: P, onPress, onLongPress, onCheckin, onStart, onCalendar,
}: Props) {
  const TH = useTheme();
  const T = useT();
  const sc = STATUS_COLORS[h.status];
  const today = dateStr();
  const isCheckedToday = (h.checkedDates ?? []).includes(today);

  return (
    <View>
      {/* Timeline indicator */}
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 10 }}>
        <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: sc }} />
        <Text style={{ color: TH.sub, fontSize: FONT_SUB(), fontWeight: '600' }}>{h.startDate}</Text>
        <View style={{ flex: 1, height: 1, backgroundColor: TH.border }} />
      </View>

      <TouchableOpacity onPress={() => onPress(h)} onLongPress={() => onLongPress(h)} activeOpacity={0.9}>
        <Card style={{ padding: 14, marginLeft: 16, marginBottom: 16 }}>
          {/* Header: name + status badge */}
          <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 10 }}>
            <Text style={{ color: TH.text, fontWeight: '700', fontSize: FONT_TITLE(), flex: 1, marginRight: 8 }}>{h.name}</Text>
            <View style={{ backgroundColor: `${sc}22`, borderRadius: 8, paddingHorizontal: 10, paddingVertical: 4 }}>
              <Text style={{ color: sc, fontSize: FONT_BADGE(), fontWeight: '600' }}>{T(STATUS_LABELS[h.status])}</Text>
            </View>
          </View>

          {/* Goal */}
          {h.goal ? (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginBottom: 6 }}>
              <Target size={15} color={P} />
              <Text style={{ color: TH.text, fontSize: FONT_BODY(), fontWeight: '700' }}>{h.goal}</Text>
            </View>
          ) : null}

          {/* Meta: start date + target days */}
          <Text style={{ color: TH.sub, fontSize: FONT_BODY(), marginBottom: 8 }}>
            {T('habitStart')} {h.startDate} · {T('habitGoal')} {String(h.targetDays)} {T('habitDays')}
          </Text>

          {/* Alarm */}
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginBottom: 8 }}>
            {h.alarmEnabled ? <Bell size={14} color={P} /> : <BellOff size={14} color={TH.sub} />}
            <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>
              {T('habitAlarm')}: {h.alarmEnabled
                ? `${String(h.alarmHour).padStart(2, '0')}:${String(h.alarmMinute).padStart(2, '0')}`
                : T('habitAlarmOff')}
            </Text>
          </View>

          {/* Insight */}
          {h.insight ? (
            <Text style={{ color: TH.sub, fontSize: FONT_SUB(), marginBottom: 8, fontStyle: 'italic' }}>
              {T('habitVision')}{h.insight}
            </Text>
          ) : null}

          {/* Link */}
          {(h.link && h.link !== 'none') ? (
            <Text style={{ color: HABIT_LINK_COLORS[h.link], fontSize: FONT_SUB(), marginBottom: 8 }}>
              {T('habitLinked')}: {h.link === 'fasting'
                ? `${T('habitLinkedFasting')}（${h.linkConfig?.targetHours ?? 16}h）`
                : h.link === 'exercise'
                  ? `${T('habitLinkedExercise')}（${h.linkConfig?.targetMinutes ?? 30}min）`
                  : h.link === 'sleep' ? T('habitLinkedSleep') : T('habitLinkedMeditation')}
            </Text>
          ) : null}

          {/* Auto tag */}
          {h.createTag && (
            <View style={{ marginBottom: 8, alignSelf: 'flex-start', backgroundColor: `${P}30`, borderRadius: 10, paddingHorizontal: 10, paddingVertical: 3 }}>
              <Text style={{ color: P, fontSize: FONT_SUB() }}>#{h.name}</Text>
            </View>
          )}

          {/* Pause/abandon reason */}
          {h.pauseReason ? (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginBottom: 4 }}>
              <Pause size={14} color={COLORS.YELLOW} />
              <Text style={{ color: COLORS.YELLOW, fontSize: FONT_SUB() }}>{h.pauseReason}</Text>
            </View>
          ) : null}
          {h.abandonReason ? (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, marginBottom: 4 }}>
              <X size={14} color={COLORS.RED} />
              <Text style={{ color: COLORS.RED, fontSize: FONT_SUB() }}>{h.abandonReason}</Text>
            </View>
          ) : null}

          {/* Progress bar */}
          <View style={{ marginBottom: 10 }}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 4 }}>
              <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{h.doneDays}/{h.targetDays} {T('habitDays')}</Text>
              <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{Math.round(h.doneDays / Math.max(h.targetDays, 1) * 100)}%</Text>
            </View>
            <ProgressBar pct={h.doneDays / Math.max(h.targetDays, 1) * 100} color={P} />
          </View>

          {/* Stats row (tap to open calendar) */}
          <TouchableOpacity onPress={() => onCalendar(h.id)}>
            <View style={{ flexDirection: 'row', gap: 20, marginBottom: 12 }}>
              {[
                { v: String(h.doneDays), l: T('habitCumDays'), c: P },
                { v: String(h.streak), l: T('habitStreakDays'), c: COLORS.ORANGE },
                { v: String(h.interrupted), l: T('habitInterrupted'), c: COLORS.RED },
                { v: String(Math.max(0, h.targetDays - h.doneDays)), l: T('habitRemainDays'), c: COLORS.GREEN },
              ].map(({ v, l, c }) => (
                <View key={l} style={{ alignItems: 'center' }}>
                  <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '800', color: c }}>{v}</Text>
                  <Text style={{ fontSize: FONT_SUB(), color: TH.sub, marginTop: 2 }}>{l}</Text>
                </View>
              ))}
            </View>
          </TouchableOpacity>

          {/* Action button */}
          {h.status === 'notStarted' && (
            <TouchableOpacity onPress={() => onStart(h.id)} style={{ paddingVertical: 10, borderRadius: 10, borderWidth: 1, borderColor: COLORS.GREEN, alignItems: 'center' }}>
              <Text style={{ color: COLORS.GREEN, fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('habitStartBtn')}</Text>
            </TouchableOpacity>
          )}
          {h.status === 'inProgress' && (isCheckedToday ? (
            <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, paddingVertical: 10, borderRadius: 10, backgroundColor: `${P}20` }}>
              <CheckCircle size={18} color={P} />
              <Text style={{ color: P, fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('habitChecked')}</Text>
            </View>
          ) : (
            <TouchableOpacity onPress={() => onCheckin(h.id, today)} style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 6, paddingVertical: 10, borderRadius: 10, backgroundColor: P }}>
              <CheckCircle size={18} color="#fff" />
              <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('habitCheckinBtn')}</Text>
            </TouchableOpacity>
          ))}
        </Card>
      </TouchableOpacity>
    </View>
  );
}

export default React.memo(HabitCard);

// ─── HabitCheckinButton: animated check-in button ────────────────
import { FONT_BUTTON } from '@egoless-do/core';
import { CheckCircle } from 'lucide-react-native';
import React, { useCallback, useRef } from 'react';
import { View, Text, TouchableOpacity, Animated } from 'react-native';

import { useTheme, useT } from '../../../components/UI';


interface Props {
  isChecked: boolean;
  onCheckin: () => void;
}

export default function HabitCheckinButton({ isChecked, onCheckin }: Props) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const scaleAnim = useRef(new Animated.Value(1)).current;

  const handlePress = useCallback(() => {
    if (isChecked) return;
    Animated.sequence([
      Animated.timing(scaleAnim, { toValue: 0.92, duration: 80, useNativeDriver: true }),
      Animated.spring(scaleAnim, { toValue: 1, useNativeDriver: true, tension: 200, friction: 10 }),
    ]).start(() => { onCheckin(); });
  }, [isChecked, onCheckin, scaleAnim]);

  if (isChecked) {
    return (
      <Animated.View style={{
        flexDirection: 'row', alignItems: 'center', justifyContent: 'center',
        gap: 8, paddingVertical: 12, borderRadius: 12, backgroundColor: `${P}15`,
        transform: [{ scale: scaleAnim }],
      }}>
        <CheckCircle size={20} color={P} />
        <Text style={{ color: P, fontSize: FONT_BUTTON(), fontWeight: '700' }}>{T('habitChecked')}</Text>
      </Animated.View>
    );
  }

  return (
    <TouchableOpacity onPress={handlePress} activeOpacity={0.8}>
      <Animated.View style={{
        flexDirection: 'row', alignItems: 'center', justifyContent: 'center',
        gap: 8, paddingVertical: 12, borderRadius: 12, backgroundColor: P,
        transform: [{ scale: scaleAnim }],
      }}>
        <CheckCircle size={20} color="#fff" />
        <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '700' }}>{T('habitCheckinBtn')}</Text>
      </Animated.View>
    </TouchableOpacity>
  );
}

// ─── HabitFilterBar: status filter pills ─────────────────────────
import { FONT_SMALL, FONT_TINY } from '@egoless-do/core';
import React from 'react';
import { View, Text, TouchableOpacity, ScrollView } from 'react-native';

import { useTheme, useT } from '../../../components/UI';
import { ALL_FILTERS } from '../constants';

interface Props {
  filter: string;
  filterCounts: Record<string, number>;
  primaryColor: string;
  onChangeFilter: (v: string) => void;
}

export default function HabitFilterBar({ filter, filterCounts, primaryColor: P, onChangeFilter }: Props) {
  const TH = useTheme();
  const T = useT();

  return (
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 8, paddingBottom: 14 }}>
      {ALL_FILTERS.map(([v, l]) => {
        const isActive = filter === v;
        return (
          <TouchableOpacity key={v} onPress={() => onChangeFilter(v)}
            style={{
              flexDirection: 'row', alignItems: 'center', gap: 4,
              paddingHorizontal: 10, paddingVertical: 6, borderRadius: 16,
              backgroundColor: isActive ? `${P}20` : TH.card,
              borderWidth: 1, borderColor: isActive ? P : TH.border,
            }}>
            <Text style={{ color: isActive ? P : TH.text, fontSize: FONT_SMALL() }}>{T(l)}</Text>
            <View style={{ backgroundColor: `${P}20`, paddingHorizontal: 5, paddingVertical: 1, borderRadius: 6 }}>
              <Text style={{ color: P, fontSize: FONT_TINY(), fontWeight: '600' }}>{filterCounts[v] ?? 0}</Text>
            </View>
          </TouchableOpacity>
        );
      })}
    </ScrollView>
  );
}

// ─── useHabitActions: action menu, status change, delete state ────
import type { Habit, HabitStatus } from '@egoless-do/core';
import { useState, useCallback } from 'react';

import { useAppStore, useShallowStore } from '../../../store/useAppStore';

export function useHabitActions() {
  const { updateHabit, deleteHabit } = useShallowStore(s => ({
    updateHabit: s.updateHabit,
    deleteHabit: s.deleteHabit,
  }));

  const [actionMenuHabit, setActionMenuHabit] = useState<Habit | null>(null);
  const [statusModal, setStatusModal] = useState<{ id: string; ns: HabitStatus } | null>(null);
  const [reason, setReason] = useState('');
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  const changeStatus = useCallback((id: string, ns: HabitStatus) => {
    if (ns === 'paused' || ns === 'abandoned') {
      setStatusModal({ id, ns });
      setReason('');
      return;
    }
    updateHabit(id, { status: ns });
  }, [updateHabit]);

  const confirmStatus = useCallback(() => {
    if (!statusModal) return;
    const patch: Partial<Habit> = { status: statusModal.ns };
    if (statusModal.ns === 'paused') patch.pauseReason = reason;
    if (statusModal.ns === 'abandoned') patch.abandonReason = reason;
    updateHabit(statusModal.id, patch);
    setStatusModal(null);
  }, [statusModal, reason, updateHabit]);

  const closeStatusModal = useCallback(() => setStatusModal(null), []);
  const closeActionMenu = useCallback(() => setActionMenuHabit(null), []);
  const closeDeleteConfirm = useCallback(() => setConfirmDelete(null), []);

  const executeDelete = useCallback(() => {
    if (confirmDelete) deleteHabit(confirmDelete);
    setConfirmDelete(null);
  }, [confirmDelete, deleteHabit]);

  return {
    actionMenuHabit,
    setActionMenuHabit,
    statusModal,
    reason,
    setReason,
    confirmDelete,
    setConfirmDelete,
    changeStatus,
    confirmStatus,
    closeStatusModal,
    closeActionMenu,
    closeDeleteConfirm,
    executeDelete,
  };
}

