                <Text style={{ fontSize: FONT_BACK() }}>{isPlaying ? '🔊' : audioCached ? '▶️' : '⬇️'}</Text>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.primary }}>
