import DateRangePickerModal from '../../components/DateRangePickerModal';
import { Card, useTheme, useT, PrimaryButton } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import type { RootStackParamList } from '../../navigation/types';
import { useAppStore, useShallowStore, type MobileStore } from '../../store/useAppStore';

const log = createLogger('Plan');




function FrequencyNumberInput({ value, prefix, suffix, min, max, editable, inputStyle, onCommit }: {
  value: number; prefix: string; suffix: string; min: number; max: number; editable: boolean; inputStyle: object; onCommit: (n: number) => void;
}) {
  const [text, setText] = React.useState(String(value));
  React.useEffect(() => { setText(String(value)); }, [value]);
  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 8 }}>
      <Text style={{ fontSize: FONT_LABEL(), color: '#888' }}>{prefix}</Text>
      <TextInput
        value={text}
        onChangeText={v => setText(v)}
        onBlur={() => { const n = parseInt(text); const clamped = Math.max(min, Math.min(max, n || min)); setText(String(clamped)); onCommit(clamped); }}
        keyboardType="number-pad"
        editable={editable}
        style={[inputStyle, { width: 60, textAlign: 'center', marginBottom: 0 }]}
      />
      <Text style={{ fontSize: FONT_LABEL(), color: '#888' }}>{suffix}</Text>
    </View>
  );
}

export default function PlanCreateScreen() {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { reflections, plans, planItems, visions, habits,
    addPlan, updatePlan, addPlanItem, updatePlanItem, deletePlanItem } = useShallowStore(s => ({
    reflections: s.reflections,
    plans: s.plans,
    planItems: s.planItems,
    visions: s.visions,
    habits: s.habits,
    addPlan: s.addPlan,
    updatePlan: s.updatePlan,
    addPlanItem: s.addPlanItem,
    updatePlanItem: s.updatePlanItem,
    deletePlanItem: s.deletePlanItem,
  }));
  const nav = useRootNavigation();
  const route = useRoute<RouteProp<RootStackParamList, 'PlanCreate'>>();
  const planId = route.params?.planId as string | undefined;
  const reflectionId = route.params?.reflectionId as string | undefined;

  const reflection = useMemo(() => reflectionId ? (reflections ?? []).find(r => !r.deleted && r.id === reflectionId) : null, [reflections, reflectionId]);

  const existingPlan = useMemo(() => planId ? (plans ?? []).find(p => !p.deleted && p.id === planId) : null, [plans, planId]);
  const existingItems = useMemo(() => planId ? (planItems ?? []).filter(i => i.planId === planId && !i.deleted) : [], [planItems, planId]);

  const [name, setName] = useState(existingPlan?.name ?? '');
  const [goal, setGoal] = useState(existingPlan?.goal ?? '');
  const [slogan, setSlogan] = useState(existingPlan?.slogan ?? '');
  const [startDate, setStartDate] = useState(existingPlan?.startDate ?? '');
  const [endDate, setEndDate] = useState(existingPlan?.endDate ?? '');
  const [visionId, setVisionId] = useState<string | undefined>(existingPlan?.visionId);
  const [showVisionPicker, setShowVisionPicker] = useState(false);
  const [saving, setSaving] = useState(false);
  const [items, setItems] = useState<ItemForm[]>(() => {
    const baseItems = existingItems.map(i => ({
      id: i.id, name: i.name, description: i.description,
      startDate: i.startDate, endDate: i.endDate, contentUrl: i.contentUrl,
      link: i.link, priority: i.priority ?? 'medium', targetMetric: i.targetMetric ?? '', linkConfig: i.linkConfig,
      frequency: i.frequency, tags: i.tags,
    }));
    if (reflection) {
      const lines = (reflection.content ?? '').split('\n').filter((l: string) => l.trim());
      const defaultName = lines[0]?.slice(0, 50) || reflection.content?.slice(0, 50) || '';
      const newItem = createNewItem(existingPlan?.startDate ?? '', existingPlan?.endDate ?? '');
      baseItems.push({
        ...newItem,
        name: defaultName,
        description: reflection.content ?? '',
        link: 'reflection',
      });
    }
    return baseItems;
  });
  const [expandedItems, setExpandedItems] = useState<Set<string>>(() => {
    const baseExpanded = new Set(existingItems.map(i => i.id));
    if (reflection) {
      const newItemId = items[items.length - 1]?.id;
      if (newItemId) baseExpanded.add(newItemId);
    }
    return baseExpanded;
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [datePicker, setDatePicker] = useState<{ field: string; value: string; min?: string; max?: string } | null>(null);
  const [showRangePicker, setShowRangePicker] = useState(false);

  const isEdit = !!existingPlan;
  const isActive = existingPlan ? isPlanActive(existingPlan.status) : false;

  // Vision
  const selectedVision = useMemo(() =>
    visionId ? (visions ?? []).find((v: Vision) => v.id === visionId && !v.deleted) : null,
    [visions, visionId]
  );
  const activeVisions = useMemo(() =>
    (visions ?? []).filter((v: Vision) => !v.deleted && v.status === 'active'),
    [visions]
  );

  // Auto-adjust item dates when plan dates change
  useEffect(() => {
    if (!startDate && !endDate) return;
    setItems(prev => prev.map(item => {
      let changed = false;
      let s = item.startDate;
      let e = item.endDate;
      if (startDate && s && s < startDate) { s = startDate; changed = true; }
      if (endDate && e && e > endDate) { e = endDate; changed = true; }
      if (s && e && e < s) { e = s; changed = true; }
      return changed ? { ...item, startDate: s, endDate: e } : item;
    }));
  }, [startDate, endDate]);

  const validate = (): boolean => {
    const e = validatePlanForm({ name, goal, startDate, endDate, items }, T);
    setErrors(e);
    return Object.keys(e).length === 0;
  };

  const handleSave = () => {
    if (saving) return; // Prevent double-click creating duplicates
    if (!validate()) return;
    if (!isEdit) {
      const activePlan = (plans ?? []).find(p => !p.deleted && isPlanActive(p.status));
      if (activePlan) {
        Alert.alert(T('planActiveExists'));
        return;
      }
    }
    if (isEdit && planId) {
      updatePlan(planId, { name, goal, slogan, startDate, endDate, visionId });
      const existingIds = new Set(existingItems.map(i => i.id));
      const currentIds = new Set(items.map(i => i.id));
      // Delete removed existing items
      existingIds.forEach(id => {
        if (!currentIds.has(id)) deletePlanItem(id).catch(err => log.error(err, { message: 'deletePlanItem' }));
      });
      items.forEach((item, idx) => {
        if (existingIds.has(item.id)) {
          updatePlanItem(item.id, {
            name: item.name, description: item.description,
            startDate: item.startDate, endDate: item.endDate,
            contentUrl: item.contentUrl, link: item.link, priority: item.priority, targetMetric: item.targetMetric, linkConfig: item.linkConfig,
            frequency: item.frequency, tags: item.tags,
            order: idx,
          });
        } else {
          addPlanItem({
            planId, name: item.name, description: item.description,
            startDate: item.startDate, endDate: item.endDate,
            contentUrl: item.contentUrl, link: item.link, priority: item.priority, targetMetric: item.targetMetric, linkConfig: item.linkConfig,
            frequency: item.frequency, tags: item.tags,
            order: idx,
          });
        }
      });
      setSaving(true);
      Alert.alert(T('planSaved'), T('planSavedMsg'), [
        { text: T('planContinueEdit'), onPress: () => setSaving(false) },
        { text: T('planBack'), onPress: () => { setSaving(false); nav.goBack(); } },
      ]);
    } else {
      const newPlanId = addPlan({ name, goal, slogan, startDate, endDate, visionId });
      if (newPlanId) {
        setSaving(true);
        Alert.alert(T('planSaved'), T('planSavedMsg'), [
          { text: T('planContinueEdit'), onPress: () => setSaving(false) },
          { text: T('planBack'), onPress: () => { setSaving(false); nav.goBack(); } },
        ]);
      } else {
        // addPlan failed (likely another active plan exists, or validation error)
        Alert.alert(T('planSaveFailedTitle'), T('planSaveFailedMsg'), [{ text: T('ok') }]);
      }
    }
  };

  const addItem = () => {
    const newItem = createNewItem(startDate, endDate);
    setItems(prev => [...prev, newItem]);
    setExpandedItems(prev => new Set(prev).add(newItem.id));
  };

  const removeItem = (id: string) => {
    Alert.alert(T('planDeleteItem'), T('planDeleteItemConfirm'), [
      { text: T('cancel'), style: 'cancel' },
      { text: T('planDeleteItem'), style: 'destructive', onPress: () => setItems(prev => prev.filter(i => i.id !== id)) },
    ]);
  };

  const updateItem = (id: string, patch: Partial<ItemForm>) => {
    setItems(prev => prev.map(i => i.id === id ? { ...i, ...patch } : i));
  };

  const toggleItem = (id: string) => {
    setExpandedItems(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  };

  const inputStyle = {
    backgroundColor: TH.card, borderRadius: 10, borderWidth: 1, borderColor: TH.border,
    paddingHorizontal: 12, paddingVertical: 10, fontSize: FONT_BODY(), color: TH.text,
  };

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* Header */}
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, padding: 16, paddingBottom: 10 }}>
        <TouchableOpacity onPress={() => nav.goBack()}>
          <ChevronLeft size={24} color={TH.text} />
        </TouchableOpacity>
        <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text }}>{isEdit ? T('planEditTitle') : T('planCreate')}</Text>
      </View>

      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'} style={{ flex: 1 }}>
      <ScrollView
        contentContainerStyle={{ padding: 16, paddingBottom: 100 }}
        keyboardDismissMode="on-drag"
        keyboardShouldPersistTaps="handled"
      >
        {/* Plan basic info */}
        <Card>
          <Text style={{ fontSize: FONT_LABEL(), fontWeight: '600', color: TH.sub, marginBottom: 4 }}>{T('planName')} *</Text>
          <TextInput
            value={name} onChangeText={setName} placeholder={T('planName')}
            placeholderTextColor={TH.sub}
            editable={!isActive}
            style={[inputStyle, { marginBottom: errors.name ? 4 : 12, borderColor: errors.name ? COLORS.RED : TH.border, ...(isActive ? { opacity: 0.5 } : {}) }]}
          />
          {errors.name ? <Text style={{ fontSize: FONT_ERROR(), color: COLORS.RED, marginBottom: 8 }}>{errors.name}</Text> : null}

          <Text style={{ fontSize: FONT_LABEL(), fontWeight: '600', color: TH.sub, marginBottom: 4 }}>{T('planGoal')} *</Text>
          <TextInput
            value={goal} onChangeText={setGoal} placeholder={T('planGoal')}
            placeholderTextColor={TH.sub} multiline
            style={[inputStyle, { minHeight: 60, textAlignVertical: 'top', marginBottom: errors.goal ? 4 : 12, borderColor: errors.goal ? COLORS.RED : TH.border }]}
          />
          {errors.goal ? <Text style={{ fontSize: FONT_ERROR(), color: COLORS.RED, marginBottom: 8 }}>{errors.goal}</Text> : null}

          {/* Vision Selector */}
          <Text style={{ fontSize: FONT_LABEL(), fontWeight: '600', color: TH.sub, marginBottom: 4 }}>{T('planLinkVision')}</Text>
          {selectedVision ? (
            <View style={{ backgroundColor: TH.card, borderRadius: 10, padding: 12, marginBottom: 12, borderWidth: 1, borderColor: TH.border, flexDirection: 'row', alignItems: 'center', gap: 8 }}>
              <View style={{ flex: 1 }}>
                <Text style={{ fontSize: FONT_BADGE(), color: '#8B5CF6', fontWeight: '600' }}>
                  {selectedVision.type === 'lifetime' ? '⭐' : selectedVision.type === 'long' ? '🟣' : '🟢'} {T(`vow${selectedVision.type === 'lifetime' ? 'Lifetime' : selectedVision.type === 'long' ? 'Long' : 'Short'}`)}
                </Text>
                <Text style={{ fontSize: FONT_BODY(), color: TH.text, marginTop: 2 }} numberOfLines={1}>{selectedVision.text}</Text>
              </View>
              <TouchableOpacity onPress={() => setShowVisionPicker(true)} style={{ paddingHorizontal: 10, paddingVertical: 4, borderRadius: 6, backgroundColor: `${TH.primary}15` }}>
                <Text style={{ fontSize: FONT_BADGE(), color: TH.primary, fontWeight: '600' }}>{T('planChangeVision')}</Text>
              </TouchableOpacity>
              <TouchableOpacity onPress={() => setVisionId(undefined)} style={{ paddingHorizontal: 10, paddingVertical: 4, borderRadius: 6, backgroundColor: '#EF444415' }}>
                <Text style={{ fontSize: FONT_BADGE(), color: '#EF4444', fontWeight: '600' }}>{T('planUnlinkVision')}</Text>
              </TouchableOpacity>
            </View>
          ) : (
            <TouchableOpacity
              onPress={() => setShowVisionPicker(true)}
              style={[inputStyle, { flexDirection: 'row', alignItems: 'center', gap: 8, marginBottom: 12 }]}
            >
              <Text style={{ fontSize: FONT_BADGE(), color: TH.primary, fontWeight: '600' }}>🔗</Text>
              <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('planSelectVision')}</Text>
            </TouchableOpacity>
          )}

          <Text style={{ fontSize: FONT_LABEL(), fontWeight: '600', color: TH.sub, marginBottom: 4 }}>{T('planSlogan')}</Text>
          <TextInput
            value={slogan} onChangeText={setSlogan} placeholder={T('planSlogan')}
            placeholderTextColor={TH.sub}
            style={[inputStyle, { marginBottom: 12 }]}
          />

          <Text style={{ fontSize: FONT_LABEL(), fontWeight: '600', color: TH.sub, marginBottom: 6 }}>{T('planPeriod')}</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 12 }} contentContainerStyle={{ gap: 6 }}>
            {([
              { key: '1m', months: 1, label: T('planPeriod1m') },
              { key: '3m', months: 3, label: T('planPeriod3m') },
              { key: '6m', months: 6, label: T('planPeriod6m') },
              { key: '1y', months: 12, label: T('planPeriod1y') },
            ] as const).map(opt => (
              <TouchableOpacity
                key={opt.key}
                onPress={() => {
                  const start = new Date();
                  const end = new Date(start);
                  end.setMonth(end.getMonth() + opt.months);
                  end.setDate(end.getDate() - 1);
                  setStartDate(dateStr(start));
                  setEndDate(dateStr(end));
                }}
                style={{
                  paddingHorizontal: 14, paddingVertical: 7, borderRadius: 8,
                  backgroundColor: TH.card, borderWidth: 1, borderColor: TH.border,
                }}
              >
                <Text style={{ color: TH.sub, fontSize: FONT_SUB(), fontWeight: '500' }}>{opt.label}</Text>
              </TouchableOpacity>
            ))}
          </ScrollView>

          <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planTime')} *</Text>
          <TouchableOpacity
            onPress={() => !isActive && setShowRangePicker(true)}
            disabled={isActive}
            style={[inputStyle, { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', borderColor: (errors.startDate || errors.endDate) ? COLORS.RED : TH.border, ...(isActive ? { opacity: 0.5 } : {}) }]}
          >
            <Text style={{ fontSize: FONT_BODY(), color: (startDate && endDate) ? TH.text : TH.sub }}>
              {startDate && endDate ? `${startDate}  —  ${endDate}` : T('planDateRangePlaceholder')}
            </Text>
            <Calendar size={16} color={TH.sub} />
          </TouchableOpacity>
          {errors.startDate ? <Text style={{ fontSize: FONT_ERROR(), color: COLORS.RED, marginTop: 4 }}>{errors.startDate}</Text> : null}
          {errors.endDate ? <Text style={{ fontSize: FONT_ERROR(), color: COLORS.RED, marginTop: 4 }}>{errors.endDate}</Text> : null}
        </Card>

        {/* Items */}
        <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginVertical: 8 }}>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>{T('planItems')}</Text>
          <TouchableOpacity onPress={addItem} style={{ backgroundColor: P, borderRadius: 8, paddingHorizontal: 12, paddingVertical: 6 }}>
            <Text style={{ color: '#fff', fontSize: FONT_SUB(), fontWeight: '600' }}>+ {T('planAddItem')}</Text>
          </TouchableOpacity>
        </View>

        {items.length === 0 && (
          <Card style={{ alignItems: 'center', padding: 24 }}>
            <Text style={{ color: TH.sub, fontSize: FONT_SUB() }}>{T('planNoItems')}</Text>
          </Card>
        )}

        {items.map((item, idx) => {
          const isExpanded = expandedItems.has(item.id);
          const _existingItem = existingItems.find(i => i.id === item.id);
          const _editable = !_existingItem || canEditPlanItem(_existingItem.status);
          return (
            <Card key={item.id} style={{ padding: 0, overflow: 'hidden' }}>
              {/* Header */}
              <TouchableOpacity
                onPress={() => toggleItem(item.id)}
                style={{ flexDirection: 'row', alignItems: 'center', gap: 10, padding: 14 }}
              >
                {isExpanded ? <ChevronDown size={16} color={TH.sub} /> : <ChevronRight size={16} color={TH.sub} />}
                <Text style={{ flex: 1, fontSize: FONT_SUB(), fontWeight: '600', color: TH.text }} numberOfLines={1}>
                  {item.name || `${T('planItemName')} ${idx + 1}`}
                </Text>
                {(() => { const p = PRIORITY_OPTIONS.find(o => o.value === (item.priority ?? 'medium')); return p ? <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: p.color }} /> : null; })()}
                {item.link !== 'manual' && (
                  <Text style={{ fontSize: FONT_BADGE(), color: TH.sub }}>
                    {T(`planLink${item.link.charAt(0).toUpperCase() + item.link.slice(1)}`)}
                  </Text>
                )}
                {item.tags && item.tags.length > 0 && item.tags.map((tag, ti) => (
                  <View key={ti} style={{ paddingHorizontal: 4, paddingVertical: 1, borderRadius: 3, backgroundColor: `${P}15`, borderWidth: 1, borderColor: `${P}30` }}>
                    <Text style={{ fontSize: FONT_BADGE(), color: P }}>{tag}</Text>
                  </View>
                ))}
              </TouchableOpacity>

              {/* Expanded content */}
              {isExpanded && (
                <View style={{ paddingHorizontal: 14, paddingBottom: 14, borderTopWidth: 1, borderTopColor: TH.border }}>
                  {/* Check if existing item is editable */}
                  {(() => {
                    const existingItem = existingItems.find(i => i.id === item.id);
                    if (existingItem && !canEditPlanItem(existingItem.status)) {
                      return (
                        <View style={{ backgroundColor: `${COLORS.ORANGE}15`, padding: 10, borderRadius: 8, marginTop: 10, marginBottom: 8 }}>
                          <Text style={{ fontSize: FONT_SUB(), color: COLORS.ORANGE }}>{T('freqCannotEdit')}</Text>
                        </View>
                      );
                    }
                    return null;
                  })()}
                  <View pointerEvents={_editable ? 'auto' : 'none'} style={_editable ? {} : { opacity: 0.5 }}>
                  <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4, marginTop: 10 }}>{T('planItemName')} *</Text>
                  <TextInput
                    value={item.name} onChangeText={v => updateItem(item.id, { name: v })}
                    placeholder={T('planItemName')} placeholderTextColor={TH.sub}
                    editable={_editable}
                    style={[inputStyle, { marginBottom: 4, borderColor: errors[`item_${idx}_name`] ? COLORS.RED : TH.border }]}
                  />
                  {errors[`item_${idx}_name`] ? <Text style={{ fontSize: FONT_BADGE(), color: COLORS.RED, marginBottom: 6 }}>{errors[`item_${idx}_name`]}</Text> : null}

                  <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planPriority')}</Text>
                  <View style={{ flexDirection: 'row', gap: 6, marginBottom: 8 }}>
                    {PRIORITY_OPTIONS.map(opt => {
                      const active = (item.priority ?? 'medium') === opt.value;
                      return (
                        <TouchableOpacity
                          key={opt.value}
                          onPress={() => updateItem(item.id, { priority: opt.value })}
                          style={{
                            flexDirection: 'row', alignItems: 'center', gap: 4,
                            paddingHorizontal: 12, paddingVertical: 6, borderRadius: 8,
                            backgroundColor: active ? `${opt.color}20` : TH.card,
                            borderWidth: 1, borderColor: active ? opt.color : TH.border,
                          }}
                        >
                          <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: opt.color }} />
                          <Text style={{ color: active ? opt.color : TH.sub, fontSize: FONT_SUB(), fontWeight: active ? '600' : '400' }}>
                            {T(opt.labelKey)}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </View>

                  <Text style={{ fontSize: FONT_LABEL(), color: errors[`item_${idx}_targetMetric`] ? COLORS.RED : TH.sub, marginBottom: 4 }}>{T('planItemTarget')} *</Text>
                  <TextInput
                    value={item.targetMetric} onChangeText={v => updateItem(item.id, { targetMetric: v })}
                    placeholder={T('planItemTarget')} placeholderTextColor={TH.sub}
                    editable={_editable}
                    style={[inputStyle, { borderColor: errors[`item_${idx}_targetMetric`] ? COLORS.RED : TH.border, marginBottom: 8 }]}
                  />

                  <Text style={{ fontSize: FONT_LABEL(), color: errors[`item_${idx}_description`] ? COLORS.RED : TH.sub, marginBottom: 4 }}>{T('planItemDesc')} *</Text>
                  <TextInput
                    value={item.description} onChangeText={v => updateItem(item.id, { description: v })}
                    placeholder={T('planItemDesc')} placeholderTextColor={TH.sub} multiline
                    editable={_editable}
                    style={[inputStyle, { minHeight: 40, textAlignVertical: 'top', borderColor: errors[`item_${idx}_description`] ? COLORS.RED : TH.border, marginBottom: 8 }]}
                  />

                  <View style={{ flexDirection: 'row', gap: 8, marginBottom: 8 }}>
                    <View style={{ flex: 1 }}>
                      <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planItemStart')} *</Text>
                      <TouchableOpacity
                        onPress={() => { const today = dateStr(); const minStart = startDate ? (today < startDate ? startDate : today) : today; setDatePicker({ field: `itemStart_${item.id}`, value: item.startDate, min: minStart, max: endDate || undefined }); }}
                        style={[inputStyle, { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', borderColor: errors[`item_${idx}_startDate`] ? COLORS.RED : TH.border }]}
                      >
                        <Text style={{ fontSize: FONT_BODY(), color: item.startDate ? TH.text : TH.sub }}>{item.startDate || 'YYYY-MM-DD'}</Text>
                        <Calendar size={14} color={TH.sub} />
                      </TouchableOpacity>
                    </View>
                    <View style={{ flex: 1 }}>
                      <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planItemEnd')} *</Text>
                      <TouchableOpacity
                        onPress={() => setDatePicker({ field: `itemEnd_${item.id}`, value: item.endDate, min: item.startDate || startDate || undefined, max: endDate || undefined })}
                        style={[inputStyle, { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', borderColor: errors[`item_${idx}_endDate`] ? COLORS.RED : TH.border }]}
                      >
                        <Text style={{ fontSize: FONT_BODY(), color: item.endDate ? TH.text : TH.sub }}>{item.endDate || 'YYYY-MM-DD'}</Text>
                        <Calendar size={14} color={TH.sub} />
                      </TouchableOpacity>
                    </View>
                  </View>
                  {(errors[`item_${idx}_startDate`] || errors[`item_${idx}_endDate`]) ? (
                    <Text style={{ fontSize: FONT_BADGE(), color: COLORS.RED, marginBottom: 6 }}>
                      {errors[`item_${idx}_startDate`] || errors[`item_${idx}_endDate`]}
                    </Text>
                  ) : null}

                  <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planItemContent')}</Text>
                  {item.tags && item.tags.length > 0 ? (
                    <TextInput
                      value={item.tags.join(', ')}
                      editable={false}
                      style={[inputStyle, { marginBottom: 8, color: TH.sub }]}
                    />
                  ) : (
                    <TextInput
                      value={item.contentUrl} onChangeText={v => updateItem(item.id, { contentUrl: v })}
                      placeholder="https://..." placeholderTextColor={TH.sub}
                      editable={_editable}
                      style={[inputStyle, { marginBottom: 8 }]}
                    />
                  )}

                  <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planItemLink')}</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 8 }} contentContainerStyle={{ gap: 6 }}>
                    {LINK_OPTIONS.map(opt => (
                      <TouchableOpacity
                        key={opt.value}
                        onPress={() => updateItem(item.id, { link: opt.value })}
                        style={{
                          paddingHorizontal: 12, paddingVertical: 6, borderRadius: 8,
                          backgroundColor: item.link === opt.value ? P : TH.card,
                          borderWidth: 1, borderColor: item.link === opt.value ? P : TH.border,
                        }}
                      >
                        <Text style={{ color: item.link === opt.value ? '#fff' : TH.sub, fontSize: FONT_SUB(), fontWeight: item.link === opt.value ? '600' : '400' }}>
                          {T(opt.labelKey)}
                        </Text>
                      </TouchableOpacity>
                    ))}
                  </ScrollView>

                  {/* Frequency selector */}
                  <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('checkinFreq')}</Text>
                  <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 8 }} contentContainerStyle={{ gap: 6 }}>
                    {FREQUENCY_OPTIONS.map(opt => {
                      const active = (item.frequency?.mode ?? 'daily') === opt.mode;
                      return (
                        <TouchableOpacity
                          key={opt.mode}
                          onPress={() => updateItem(item.id, { frequency: opt.mode === 'daily' ? undefined : createDefaultFrequency(opt.mode) })}
                          style={{
                            paddingHorizontal: 12, paddingVertical: 6, borderRadius: 8,
                            backgroundColor: active ? P : TH.card,
                            borderWidth: 1, borderColor: active ? P : TH.border,
                          }}
                        >
                          <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SUB(), fontWeight: active ? '600' : '400' }}>
                            {T(opt.labelKey)}
                          </Text>
                        </TouchableOpacity>
                      );
                    })}
                  </ScrollView>

                  {/* Frequency config */}
                  {item.frequency && item.frequency.mode === 'interval' && (() => {
                    const [prefix, suffix] = T('freqEveryNDays').split('{n}');
                    return (
                      <FrequencyNumberInput
                        value={item.frequency.every} prefix={prefix} suffix={suffix} min={1} max={365}
                        editable={_editable} inputStyle={inputStyle}
                        onCommit={n => updateItem(item.id, { frequency: { mode: 'interval', every: n } })}
                      />
                    );
                  })()}

                  {item.frequency && item.frequency.mode === 'weekly' && (() => {
                    const [prefix, suffix] = T('freqNTimesPerWeek').split('{n}');
                    return (
                      <FrequencyNumberInput
                        value={item.frequency.target} prefix={prefix} suffix={suffix} min={1} max={7}
                        editable={_editable} inputStyle={inputStyle}
                        onCommit={n => updateItem(item.id, { frequency: { mode: 'weekly', target: n } })}
                      />
                    );
                  })()}

                  {item.frequency && item.frequency.mode === 'weekly_fixed' && (
                    <View style={{ flexDirection: 'row', gap: 6, marginBottom: 8 }}>
                      {[0, 1, 2, 3, 4, 5, 6].map(d => {
                        const active = item.frequency && 'days' in item.frequency && item.frequency.days.includes(d);
                        const label = [T('weekdaySun'), T('weekdayMon'), T('weekdayTue'), T('weekdayWed'), T('weekdayThu'), T('weekdayFri'), T('weekdaySat')][d];
                        return (
                          <TouchableOpacity
                            key={d}
                            onPress={() => {
                              if (!item.frequency || !('days' in item.frequency)) return;
                              const days = active ? item.frequency.days.filter(x => x !== d) : [...item.frequency.days, d].sort();
                              updateItem(item.id, { frequency: { mode: 'weekly_fixed', days } });
                            }}
                            style={{
                              width: 36, height: 36, borderRadius: 18, alignItems: 'center', justifyContent: 'center',
                              backgroundColor: active ? P : TH.card,
                              borderWidth: 1, borderColor: active ? P : TH.border,
                            }}
                          >
                            <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SMALL(), fontWeight: active ? '700' : '400' }}>{label}</Text>
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                  )}

                  {item.frequency && item.frequency.mode === 'monthly' && (() => {
                    const [prefix, suffix] = T('freqNTimesPerMonth').split('{n}');
                    return (
                      <FrequencyNumberInput
                        value={item.frequency.target} prefix={prefix} suffix={suffix} min={1} max={31}
                        editable={_editable} inputStyle={inputStyle}
                        onCommit={n => updateItem(item.id, { frequency: { mode: 'monthly', target: n } })}
                      />
                    );
                  })()}

                  {item.frequency && item.frequency.mode === 'monthly_fixed' && (
                    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginBottom: 8 }}>
                      {Array.from({ length: 31 }, (_, i) => i + 1).map(d => {
                        const active = item.frequency && 'dates' in item.frequency && item.frequency.dates.includes(d);
                        return (
                          <TouchableOpacity
                            key={d}
                            onPress={() => {
                              if (!item.frequency || !('dates' in item.frequency)) return;
                              const dates = active ? item.frequency.dates.filter(x => x !== d) : [...item.frequency.dates, d].sort((a, b) => a - b);
                              updateItem(item.id, { frequency: { mode: 'monthly_fixed', dates } });
                            }}
                            style={{
                              width: 36, height: 36, borderRadius: 18, alignItems: 'center', justifyContent: 'center',
                              backgroundColor: active ? P : TH.card,
                              borderWidth: 1, borderColor: active ? P : TH.border,
                            }}
                          >
                            <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SMALL(), fontWeight: active ? '700' : '400' }}>{d}</Text>
                          </TouchableOpacity>
                        );
                      })}
                    </View>
                  )}

                  {item.link === 'habit' && (
                    <>
                      <Text style={{ fontSize: FONT_LABEL(), color: TH.sub, marginBottom: 4 }}>{T('planLinkHabit')}</Text>
                      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 8 }} contentContainerStyle={{ gap: 6 }}>
                        {(habits ?? []).filter(h => !h.deleted).map(h => {
                          const active = item.linkConfig?.habitId === h.id;
                          return (
                            <TouchableOpacity
                              key={h.id}
                              onPress={() => updateItem(item.id, { linkConfig: { ...item.linkConfig, habitId: h.id } })}
                              style={{
                                paddingHorizontal: 12, paddingVertical: 6, borderRadius: 8,
                                backgroundColor: active ? P : TH.card,
                                borderWidth: 1, borderColor: active ? P : TH.border,
                              }}
                            >
                              <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SUB(), fontWeight: active ? '600' : '400' }}>
                                {h.name}
                              </Text>
                            </TouchableOpacity>
                          );
                        })}
                      </ScrollView>
                    </>
                  )}
                  </View>

                  <TouchableOpacity
                    onPress={() => removeItem(item.id)}
                    style={{ paddingVertical: 8, borderRadius: 8, borderWidth: 1, borderColor: `${COLORS.RED}40`, alignItems: 'center' }}
                  >
                    <Text style={{ color: COLORS.RED, fontSize: FONT_SUB() }}>{T('planDeleteItem')}</Text>
                  </TouchableOpacity>
                </View>
              )}
            </Card>
          );
        })}

        {/* Add next task button */}
        {items.length > 0 && (
          <TouchableOpacity
            onPress={addItem}
            style={{
              paddingVertical: 14, borderRadius: 12, borderWidth: 1.5, borderColor: `${P}40`,
              borderStyle: 'dashed', alignItems: 'center', marginTop: 4,
            }}
          >
            <Text style={{ color: P, fontSize: FONT_SUB(), fontWeight: '600' }}>{T('planAddItemHint')}</Text>
          </TouchableOpacity>
        )}
      </ScrollView>
      </KeyboardAvoidingView>

      {/* Save button */}
      <View style={{ position: 'absolute', bottom: 0, left: 0, right: 0, padding: 16, paddingBottom: 32, backgroundColor: TH.bg }}>
        <PrimaryButton label={T('planSave')} onPress={handleSave} />
      </View>

      {/* Date Range Picker Modal for plan dates */}
      <DateRangePickerModal
        visible={showRangePicker}
        startDate={startDate}
        endDate={endDate}
        onClose={() => setShowRangePicker(false)}
        onConfirm={(start, end) => {
          setStartDate(start);
          setEndDate(end);
          setShowRangePicker(false);
        }}
      />

      {/* Date Picker Modal for item dates */}
      {datePicker && (
        <DatePickerModal
          visible
          value={datePicker.value || dateStr()}
          minDate={datePicker.min}
          maxDate={datePicker.max}
          onClose={() => setDatePicker(null)}
          onConfirm={(date) => {
            const { field } = datePicker;
            if (field.startsWith('itemStart_')) {
              const id = field.slice(10);
              const item = items.find(i => i.id === id);
              updateItem(id, { startDate: date, ...(item && item.endDate && item.endDate < date ? { endDate: date } : {}) });
            } else if (field.startsWith('itemEnd_')) {
              updateItem(field.slice(8), { endDate: date });
            }
            setDatePicker(null);
          }}
        />
      )}

      {/* Vision Picker Modal */}
      {showVisionPicker && (
        <Modal visible transparent animationType="fade" onRequestClose={() => setShowVisionPicker(false)}>
          <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.75)', justifyContent: 'center', padding: 24 }}>
            <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, maxHeight: '80%' }}>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text }}>{T('planSelectVision')}</Text>
                <TouchableOpacity onPress={() => setShowVisionPicker(false)}><X size={20} color={TH.sub} /></TouchableOpacity>
              </View>
              <ScrollView>
                {activeVisions.length === 0 ? (
                  <View style={{ alignItems: 'center', padding: 24 }}>
                    <Text style={{ fontSize: scaleFontSize(40), marginBottom: 8 }}>🎯</Text>
                    <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>{T('vowNoVision')}</Text>
                  </View>
                ) : activeVisions.map((v: Vision) => {
                  const typeColor = v.type === 'lifetime' ? '#F59E0B' : v.type === 'long' ? '#8B5CF6' : '#10B981';
                  const typeLabel = v.type === 'lifetime' ? T('vowLifetime') : v.type === 'long' ? T('vowLong') : T('vowShort');
                  return (
                    <TouchableOpacity
                      key={v.id}
                      onPress={() => {
                        setVisionId(v.id);
                        if (!slogan || slogan.trim() === '') setSlogan(v.text);
                        setShowVisionPicker(false);
                      }}
                      style={{
                        padding: 14, borderRadius: 12, marginBottom: 8,
                        backgroundColor: visionId === v.id ? `${typeColor}15` : TH.card,
                        borderWidth: 1, borderColor: visionId === v.id ? typeColor : TH.border,
                      }}
                    >
                      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 4 }}>
                        <Text style={{ fontSize: FONT_BADGE(), color: typeColor, fontWeight: '600' }}>
                          {v.type === 'lifetime' ? '⭐' : v.type === 'long' ? '🟣' : '🟢'} {typeLabel}
                        </Text>
                      </View>
                      <Text style={{ fontSize: FONT_BODY(), color: TH.text, lineHeight: 20 }}>{v.text}</Text>
                    </TouchableOpacity>
                  );
                })}
              </ScrollView>
            </View>
          </View>
        </Modal>
      )}
    </SafeAreaView>
  );
}

import { PLAN_STATUS_COLORS, statusToI18nKey, getHistoryPlans, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BADGE } from '@egoless-do/core';
import type { PlanStatus } from '@egoless-do/core';
import { ChevronLeft, ClipboardList, ChevronRight } from 'lucide-react-native';
import React, { useMemo, useCallback } from 'react';
import { View, Text, FlatList, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { Card, useTheme, useT } from '../../components/UI';
import { useRootNavigation } from '../../navigation/hooks';
import { useAppStore, useShallowStore } from '../../store/useAppStore';



export default function PlanHistoryScreen() {
  const TH = useTheme();
  const T = useT();
  const { plans } = useShallowStore(s => ({ plans: s.plans }));
  const nav = useRootNavigation();

  const historyPlans = useMemo(() => getHistoryPlans(plans ?? []), [plans]);

  const statusLabel = (s: PlanStatus) => T(statusToI18nKey(s));

  const keyExtractor = useCallback((item: typeof historyPlans[number]) => item.id, []);

  const renderPlanItem = useCallback(({ item: plan }: { item: typeof historyPlans[number] }) => (
    <TouchableOpacity
      onPress={() => nav.navigate('PlanDetail', { planId: plan.id })}
      activeOpacity={0.7}
    >
      <Card style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
        <ClipboardList size={24} color={TH.text} />
        <View style={{ flex: 1, minWidth: 0 }}>
          <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text, marginBottom: 4 }} numberOfLines={1}>
            {plan.name}
          </Text>
          <Text style={{ fontSize: FONT_BADGE(), color: TH.sub }}>
            {plan.startDate} ~ {plan.endDate}
          </Text>
        </View>
        <View style={{ alignItems: 'flex-end', gap: 4 }}>
          <View style={{ backgroundColor: `${PLAN_STATUS_COLORS[plan.status]}20`, paddingHorizontal: 8, paddingVertical: 2, borderRadius: 6 }}>
            <Text style={{ fontSize: FONT_BADGE(), fontWeight: '600', color: PLAN_STATUS_COLORS[plan.status] }}>{statusLabel(plan.status)}</Text>
          </View>
          <Text style={{ fontSize: FONT_BADGE(), color: TH.sub }}>{plan.progress}%</Text>
        </View>
        <ChevronRight size={16} color={TH.sub} />
      </Card>
    </TouchableOpacity>
  ), [nav, TH, statusLabel]);

  const renderEmpty = useCallback(() => (
    <Card style={{ alignItems: 'center', padding: 32 }}>
      <ClipboardList size={32} color={TH.sub} style={{ marginBottom: 8 }} />
      <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('planNoHistory')}</Text>
    </Card>
  ), [TH, T]);

  return (
    <SafeAreaView edges={['top', 'bottom']} style={{ flex: 1, backgroundColor: TH.bg }}>
      {/* Header */}
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12, padding: 16, paddingBottom: 10 }}>
        <TouchableOpacity onPress={() => nav.goBack()}>
          <ChevronLeft size={24} color={TH.text} />
        </TouchableOpacity>
        <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text }}>{T('planHistory')}</Text>
      </View>

      <FlatList
        data={historyPlans}
        renderItem={renderPlanItem}
        keyExtractor={keyExtractor}
        contentContainerStyle={{ padding: 16, paddingBottom: 32 }}
        removeClippedSubviews
        ListEmptyComponent={renderEmpty}
      />
    </SafeAreaView>
  );
}

import { COLORS, FONT_BODY, FONT_SUB, FONT_BADGE, FONT_TINY, FONT_EMPTY, getFrequencySummary } from '@egoless-do/core';
import type { PlanItem, PlanItemCheckin } from '@egoless-do/core';
import { Check, ClipboardList, Pencil, Plus, Trash2, Repeat } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity, TextInput, Alert } from 'react-native';

import { useTheme } from '../../components/UI';

import { LinkBadge } from './components/LinkBadge';

interface Props {
  todayItems: PlanItem[];
  dailyCustomTodos: Array<{ id: string; name: string; done: boolean; recurring?: boolean }>;
  statusMap: Map<string, { done: boolean; autoChecked: boolean }>;
  onToggleItem: (id: string) => void;
  onToggleTodo: (id: string) => void;
  onDeleteTodo: (id: string) => void;
  onAddTodo: () => void;
  newTodoText: string;
  onChangeNewTodoText: (text: string) => void;
  checkins: PlanItemCheckin[];
  today: string;
  T: (key: string) => string;
  P: string;
}

export default function PlanTodoList({
  todayItems, dailyCustomTodos, statusMap,
  onToggleItem, onToggleTodo, onDeleteTodo,
  onAddTodo, newTodoText, onChangeNewTodoText,
  checkins, today, T, P,
}: Props) {
  const TH = useTheme();
  const hasItems = todayItems.length > 0 || dailyCustomTodos.length > 0;

  return (
    <>
      {/* Plan items */}
      {!hasItems ? (
        <Text style={{ fontSize: FONT_EMPTY(), color: TH.sub, textAlign: 'center', padding: 24 }}>{T('planNoItems')}</Text>
      ) : (
        <>
          {/* Plan items group header */}
          {todayItems.length > 0 && (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, paddingVertical: 8, paddingHorizontal: 12 }}>
              <ClipboardList size={14} color={P} />
              <Text style={{ fontSize: FONT_SUB(), fontWeight: '600', color: TH.text }}>{T('planTodoList')} ({todayItems.length})</Text>
            </View>
          )}
          {todayItems.map((item, i, arr) => {
            const status = statusMap.get(item.id);
            const done = status?.done ?? false;
            const autoChecked = status?.autoChecked ?? false;
            return (
              <View key={item.id} style={{
                flexDirection: 'row', alignItems: 'center', gap: 12,
                paddingVertical: 10, paddingHorizontal: 12,
                borderBottomWidth: i < arr.length - 1 || dailyCustomTodos.length > 0 ? 1 : 0,
                borderBottomColor: TH.border, opacity: autoChecked ? 0.7 : 1,
              }}>
                <TouchableOpacity onPress={() => onToggleItem(item.id)} style={{ width: 44, height: 44, alignItems: 'center', justifyContent: 'center' }} accessibilityLabel={done ? `${item.name} 取消完成` : `${item.name} 完成`}>
                  <View style={{ width: 22, height: 22, borderRadius: 6, borderWidth: 2, borderColor: done ? P : TH.border, alignItems: 'center', justifyContent: 'center', backgroundColor: done ? P : 'transparent' }}>
                    {done && <Check size={14} color="#fff" />}
                  </View>
                </TouchableOpacity>
                {autoChecked && (
                  <View style={{ backgroundColor: `${COLORS.GREEN}20`, paddingHorizontal: 4, paddingVertical: 1, borderRadius: 4 }}>
                    <Text style={{ fontSize: FONT_TINY(), color: COLORS.GREEN, fontWeight: '600' }}>{T('planAutoChecked')}</Text>
                  </View>
                )}
                {item.status === 'delayed' && !done && (
                  <View style={{ backgroundColor: `${COLORS.ORANGE}20`, paddingHorizontal: 4, paddingVertical: 1, borderRadius: 4 }}>
                    <Text style={{ fontSize: FONT_TINY(), color: COLORS.ORANGE, fontWeight: '600' }}>{T('planStatusDelayed')}</Text>
                  </View>
                )}
                <View style={{ flex: 1, minWidth: 0 }}>
                  <Text style={{ fontSize: FONT_BODY(), fontWeight: '500', color: TH.text }}>{item.name}</Text>
                  <Text style={{ fontSize: FONT_TINY(), color: P, marginTop: 1 }}>
                    {getFrequencySummary(item.frequency ?? { mode: 'daily' }, T, checkins, today, item.id)}
                  </Text>
                  {item.description ? (
                    <Text style={{ fontSize: FONT_BADGE(), color: TH.sub, marginTop: 2 }} numberOfLines={1}>{item.description}</Text>
                  ) : null}
                </View>
                <LinkBadge link={item.link} T={T} P={P} />
              </View>
            );
          })}

          {/* Custom todos group header */}
          {dailyCustomTodos.length > 0 && (
            <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4, paddingVertical: 8, paddingHorizontal: 12, borderTopWidth: todayItems.length > 0 ? 1 : 0, borderTopColor: TH.border }}>
              <Pencil size={14} color={P} />
              <Text style={{ fontSize: FONT_SUB(), fontWeight: '600', color: TH.text }}>{T('planDailyCustomTodos')} ({dailyCustomTodos.length})</Text>
            </View>
          )}
          {/* Custom todos */}
          {dailyCustomTodos.map((todo, i, arr) => (
            <View key={todo.id} style={{
              flexDirection: 'row', alignItems: 'center', gap: 12,
              paddingVertical: 10, paddingHorizontal: 12,
              borderBottomWidth: i < arr.length - 1 ? 1 : 0, borderBottomColor: TH.border,
            }}>
              <TouchableOpacity onPress={() => onToggleTodo(todo.id)} style={{ width: 44, height: 44, alignItems: 'center', justifyContent: 'center' }} accessibilityLabel={todo.done ? `${todo.name} 取消完成` : `${todo.name} 完成`}>
                <View style={{ width: 22, height: 22, borderRadius: 6, borderWidth: 2, borderColor: todo.done ? P : TH.border, alignItems: 'center', justifyContent: 'center', backgroundColor: todo.done ? P : 'transparent' }}>
                  {todo.done && <Check size={14} color="#fff" />}
                </View>
              </TouchableOpacity>
              <View style={{ flex: 1, minWidth: 0, flexDirection: 'row', alignItems: 'center', gap: 6 }}>
                <Text style={{ fontSize: FONT_BODY(), fontWeight: '500', color: TH.text }}>{todo.name}</Text>
                {todo.recurring && <Repeat size={12} color={P} />}
              </View>
              <TouchableOpacity
                onPress={() => {
                  Alert.alert(T('planDeleteCustomTodo'), T('planDeleteCustomTodoConfirm'), [
                    { text: T('commonCancel'), style: 'cancel' },
                    { text: T('commonConfirm'), style: 'destructive', onPress: () => onDeleteTodo(todo.id) },
                  ]);
                }}
                style={{ padding: 4 }}
                accessibilityLabel={`${T('planDeleteCustomTodo')} ${todo.name}`}
              >
                <Trash2 size={16} color={COLORS.RED} />
              </TouchableOpacity>
            </View>
          ))}
        </>
      )}

      {/* Add custom todo */}
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, padding: 12, borderTopWidth: hasItems ? 1 : 0, borderTopColor: TH.border }}>
        <TextInput
          placeholder={T('planAddCustomTodoPlaceholder')}
          placeholderTextColor={TH.sub}
          style={{ flex: 1, borderWidth: 1, borderColor: TH.border, borderRadius: 8, padding: 10, fontSize: FONT_BODY(), color: TH.text, backgroundColor: TH.bg }}
          value={newTodoText}
          onChangeText={onChangeNewTodoText}
          onSubmitEditing={onAddTodo}
          returnKeyType="done"
        />
        <TouchableOpacity onPress={onAddTodo} disabled={!newTodoText.trim()} hitSlop={{ top: 2, bottom: 2, left: 2, right: 2 }} style={{ width: 40, height: 40, borderRadius: 20, backgroundColor: newTodoText.trim() ? P : TH.border, alignItems: 'center', justifyContent: 'center' }} accessibilityLabel={T('planAddCustomTodoPlaceholder')}>
          <Plus size={18} color="#fff" />
        </TouchableOpacity>
      </View>
    </>
  );
}

import { COLORS, getTodayItems, getActivePlan, getTodoItemStatus, computeDailyTodoStats, FONT_TITLE, FONT_BODY, FONT_SUB, FONT_BADGE, dateStr } from '@egoless-do/core';
import { X, CheckCircle2, Check } from 'lucide-react-native';
import React, { useMemo } from 'react';
import {
  View, Text, TouchableOpacity, Modal, ScrollView,
} from 'react-native';

import { useTheme, useT } from '../../components/UI';
import { useAppStore, useShallowStore } from '../../store/useAppStore';


export default function PlanTodoListModal({ onClose }: { onClose: () => void }) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { plans, planItemCheckins, planItems, checkinPlanItem, uncheckinPlanItem } = useShallowStore(s => ({ plans: s.plans, planItemCheckins: s.planItemCheckins, planItems: s.planItems, checkinPlanItem: s.checkinPlanItem, uncheckinPlanItem: s.uncheckinPlanItem }));
  const today = dateStr();

  const activePlan = useMemo(() => getActivePlan(plans ?? []), [plans]);
  const checkins = useMemo(() => planItemCheckins ?? [], [planItemCheckins]);
  const todayItems = useMemo(() => {
    if (!activePlan) return [];
    return getTodayItems(planItems ?? [], activePlan, today, checkins);
  }, [planItems, activePlan, today, checkins]);

  const stats = useMemo(
    () => computeDailyTodoStats(todayItems, [], checkins, today),
    [todayItems, checkins, today],
  );

  return (
    <Modal visible transparent animationType="slide" onRequestClose={onClose}>
      <TouchableOpacity
        activeOpacity={1}
        onPress={onClose}
        style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'flex-end' }}
      >
        <TouchableOpacity activeOpacity={1} onPress={e => e.stopPropagation()}>
          <View style={{
            backgroundColor: TH.bg, borderTopLeftRadius: 20, borderTopRightRadius: 20,
            padding: 20, paddingBottom: 32, maxHeight: '70%',
          }}>
            {/* Header */}
            <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 16 }}>
              <Text style={{ fontWeight: '700', fontSize: FONT_TITLE(), color: TH.text, flex: 1 }}>{T('planTodoList')}</Text>
              <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{today}</Text>
              <TouchableOpacity onPress={onClose} style={{ marginLeft: 12 }}>
                <X size={20} color={TH.sub} />
              </TouchableOpacity>
            </View>

            {todayItems.length === 0 ? (
              <View style={{ alignItems: 'center', padding: 32 }}>
                <CheckCircle2 size={32} color={COLORS.GREEN} style={{ marginBottom: 8 }} />
                <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('planNoTodayTodos')}</Text>
              </View>
            ) : (
              <ScrollView>
                {todayItems.map(item => {
                  const status = getTodoItemStatus(item, checkins, today);
                  const done = status.done;
                  const isManual = item.link === 'manual';
                  return (
                    <TouchableOpacity
                      key={item.id}
                      onPress={() => {
                        if (!isManual) return;
                        done ? uncheckinPlanItem(item.id) : checkinPlanItem(item.id);
                      }}
                      activeOpacity={isManual ? 0.7 : 1}
                      style={{
                        flexDirection: 'row', alignItems: 'center', gap: 12,
                        padding: 14, marginBottom: 8, borderRadius: 12,
                        backgroundColor: done ? `${COLORS.GREEN}10` : TH.card,
                        borderWidth: 1, borderColor: done ? `${COLORS.GREEN}40` : TH.border,
                      }}
                    >
                      {/* Checkbox */}
                      <View style={{
                        width: 22, height: 22, borderRadius: 6,
                        borderWidth: 2, borderColor: done ? COLORS.GREEN : TH.border,
                        alignItems: 'center', justifyContent: 'center',
                        backgroundColor: done ? COLORS.GREEN : 'transparent',
                      }}>
                        {done ? <Check size={14} color="#fff" /> : null}
                      </View>

                      {/* Content */}
                      <View style={{ flex: 1, minWidth: 0 }}>
                        <Text style={{
                          fontSize: FONT_BODY(), fontWeight: '500',
                          color: done ? TH.sub : TH.text,
                          textDecorationLine: done ? 'line-through' : 'none',
                        }}>{item.name}</Text>
                        {item.description ? (
                          <Text style={{ fontSize: FONT_BADGE(), color: TH.sub, marginTop: 2 }} numberOfLines={1}>
                            {item.description}
                          </Text>
                        ) : null}
                      </View>

                      {/* Link badge */}
                      {!isManual && (
                        <View style={{ backgroundColor: `${P}15`, paddingHorizontal: 8, paddingVertical: 2, borderRadius: 6 }}>
                          <Text style={{ fontSize: FONT_BADGE(), color: P }}>
                            {T(`planLink${item.link.charAt(0).toUpperCase() + item.link.slice(1)}`)}
                          </Text>
                        </View>
                      )}
                    </TouchableOpacity>
                  );
                })}
                <Text style={{ textAlign: 'center', fontSize: FONT_SUB(), color: TH.sub, marginTop: 8 }}>
                  {stats.planItemsDone}/{stats.planItemsTotal} {T('planProgress')}
                </Text>
              </ScrollView>
            )}
          </View>
        </TouchableOpacity>
      </TouchableOpacity>
    </Modal>
  );
}

import { COLORS, dateStr, FONT_SUB, FONT_BADGE , FONT_SMALL } from '@egoless-do/core';
import type { PlanItem, PlanItemCheckin, Theme } from '@egoless-do/core';
import React, { useMemo, useState } from 'react';
import { View, Text, TouchableOpacity, LayoutChangeEvent } from 'react-native';

interface ItemHeatmapProps {
  item: PlanItem;
  checkins: PlanItemCheckin[];
  TH: Theme;
  T: (k: string) => string;
}

export const ItemHeatmap = React.memo(function ItemHeatmap({ item, checkins, TH, T }: ItemHeatmapProps) {
  const [containerWidth, setContainerWidth] = useState(0);
  const cellSize = containerWidth > 0 ? Math.floor(containerWidth / 7) : 0;

  // Pre-build done dates set for this item
  const doneDates = useMemo(() => {
    const set = new Set<string>();
    for (const c of checkins) {
      if (c.planItemId === item.id && c.done && !c.deleted) {
        set.add(c.date);
      }
    }
    return set;
  }, [checkins, item.id]);

  // Build weeks grid
  const { weeks } = useMemo(() => {
    const [sy, sm, sd] = item.startDate.split('-').map(Number);
    const [ey, em, ed] = item.endDate.split('-').map(Number);
    const start = new Date(sy, sm - 1, sd);
    const end = new Date(ey, em - 1, ed);
    const startDay = start.getDay();

    const dates: string[] = [];
    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      dates.push(dateStr(d));
    }

    const weeks: (string | null)[][] = [];
    let week: (string | null)[] = new Array<string | null>(startDay).fill(null);

    for (const ds of dates) {
      week.push(ds);
      if (week.length === 7) { weeks.push(week); week = []; }
    }
    if (week.length > 0) { while (week.length < 7) week.push(null); weeks.push(week); }

    return { weeks };
  }, [item.startDate, item.endDate]);

  const weekLabels = useMemo(() => [
    T('weekdaySun'), T('weekdayMon'), T('weekdayTue'), T('weekdayWed'),
    T('weekdayThu'), T('weekdayFri'), T('weekdaySat'),
  ], [T]);

  const onLayout = (e: LayoutChangeEvent) => {
    setContainerWidth(e.nativeEvent.layout.width);
  };

  if (cellSize <= 0) {
    return <View onLayout={onLayout} style={{ width: '100%' }} />;
  }

  return (
    <View onLayout={onLayout}>
      {/* Weekday labels row */}
      <View style={{ flexDirection: 'row', marginBottom: 4 }}>
        {weekLabels.map((label, i) => (
          <View key={i} style={{ width: cellSize }}>
            <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, textAlign: 'center' }}>{label}</Text>
          </View>
        ))}
      </View>

      {/* Grid */}
      <View>
        {weeks.map((w, wi) => (
          <View key={wi} style={{ flexDirection: 'row' }}>
            {w.map((ds, di) => {
              const dayNum = ds ? parseInt(ds.slice(8), 10) : 0;
              const done = ds ? doneDates.has(ds) : false;
              return (
                <View key={di} style={{ width: cellSize, height: cellSize, padding: 2 }}>
                  {ds ? (
                    <View style={{
                      flex: 1, borderRadius: 6, alignItems: 'center', justifyContent: 'center',
                      backgroundColor: done ? COLORS.GREEN : `${TH.border}60`,
                    }}>
                      <Text style={{ fontSize: FONT_SMALL(), fontWeight: '500', color: done ? '#fff' : TH.text }}>{dayNum}</Text>
                    </View>
                  ) : null}
                </View>
              );
            })}
          </View>
        ))}
      </View>

      {/* Legend */}
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8, marginTop: 8 }}>
        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('heatmapLess')}</Text>
        {[`${TH.border}60`, COLORS.GREEN].map((c, i) => (
          <View key={i} style={{ width: 14, height: 14, borderRadius: 4, backgroundColor: c }} />
        ))}
        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>{T('heatmapMore')}</Text>
      </View>
    </View>
  );
});

import type {PlanItemPriority, UnifiedPlanItemForm, CheckinFrequency} from '@egoless-do/core';
import { FONT_SMALL, FONT_BODY, dateStr , FREQUENCY_OPTIONS, createDefaultFrequency } from '@egoless-do/core';
import React, { useState, useCallback, useEffect } from 'react';
import {
  View, Text, TextInput, TouchableOpacity, ScrollView, StyleSheet,
} from 'react-native';

import { useTheme } from '../../../components/UI';

export function validatePlanItemForm(
  form: UnifiedPlanItemForm,
  opts?: { requireTargetMetric?: boolean },
): Record<string, string> {
  const errors: Record<string, string> = {};
  if (!form.name.trim()) errors.name = '请输入任务名称';
  if (opts?.requireTargetMetric && !form.targetMetric?.trim()) errors.targetMetric = '请输入任务目标';
  if (form.endDate < form.startDate) errors.date = '结束日期不能早于开始日期';
  return errors;
}

export type { UnifiedPlanItemForm as PlanItemFormValue };

interface PlanItemFormProps {
  initialValues?: Partial<UnifiedPlanItemForm>;
  showTargetMetric?: boolean;
  showFrequency?: boolean;
  onChange: (form: UnifiedPlanItemForm) => void;
  onDatePress?: (field: 'start' | 'end') => void;
  errors?: Record<string, string>;
}

const PRIORITY_OPTIONS: { value: PlanItemPriority; label: string; color: string }[] = [
  { value: 'high', label: '高', color: '#EF4444' },
  { value: 'medium', label: '中', color: '#F59E0B' },
  { value: 'low', label: '低', color: '#10B981' },
];

const FREQ_MODE_LABELS: Record<string, string> = {
  daily: '每天',
  interval: '间隔',
  weekly: '每周',
  weekly_fixed: '每周固定',
  monthly: '每月',
  monthly_fixed: '每月固定',
};

// These are computed at render time inside the component to avoid stale dates after midnight

export function PlanItemForm({
  initialValues,
  showTargetMetric,
  showFrequency,
  onChange,
  onDatePress,
  errors = {},
}: PlanItemFormProps) {
  const TH = useTheme();
  const today = dateStr();
  const defaultEnd = (() => { const d = new Date(); d.setDate(d.getDate() + 30); return dateStr(d); })();

  const [name, setName] = useState(initialValues?.name ?? '');
  const [description, setDescription] = useState(initialValues?.description ?? '');
  const [targetMetric, setTargetMetric] = useState(initialValues?.targetMetric ?? '');
  const [startDate, setStartDate] = useState(initialValues?.startDate ?? today);
  const [endDate, setEndDate] = useState(initialValues?.endDate ?? defaultEnd);
  const [priority, setPriority] = useState<PlanItemPriority>(initialValues?.priority ?? 'medium');
  const [frequency, setFrequency] = useState<CheckinFrequency>(initialValues?.frequency ?? { mode: 'daily' });
  const [draftInputs, setDraftInputs] = useState<Record<string, string>>({});

  useEffect(() => {
    setDraftInputs({});
  }, [frequency.mode]);

  // Form state is self-managed after initial mount.
  // Parent should use a key prop to force remount when switching contexts (e.g. different reflection).

  const emitChange = useCallback((patch: Partial<UnifiedPlanItemForm>) => {
    const next = { name, description, targetMetric, startDate, endDate, priority, frequency, ...patch };
    onChange(next);
  }, [name, description, targetMetric, startDate, endDate, priority, frequency, onChange]);

  const handleNameChange = useCallback((v: string) => {
    setName(v);
    emitChange({ name: v });
  }, [emitChange]);

  const handleDescChange = useCallback((v: string) => {
    setDescription(v);
    emitChange({ description: v });
  }, [emitChange]);

  const handleMetricChange = useCallback((v: string) => {
    setTargetMetric(v);
    emitChange({ targetMetric: v });
  }, [emitChange]);

  const handlePriorityChange = useCallback((p: PlanItemPriority) => {
    setPriority(p);
    emitChange({ priority: p });
  }, [emitChange]);

  const P = TH.primary;

  return (
    <>
      {/* 任务名称 */}
      <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>
        任务名称 *
      </Text>
      <TextInput
        value={name}
        onChangeText={handleNameChange}
        placeholder="输入任务名称"
        placeholderTextColor={TH.sub}
        maxLength={10}
        style={{
          borderWidth: 1, borderColor: errors.name ? '#EF4444' : TH.border,
          borderRadius: 8, padding: 10, marginBottom: 12,
          color: TH.text, backgroundColor: TH.card, fontSize: FONT_BODY(),
        }}
      />
      {errors.name && (
        <Text style={styles.errorText}>
          {errors.name}
        </Text>
      )}

      {/* 任务目标 */}
      {showTargetMetric && (
        <>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>
            任务目标 *
          </Text>
          <TextInput
            value={targetMetric}
            onChangeText={handleMetricChange}
            placeholder="例如：每周复盘3次"
            placeholderTextColor={TH.sub}
            style={{
              borderWidth: 1, borderColor: errors.targetMetric ? '#EF4444' : TH.border,
              borderRadius: 8, padding: 10, marginBottom: 12,
              color: TH.text, backgroundColor: TH.card, fontSize: FONT_BODY(),
            }}
          />
          {errors.targetMetric && (
            <Text style={styles.errorText}>
              {errors.targetMetric}
            </Text>
          )}
        </>
      )}

      {/* 任务描述 */}
      <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>任务描述</Text>
      <TextInput
        value={description}
        onChangeText={handleDescChange}
        placeholder="添加任务描述..."
        placeholderTextColor={TH.sub}
        multiline
        numberOfLines={2}
        style={{
          borderWidth: 1, borderColor: TH.border, borderRadius: 8, padding: 10,
          marginBottom: 12, color: TH.text, backgroundColor: TH.card,
          fontSize: FONT_BODY(), minHeight: 60, textAlignVertical: 'top',
        }}
      />

      {/* 日期 */}
      <View style={styles.dateRow}>
        <View style={{ flex: 1 }}>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>开始日期</Text>
          <TouchableOpacity
            onPress={() => onDatePress?.('start')}
            style={{
              borderWidth: 1, borderColor: TH.border, borderRadius: 8, padding: 10, marginBottom: 12,
              backgroundColor: TH.card,
            }}
          >
            <Text style={{ color: TH.text, fontSize: FONT_BODY() }}>{startDate}</Text>
          </TouchableOpacity>
        </View>
        <View style={{ flex: 1 }}>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>结束日期</Text>
          <TouchableOpacity
            onPress={() => onDatePress?.('end')}
            style={{
              borderWidth: 1, borderColor: TH.border, borderRadius: 8, padding: 10, marginBottom: 12,
              backgroundColor: TH.card,
            }}
          >
            <Text style={{ color: TH.text, fontSize: FONT_BODY() }}>{endDate}</Text>
          </TouchableOpacity>
        </View>
      </View>
      {errors.date && (
        <Text style={styles.errorText}>
          {errors.date}
        </Text>
      )}

      {/* 打卡频率 */}
      {showFrequency && (
        <>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>打卡频率</Text>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.frequencyScrollView} contentContainerStyle={styles.frequencyScrollViewContent}>
            {FREQUENCY_OPTIONS.map(opt => {
              const active = (frequency.mode ?? 'daily') === opt.mode;
              return (
                <TouchableOpacity
                  key={opt.mode}
                  onPress={() => {
                    const f = opt.mode === 'daily' ? { mode: 'daily' as const } : createDefaultFrequency(opt.mode);
                    setFrequency(f);
                    emitChange({ frequency: f });
                  }}
                  style={{
                    paddingHorizontal: 12, paddingVertical: 6, borderRadius: 8,
                    backgroundColor: active ? P : TH.card,
                    borderWidth: 1, borderColor: active ? P : TH.border,
                  }}
                >
                  <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SMALL(), fontWeight: active ? '600' : '400' }}>
                    {FREQ_MODE_LABELS[opt.mode] ?? opt.mode}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </ScrollView>

          {/* 每N天 */}
          {frequency.mode === 'interval' && (
            <View style={styles.frequencyRow}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>每</Text>
              <TextInput
                value={draftInputs.interval ?? String(frequency.every ?? '')}
                onChangeText={v => {
                  setDraftInputs(prev => ({ ...prev, interval: v }));
                  const n = parseInt(v);
                  if (!isNaN(n) && n > 0) {
                    const f: CheckinFrequency = { mode: 'interval', every: n };
                    setFrequency(f);
                    emitChange({ frequency: f });
                  }
                }}
                keyboardType="number-pad"
                style={[styles.frequencyInput, { borderColor: TH.border, color: TH.text, backgroundColor: TH.card }]}
              />
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>天</Text>
            </View>
          )}

          {/* 每周N次 */}
          {frequency.mode === 'weekly' && (
            <View style={styles.frequencyRow}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>每周</Text>
              <TextInput
                value={draftInputs.weekly ?? String(frequency.target ?? '')}
                onChangeText={v => {
                  setDraftInputs(prev => ({ ...prev, weekly: v }));
                  const n = parseInt(v);
                  if (!isNaN(n) && n >= 1 && n <= 7) {
                    const f: CheckinFrequency = { mode: 'weekly', target: n };
                    setFrequency(f);
                    emitChange({ frequency: f });
                  }
                }}
                keyboardType="number-pad"
                style={[styles.frequencyInput, { borderColor: TH.border, color: TH.text, backgroundColor: TH.card }]}
              />
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>次</Text>
            </View>
          )}

          {/* 固定星期 */}
          {frequency.mode === 'weekly_fixed' && (
            <View style={styles.weekDayRow}>
              {[0, 1, 2, 3, 4, 5, 6].map(d => {
                const active = frequency.days.includes(d);
                const label = ['日', '一', '二', '三', '四', '五', '六'][d];
                return (
                  <TouchableOpacity
                    key={d}
                    onPress={() => {
                      const days = active ? frequency.days.filter(x => x !== d) : [...frequency.days, d].sort();
                      const f: CheckinFrequency = { mode: 'weekly_fixed', days };
                      setFrequency(f);
                      emitChange({ frequency: f });
                    }}
                    style={[styles.dayCircle, { backgroundColor: active ? P : TH.card, borderColor: active ? P : TH.border }]}
                  >
                    <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SMALL(), fontWeight: active ? '700' : '400' }}>{label}</Text>
                  </TouchableOpacity>
                );
              })}
            </View>
          )}

          {/* 每月N次 */}
          {frequency.mode === 'monthly' && (
            <View style={styles.frequencyRow}>
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>每月</Text>
              <TextInput
                value={draftInputs.monthly ?? String(frequency.target ?? '')}
                onChangeText={v => {
                  setDraftInputs(prev => ({ ...prev, monthly: v }));
                  const n = parseInt(v);
                  if (!isNaN(n) && n >= 1 && n <= 31) {
                    const f: CheckinFrequency = { mode: 'monthly', target: n };
                    setFrequency(f);
                    emitChange({ frequency: f });
                  }
                }}
                keyboardType="number-pad"
                style={[styles.frequencyInput, { borderColor: TH.border, color: TH.text, backgroundColor: TH.card }]}
              />
              <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>次</Text>
            </View>
          )}

          {/* 固定日期 */}
          {frequency.mode === 'monthly_fixed' && (
            <View style={styles.monthDayGrid}>
              {Array.from({ length: 31 }, (_, i) => i + 1).map(d => {
                const active = frequency.dates.includes(d);
                return (
                  <TouchableOpacity
                    key={d}
                    onPress={() => {
                      const dates = active ? frequency.dates.filter(x => x !== d) : [...frequency.dates, d].sort((a, b) => a - b);
                      const f: CheckinFrequency = { mode: 'monthly_fixed', dates };
                      setFrequency(f);
                      emitChange({ frequency: f });
                    }}
                    style={[styles.dayCircle, { backgroundColor: active ? P : TH.card, borderColor: active ? P : TH.border }]}
                  >
                    <Text style={{ color: active ? '#fff' : TH.sub, fontSize: FONT_SMALL(), fontWeight: active ? '700' : '400' }}>{d}</Text>
                  </TouchableOpacity>
                );
              })}
            </View>
          )}
        </>
      )}

      {/* 优先级 */}
      <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 6, fontWeight: '600' }}>优先级</Text>
      <View style={styles.priorityRow}>
        {PRIORITY_OPTIONS.map(p => (
          <TouchableOpacity
            key={p.value}
            onPress={() => handlePriorityChange(p.value)}
            style={[styles.priorityButtonBase, {
              borderColor: priority === p.value ? p.color : TH.border,
              backgroundColor: priority === p.value ? `${p.color}20` : 'transparent',
            }]}
          >
            <Text style={{
              color: priority === p.value ? p.color : TH.text,
              fontWeight: priority === p.value ? '600' : '400',
              fontSize: FONT_SMALL(),
            }}>
              {p.label}
            </Text>
          </TouchableOpacity>
        ))}
      </View>
    </>
  );
}

