import { FONT_TITLE, FONT_BODY, FONT_SUB, type BodyGoal, type BodyTrainingPlan, type BodyPlan, type DayOverride, type ExerciseDef, type BodyCheckin } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity, Modal } from 'react-native';

import { styles } from './BodyDashboardStyles';
import AdjustExerciseModal from './modals/AdjustExerciseModal';
import AssessmentModal from './modals/AssessmentModal';
import BodyCheckinModal from './modals/BodyCheckinModal';
import DayActionSheet from './modals/DayActionSheet';
import GoalEditLightModal from './modals/GoalEditLightModal';
import GoalEditModal from './modals/GoalEditModal';
import QuickSwapModal from './modals/QuickSwapModal';
import WeightRecordModal from './modals/WeightRecordModal';
import WeightTrendModal from './modals/WeightTrendModal';
import CelebrationOverlay from './screens/CelebrationOverlay';

interface BodyDashboardModalsProps {
  TH: { primary: string; sub: string; bg: string; card: string; cardSolid: string; border: string; text: string };
  T: (key: string, params?: Record<string, string | number>) => string;
  todayPlan?: BodyPlan;
  activeGoal?: BodyGoal;
  activeTrainingPlan?: BodyTrainingPlan;
  profile: Record<string, unknown>;
  todayExercises?: ExerciseDef[];
  selectedDay: number | null;
  selectedDayIsRest: boolean;
  selectedDayOverride: DayOverride | undefined;
  // Visible states
  showAssessment: boolean; showGoalEdit: boolean; showCheckin: boolean;
  showWeightRecord: boolean; showWeightTrend: boolean; showQuickSwap: boolean;
  showAdjustExercise: boolean; showDayAction: boolean; showGoalEditLight: boolean;
  showDaySwapPicker: boolean; showCelebration: boolean;
  // Close handlers
  onCloseAssessment: () => void; onCloseGoalEdit: () => void;
  onCloseCheckin: () => void; onCloseWeightRecord: () => void;
  onCloseWeightTrend: () => void; onCloseQuickSwap: () => void;
  onCloseAdjustExercise: () => void; onCloseDayAction: () => void;
  onCloseGoalEditLight: () => void; onCloseDaySwapPicker: () => void;
  onCloseCelebration: () => void;
  // Save handlers
  onSaveAssessment: (text: string, tags: string[]) => void;
  onSaveGoal: (data: Partial<BodyGoal>) => void;
  onSaveCheckin: (data: { date: string; energy: number; pain: number; comfort: number; sleep: number; tags: string[]; note?: string }) => void;
  onSaveWeight: (data: { date: string; weight: number; bodyFat?: number }) => void;
  onSwapConfirm: (sportKey: string, exercises?: ExerciseDef[]) => void;
  onAdjustConfirm: (adjustments: { exerciseId: string; sets: number; reps: number; durationSec?: number }[]) => void;
  onDaySkip: () => void;
  onOpenQuickSwap: () => void;
  onOpenDaySwapPicker: () => void;
  onOpenAdjustExercise: () => void;
  onDaySwapConfirm: (targetDay: number) => void;
  onSaveGoalLight: (data: { strategy?: string; targetWeight?: number; targetBodyFat?: number; goalNote?: string }) => void;
  // Other
  checkinHistory?: { deleted?: boolean; weight?: number; date: string }[];
  celebrationData: { planName: string; totalDays: number; completedDays: number; totalDurationMin: number; totalCalories: number } | null;
}

export default function BodyDashboardModals({
  TH, T, todayPlan, activeGoal, activeTrainingPlan, profile, todayExercises,
  selectedDay, selectedDayIsRest, selectedDayOverride,
  showAssessment, showGoalEdit, showCheckin, showWeightRecord, showWeightTrend,
  showQuickSwap, showAdjustExercise, showDayAction, showGoalEditLight,
  showDaySwapPicker, showCelebration,
  onCloseAssessment, onCloseGoalEdit, onCloseCheckin, onCloseWeightRecord,
  onCloseWeightTrend, onCloseQuickSwap, onCloseAdjustExercise, onCloseDayAction,
  onCloseGoalEditLight, onCloseDaySwapPicker, onCloseCelebration,
  onSaveAssessment, onSaveGoal, onSaveCheckin, onSaveWeight,
  onSwapConfirm, onAdjustConfirm, onDaySkip, onOpenQuickSwap, onOpenDaySwapPicker, onOpenAdjustExercise, onDaySwapConfirm,
  onSaveGoalLight,
  checkinHistory, celebrationData,
}: BodyDashboardModalsProps) {
  return (
    <>
      <AssessmentModal visible={showAssessment} TH={TH} T={T} profile={profile} onClose={onCloseAssessment} onSave={onSaveAssessment} />
      <GoalEditModal visible={showGoalEdit} TH={TH} T={T} goal={activeGoal} profile={profile} onClose={onCloseGoalEdit} onSave={onSaveGoal} />
      <BodyCheckinModal visible={showCheckin} TH={TH} T={T} todayPlan={todayPlan} onClose={onCloseCheckin} onSave={onSaveCheckin} />
      <WeightRecordModal visible={showWeightRecord} TH={TH} T={T} currentWeight={profile.weight as number | undefined} currentBodyFat={profile.bodyFat as number | undefined} onClose={onCloseWeightRecord} onSave={onSaveWeight} />
      <WeightTrendModal visible={showWeightTrend} TH={TH} T={T} checkins={checkinHistory ?? []} onClose={onCloseWeightTrend} />

      {/* Override modals */}
      <QuickSwapModal visible={showQuickSwap} onClose={onCloseQuickSwap} onConfirm={onSwapConfirm} TH={TH} T={T} />
      {todayExercises && (
        <AdjustExerciseModal visible={showAdjustExercise} onClose={onCloseAdjustExercise} onConfirm={onAdjustConfirm} exercises={todayExercises} TH={TH} T={T} />
      )}
      <DayActionSheet
        visible={showDayAction}
        onClose={onCloseDayAction}
        dayLabel={selectedDay ? T(`bodyWeek${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][selectedDay - 1]}`) : ''}
        isRest={selectedDayIsRest}
        hasOverride={!!selectedDayOverride}
        onSwap={() => { onCloseDayAction(); onOpenQuickSwap(); }}
        onSkip={onDaySkip}
        onSwapDays={() => { onCloseDayAction(); onOpenDaySwapPicker(); }}
        onAdjust={() => { onCloseDayAction(); onOpenAdjustExercise(); }}
        TH={TH} T={T}
      />
      {activeTrainingPlan && (
        <GoalEditLightModal
          visible={showGoalEditLight}
          onClose={onCloseGoalEditLight}
          onConfirm={onSaveGoalLight}
          initialStrategy={activeTrainingPlan.strategy}
          initialTargetWeight={activeTrainingPlan.targetWeight}
          initialTargetBodyFat={activeTrainingPlan.targetBodyFat}
          initialGoalNote={activeTrainingPlan.goalNote}
          TH={TH} T={T}
        />
      )}

      {/* Day swap picker modal */}
      <Modal visible={showDaySwapPicker} transparent animationType="fade">
        <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,.5)', justifyContent: 'center', alignItems: 'center' }}>
          <View style={{ backgroundColor: TH.cardSolid, borderRadius: 20, padding: 24, width: '80%', maxWidth: 320 }}>
            <Text style={{ fontSize: FONT_TITLE(), fontWeight: '700', color: TH.text, marginBottom: 16, textAlign: 'center' }}>
              {T('bodySwapDays')}
            </Text>
            {[1,2,3,4,5,6,7].filter(d => d !== selectedDay).map(d => (
              <TouchableOpacity
                key={d}
                onPress={() => onDaySwapConfirm(d)}
                style={{ paddingVertical: 14, paddingHorizontal: 20, borderRadius: 12, marginBottom: 8, backgroundColor: `${TH.primary}15`, borderWidth: 1, borderColor: `${TH.primary}30` }}
              >
                <Text style={{ fontSize: FONT_BODY(), color: TH.text, fontWeight: '600', textAlign: 'center' }}>
                  {T(`bodyWeek${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][d - 1]}`)}
                </Text>
              </TouchableOpacity>
            ))}
            <TouchableOpacity
              onPress={onCloseDaySwapPicker}
              style={{ paddingVertical: 12, alignItems: 'center', marginTop: 8 }}
            >
              <Text style={{ fontSize: FONT_BODY(), color: TH.sub }}>{T('commonCancel')}</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>

      {celebrationData && (
        <CelebrationOverlay
          visible={showCelebration}
          TH={TH} T={T}
          data={celebrationData}
          onDismiss={onCloseCelebration}
        />
      )}
    </>
  );
}

import { FONT_BODY, FONT_SUB, FONT_SMALL, FONT_STAT_CARD, FONT_TINY, type CheckinEntry, type Theme } from '@egoless-do/core';
import { TrendingDown, TrendingUp, Minus, ChevronLeft, ChevronRight } from 'lucide-react-native';
import React, { useState, useRef, useMemo } from 'react';
import { View, Text, Dimensions, TouchableOpacity, FlatList } from 'react-native';

const SCREEN_WIDTH = Dimensions.get('window').width;
const CHART_HEIGHT = 180;
const CHART_PADDING = 30; // space for weight labels above points

interface Props {
  TH: Theme;
  T: (key: string) => string;
  checkins: CheckinEntry[];
}

interface MonthData {
  month: string;      // "2026-07"
  label: string;       // "7月" or "2026年7月"
  records: CheckinEntry[];
  minW: number;
  maxW: number;
}

export default function WeightTrendChart({ TH, T, checkins }: Props) {
  const validRecords = checkins
    .filter(r => !r.deleted && r.weight != null && r.weight > 0)
    .sort((a, b) => a.date.localeCompare(b.date));

  // Group by month — must be called before early return (hooks rule)
  const months = useMemo(() => {
    const map = new Map<string, CheckinEntry[]>();
    for (const r of validRecords) {
      const m = r.date.slice(0, 7); // "2026-07"
      if (!map.has(m)) map.set(m, []);
      map.get(m)!.push(r);
    }
    const result: MonthData[] = [];
    for (const [month, records] of map) {
      const weights = records.map(r => r.weight);
      const [year, mon] = month.split('-');
      result.push({
        month,
        label: `${parseInt(mon)}月`,
        records,
        minW: Math.min(...weights),
        maxW: Math.max(...weights),
      });
    }
    return result;
  }, [validRecords]);

  const [currentIndex, setCurrentIndex] = useState(0);
  const flatListRef = useRef<FlatList>(null);

  if (validRecords.length === 0) {
    return (
      <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 16 }}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text, marginBottom: 12 }}>{T('bodyWeightTrend')}</Text>
        <View style={{ paddingVertical: 24, alignItems: 'center' }}>
          <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>{T('bodyWeightNoData')}</Text>
        </View>
      </View>
    );
  }

  // Trend direction (global)
  const first = validRecords[0].weight;
  const last = validRecords[validRecords.length - 1].weight;
  const diff = last - first;
  const TrendIcon = diff > 0.1 ? TrendingUp : diff < -0.1 ? TrendingDown : Minus;
  const trendColor = diff > 0.1 ? '#ef4444' : diff < -0.1 ? '#10b981' : TH.sub;

  const currentMonth = months[currentIndex];

  const handlePrev = () => {
    if (currentIndex > 0) {
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      flatListRef.current?.scrollToIndex({ index: newIndex, animated: true });
    }
  };

  const handleNext = () => {
    if (currentIndex < months.length - 1) {
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      flatListRef.current?.scrollToIndex({ index: newIndex, animated: true });
    }
  };

  const renderMonthPage = ({ item, index }: { item: MonthData; index: number }) => {
    const range = item.maxW - item.minW || 1;
    const isActive = index === currentIndex;
    const chartWidth = SCREEN_WIDTH - 64; // padding
    const pointSpacing = item.records.length > 1 ? chartWidth / (item.records.length - 1) : chartWidth;

    // Calculate point positions
    const points = item.records.map((r, i) => ({
      x: i * pointSpacing,
      y: CHART_HEIGHT - ((r.weight - item.minW) / range) * (CHART_HEIGHT - CHART_PADDING) - CHART_PADDING / 2,
      weight: r.weight,
      date: r.date,
    }));

    return (
      <View style={{ width: SCREEN_WIDTH - 32, paddingHorizontal: 4 }}>
        {/* Line chart */}
        <View style={{ height: CHART_HEIGHT + 40, position: 'relative' }}>
          {/* Line segments */}
          {points.map((point, i) => {
            if (i === 0) return null;
            const prevPoint = points[i - 1];
            const dx = point.x - prevPoint.x;
            const dy = point.y - prevPoint.y;
            const length = Math.sqrt(dx * dx + dy * dy);
            const angle = Math.atan2(dy, dx) * (180 / Math.PI);

            return (
              <View
                key={`line-${i}`}
                style={{
                  position: 'absolute',
                  left: prevPoint.x,
                  top: prevPoint.y,
                  width: length,
                  height: 3,
                  backgroundColor: isActive ? '#10b981' : '#10b98160',
                  transform: [{ rotate: `${angle}deg` }],
                  transformOrigin: '0 0',
                }}
              />
            );
          })}

          {/* Data points with weight labels */}
          {points.map((point, i) => {
            const isLast = i === points.length - 1;
            return (
              <React.Fragment key={`point-${i}`}>
                {/* Weight label above point */}
                <Text style={{
                  position: 'absolute',
                  left: point.x - 18,
                  top: point.y - 22,
                  fontSize: FONT_SMALL(),
                  color: isActive ? TH.text : TH.sub,
                  fontWeight: isLast ? '700' : '600',
                  width: 36,
                  textAlign: 'center',
                }}>
                  {String(point.weight)}
                </Text>
                {/* Point dot */}
                <View style={{
                  position: 'absolute',
                  left: point.x - 6,
                  top: point.y - 6,
                  width: isLast ? 14 : 12,
                  height: isLast ? 14 : 12,
                  borderRadius: isLast ? 7 : 6,
                  backgroundColor: isLast ? '#10b981' : (isActive ? '#10b98180' : '#10b98140'),
                  borderWidth: isLast ? 3 : 0,
                  borderColor: '#fff',
                }} />
              </React.Fragment>
            );
          })}
        </View>

        {/* X-axis: day numbers */}
        <View style={{ flexDirection: 'row', marginTop: 4 }}>
          {item.records.map((r) => (
            <View key={r.date} style={{ flex: 1, alignItems: 'center' }}>
              <Text style={{ fontSize: FONT_TINY(), color: TH.sub }}>
                {r.date.slice(8)}
              </Text>
            </View>
          ))}
        </View>
      </View>
    );
  };

  return (
    <View style={{ backgroundColor: TH.card, borderRadius: 16, padding: 16, marginBottom: 16 }}>
      {/* Header */}
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '700', color: TH.text }}>{T('bodyWeightTrend')}</Text>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 4 }}>
          <TrendIcon size={14} color={trendColor} />
          <Text style={{ fontSize: FONT_SMALL(), color: trendColor }}>
            {diff > 0 ? '+' : ''}{diff.toFixed(1)}{T('bodyUnitKg')}
          </Text>
        </View>
      </View>

      {/* Latest weight */}
      <View style={{ flexDirection: 'row', alignItems: 'baseline', gap: 4, marginBottom: 12 }}>
        <Text style={{ fontSize: FONT_STAT_CARD(), fontWeight: '900', color: TH.text }}>{last}</Text>
        <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>{T('bodyUnitKg')}</Text>
      </View>

      {/* Month navigator */}
      <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginBottom: 8 }}>
        <TouchableOpacity onPress={handlePrev} disabled={currentIndex <= 0} style={{ padding: 4, opacity: currentIndex <= 0 ? 0.3 : 1 }}>
          <ChevronLeft size={18} color={TH.text} />
        </TouchableOpacity>
        <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.text }}>{currentMonth.month}</Text>
        <TouchableOpacity onPress={handleNext} disabled={currentIndex >= months.length - 1} style={{ padding: 4, opacity: currentIndex >= months.length - 1 ? 0.3 : 1 }}>
          <ChevronRight size={18} color={TH.text} />
        </TouchableOpacity>
      </View>

      {/* Swipeable month chart */}
      <FlatList
        ref={flatListRef}
        data={months}
        renderItem={renderMonthPage}
        keyExtractor={(item) => item.month}
        horizontal
        pagingEnabled
        showsHorizontalScrollIndicator={false}
        initialScrollIndex={months.length - 1}
        getItemLayout={(_, index) => ({ length: SCREEN_WIDTH - 32, offset: (SCREEN_WIDTH - 32) * index, index })}
        onMomentumScrollEnd={(e) => {
          const index = Math.round(e.nativeEvent.contentOffset.x / (SCREEN_WIDTH - 32));
          setCurrentIndex(index);
        }}
      />

      {/* Page indicator dots */}
      {months.length > 1 && (
        <View style={{ flexDirection: 'row', justifyContent: 'center', gap: 6, marginTop: 8 }}>
          {months.map((m, i) => (
            <View key={m.month} style={{
              width: i === currentIndex ? 16 : 6, height: 6, borderRadius: 3,
              backgroundColor: i === currentIndex ? '#10b981' : TH.border,
            }} />
          ))}
        </View>
      )}
    </View>
  );
}

import { FONT_TITLE, FONT_SUB, FONT_BADGE, type Theme } from '@egoless-do/core';
import { ChevronDown } from 'lucide-react-native';
import React, { useState, useRef, useCallback } from 'react';
import { View, Text, TouchableOpacity, Animated, StyleSheet } from 'react-native';

interface CollapsibleSectionProps {
  title: string;
  icon?: string;
  color?: string;            // accent color for the header
  TH: Theme;
  defaultExpanded?: boolean;
  badge?: string;            // optional badge text (e.g. "3/5")
  children: React.ReactNode;
}

export default function CollapsibleSection({
  title, icon, color = '#f59e0b', TH,
  defaultExpanded = true, badge, children,
}: CollapsibleSectionProps) {
  const [expanded, setExpanded] = useState(defaultExpanded);
  const animValue = useRef(new Animated.Value(defaultExpanded ? 1 : 0)).current;
  const [contentHeight, setContentHeight] = useState(0);
  const heightRef = useRef(0);

  // Always update content height when layout changes
  const onContentLayout = useCallback((e: { nativeEvent: { layout: { height: number } } }) => {
    const h = e.nativeEvent.layout.height;
    if (Math.abs(h - heightRef.current) > 1) {
      heightRef.current = h;
      setContentHeight(h);
    }
  }, []);

  const toggle = useCallback(() => {
    const toValue = expanded ? 0 : 1;
    Animated.spring(animValue, {
      toValue,
      useNativeDriver: false,
      friction: 9,
      tension: 50,
    }).start();
    setExpanded(!expanded);
  }, [expanded, animValue]);

  // Chevron rotation: 0° when collapsed, 180° when expanded
  const chevronRotation = animValue.interpolate({
    inputRange: [0, 1],
    outputRange: ['0deg', '180deg'],
  });

  // Content max-height: animated between 0 and contentHeight
  const maxHeight = animValue.interpolate({
    inputRange: [0, 1],
    outputRange: [0, contentHeight || 400],
  });

  // Opacity for child fade-in
  const opacity = animValue.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [0, 0, 1],
  });

  return (
    <View style={[styles.container, { backgroundColor: TH.card, borderColor: TH.border }]}>
      {/* Header */}
      <TouchableOpacity
        onPress={toggle}
        activeOpacity={0.7}
        style={[styles.header, { borderBottomColor: expanded ? `${color}20` : 'transparent' }]}
      >
        <View style={styles.headerLeft}>
          {icon ? <Text style={{ fontSize: 18, marginRight: 8 }}>{icon}</Text> : null}
          <Text style={[styles.title, { color: TH.text }]}>{title}</Text>
          {badge ? (
            <View style={[styles.badge, { backgroundColor: `${color}20` }]}>
              <Text style={[styles.badgeText, { color }]}>{badge}</Text>
            </View>
          ) : null}
        </View>
        <Animated.View style={{ transform: [{ rotate: chevronRotation }] }}>
          <ChevronDown size={20} color={TH.sub} />
        </Animated.View>
      </TouchableOpacity>

      {/* Collapsible content */}
      <Animated.View style={[styles.content, { maxHeight, opacity, overflow: 'hidden' }]}>
        <View onLayout={onContentLayout}>
          {children}
        </View>
      </Animated.View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    marginBottom: 16,
    borderWidth: 1,
    overflow: 'hidden',
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 16,
    paddingVertical: 14,
    borderBottomWidth: 1,
  },
  headerLeft: {
