import { FONT_SUB, FONT_SMALL, FONT_TINY, formatDate , FONT_STAT_SECTION } from '@egoless-do/core';
import type { MindReflection } from '@egoless-do/core';
import React from 'react';
import { View, Text, StyleSheet } from 'react-native';

import { useTheme } from '../../../components/UI';
import { useShallowStore, type MobileStore } from '../../../store/useAppStore';

import ReflectionCard from './ReflectionCard';


interface PlanItem {
  id: string;
  planId: string;
  name: string;
  deleted?: boolean;
}

interface Props {
  date: string;
  reflections: MindReflection[];
  planItems?: PlanItem[];
  searchQuery?: string;
  onPress: (id: string) => void;
  onLongPress: (id: string) => void;
  onEdit: (id: string) => void;
  onTogglePin: (id: string) => void;
  onNavigateToPlan?: (planId: string) => void;
}

function DayGroupComponent({
  date,
  reflections,
  planItems = [],
  searchQuery,
  onPress,
  onLongPress,
  onEdit,
  onTogglePin,
  onNavigateToPlan,
}: Props) {
  const TH = useTheme();
  const P = TH.primary;
  const language = useShallowStore((s: MobileStore) => s.language);

  const dayNum = date.slice(8, 10);
  const month = date.slice(5, 7);
