    tags: string[];
    moods: string[];
    hasLink?: boolean;
    hasLinkedTask?: boolean;
    dateRange?: { from: number; to: number };
    datePreset?: string;
  };
  onApplyFilters: (filters: Props['filters']) => void;
  allTagOptions: string[];
  allMoodOptions: string[];
  dynamicTagCounts: Record<string, number>;
  dynamicMoodCounts: Record<string, number>;
  primaryColor: string;
}

type DatePreset = 'week' | 'month' | '7d' | '30d' | 'custom';

function getDateRange(preset: Exclude<DatePreset, 'custom'>): { from: number; to: number } {
  const now = new Date();
  const to = Date.now();
  let from: number;
  if (preset === 'week') {
    const d = new Date(now);
    const day = d.getDay() || 7;
    d.setDate(d.getDate() - day + 1);
    d.setHours(0, 0, 0, 0);
    from = d.getTime();
  } else if (preset === 'month') {
    const d = new Date(now.getFullYear(), now.getMonth(), 1);
    from = d.getTime();
  } else if (preset === '7d') {
    const d = new Date(now);
    d.setDate(d.getDate() - 6);
    d.setHours(0, 0, 0, 0);
    from = d.getTime();
  } else {
    const d = new Date(now);
    d.setDate(d.getDate() - 29);
    d.setHours(0, 0, 0, 0);
    from = d.getTime();
  }
  return { from, to };
}

const QUICK_PRESETS: { key: Exclude<DatePreset, 'custom'>; label: string }[] = [
  { key: 'week', label: '本周' },
  { key: 'month', label: '本月' },
  { key: '7d', label: '近7天' },
  { key: '30d', label: '近30天' },
];

function FilterDrawerComponent({
  visible,
  onClose,
  filters,
  onApplyFilters,
  allTagOptions,
  allMoodOptions,
  dynamicTagCounts,
  dynamicMoodCounts,
  primaryColor: P,
