        endDate={filters.dateRange ? new Date(filters.dateRange.to).toLocaleDateString('sv-SE') : dateStr()}
        onConfirm={handleCustomRangeConfirm}
        onClose={() => setShowRangePicker(false)}
      />
    </View>
  );
}

