const ReflectionCard = React.memo(ReflectionCardComponent);
export default ReflectionCard;

import { MIND_COLORS_EXTENDED, FONT_BODY, FONT_SUB, FONT_BUTTON, FONT_SMALL, dateStr, getTrailsByReflection, createLogger, formatDate, formatTime } from '@egoless-do/core';
import type { MindReflection } from '@egoless-do/core';
import { LinearGradient } from 'expo-linear-gradient';
import { ArrowLeft, ExternalLink, Link, Pin, Network, MoreHorizontal } from 'lucide-react-native';
import React, { useMemo, useState } from 'react';
import { View, Text, ScrollView, TouchableOpacity, Linking, Alert, Pressable } from 'react-native';

import { useT } from '../../../components/UI';
import { useRootNavigation } from '../../../navigation/hooks';
import { useShallowStore, type MobileStore } from '../../../store/useAppStore';
import { TrailPickerModal } from '../trails';

const log = createLogger('Reflections');

interface ReflectionDetailContentProps {
  reflectionId: string;
  onClose: () => void;
  onEdit?: (reflection: MindReflection) => void;
  onShare?: (reflection: MindReflection) => void;
  onCreatePlanItem?: (reflectionId: string) => void;
  onDelete?: (reflectionId: string) => void;
}

export default function ReflectionDetailContent({
  reflectionId,
  onClose,
  onEdit,
  onShare,
  onCreatePlanItem,
  onDelete,
}: ReflectionDetailContentProps) {
  const { reflections, thoughtTrails, planItems, deletePlanItem, unlinkReflectionFromPlanItem } = useShallowStore(s => ({
    reflections: s.reflections,
    thoughtTrails: s.thoughtTrails,
    planItems: s.planItems,
    deletePlanItem: s.deletePlanItem,
    unlinkReflectionFromPlanItem: s.unlinkReflectionFromPlanItem,
  }));
  const nav = useRootNavigation();
  const T = useT();
  const language = useShallowStore((s: MobileStore) => s.language);
  const [showMore, setShowMore] = useState(false);
  const [showTrailPicker, setShowTrailPicker] = useState(false);

  const r = useMemo(() => (reflections ?? []).find(x => !x.deleted && x.id === reflectionId), [reflections, reflectionId]);

  const linkedTrails = useMemo(() => {
    if (!r) return [];
    return getTrailsByReflection(r.id, thoughtTrails ?? []);
  }, [r, thoughtTrails]);

  if (!r) return null;

  const linkedPlanItem = r.linkedPlanItemId
    ? (planItems ?? []).find(i => i.id === r.linkedPlanItemId && !i.deleted)
    : null;
  const colors: [string, string] = [r.colors?.[0] || MIND_COLORS_EXTENDED[0][0], r.colors?.[1] || MIND_COLORS_EXTENDED[0][1]];
  const isToday = dateStr(new Date(r.timestamp ?? 0)) === dateStr();

  const handleUnlink = () => {
    Alert.alert(T('reflUnlinkConfirmTitle'), T('reflUnlinkConfirmMessage'), [
      { text: T('cancel'), style: 'cancel' },
      { text: T('confirm'), style: 'destructive', onPress: () => {
        if (r.linkedPlanItemId) deletePlanItem(r.linkedPlanItemId).catch(err => log.error(err, { message: 'deletePlanItem' }));
        unlinkReflectionFromPlanItem(r.id);
        onClose();
      }},
    ]);
  };

  return (
    <View style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0,0,0,.5)', justifyContent: 'flex-end' }}>
      <TouchableOpacity activeOpacity={1} onPress={() => { if (showMore) setShowMore(false); else onClose(); }} style={{ flex: 1 }} />
      <LinearGradient
        colors={colors}
        start={{ x: 0, y: 0 }} end={{ x: 1, y: 1 }}
        style={{ borderTopLeftRadius: 24, borderTopRightRadius: 24, paddingHorizontal: 24, paddingBottom: 40, paddingTop: 20, maxHeight: '95%' }}
      >
        {/* Header */}
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
          <TouchableOpacity onPress={onClose}>
            <ArrowLeft size={24} color="#fff" />
          </TouchableOpacity>
          <View style={{ flexDirection: 'row', alignItems: 'center', gap: 8 }}>
            {r.isPinned && <Pin size={14} color="#fff" />}
            <Text style={{ color: 'rgba(255,255,255,.7)', fontSize: FONT_SMALL() }}>
              {formatDate(new Date(r.timestamp ?? 0), language, { year: 'numeric', month: 'long', day: 'numeric' })}
              {' '}
              {formatTime(new Date(r.timestamp ?? 0), language, { hour: '2-digit', minute: '2-digit' })}
            </Text>
          </View>
        </View>

        <ScrollView>
          {/* Content */}
          <Text style={{ color: '#fff', fontSize: FONT_BODY(), lineHeight: 28, marginBottom: 16 }}>{r.content}</Text>

          {/* Tags + Mood */}
          {(r.tags.length > 0 || r.mood) && (
            <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6, marginBottom: 16 }}>
              {r.tags.map(tag => (
                <View key={tag} style={{ backgroundColor: 'rgba(255,255,255,.2)', paddingHorizontal: 10, paddingVertical: 4, borderRadius: 12 }}>
                  <Text style={{ color: '#fff', fontSize: FONT_SMALL() }}>{tag}</Text>
                </View>
              ))}
              {r.mood && (
                <View style={{ backgroundColor: 'rgba(255,255,255,.15)', paddingHorizontal: 10, paddingVertical: 4, borderRadius: 12 }}>
                  <Text style={{ color: 'rgba(255,255,255,.8)', fontSize: FONT_SMALL() }}>{r.mood}</Text>
                </View>
              )}
            </View>
          )}

          {/* Link */}
          {r.link && (
            <TouchableOpacity onPress={() => r.link && Linking.openURL(r.link).catch((e) => log.error(e))} style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 12 }}>
              <Link size={14} color="rgba(255,255,255,.7)" />
              <Text style={{ color: 'rgba(255,255,255,.7)', fontSize: FONT_SMALL(), textDecorationLine: 'underline', flex: 1 }} numberOfLines={2}>{r.link}</Text>
            </TouchableOpacity>
          )}

          {/* Linked plan item */}
          {linkedPlanItem && (
            <TouchableOpacity
              onPress={() => { onClose(); nav.navigate('PlanDetail', { planId: linkedPlanItem.planId }); }}
              style={{ flexDirection: 'row', alignItems: 'center', gap: 6, marginBottom: 12, backgroundColor: 'rgba(255,255,255,.15)', paddingHorizontal: 12, paddingVertical: 8, borderRadius: 10 }}
            >
              <ExternalLink size={14} color="#fff" />
              <Text style={{ color: '#fff', fontSize: FONT_SMALL() }} numberOfLines={1}>{linkedPlanItem.name}</Text>
            </TouchableOpacity>
          )}
        </ScrollView>

        {/* Action buttons */}
        <View style={{ flexDirection: 'row', gap: 10, marginTop: 20, flexWrap: 'wrap' }}>
          {onEdit && (
            <TouchableOpacity onPress={() => { onClose(); onEdit(r); }}
              style={{ flex: 1, backgroundColor: 'rgba(255,255,255,.25)', paddingVertical: 12, borderRadius: 12, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('reflEditTitle')}</Text>
            </TouchableOpacity>
          )}
          {linkedTrails.length > 0 ? (
            <TouchableOpacity onPress={() => { onClose(); nav.navigate('ThoughtTrailDetail', { trailId: linkedTrails[0].id }); }}
              style={{ flex: 1, backgroundColor: 'rgba(139,92,246,.3)', paddingVertical: 12, borderRadius: 12, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('reflLinkedTrail')}</Text>
            </TouchableOpacity>
          ) : (
            <TouchableOpacity onPress={() => setShowTrailPicker(true)}
              style={{ flex: 1, backgroundColor: 'rgba(139,92,246,.3)', paddingVertical: 12, borderRadius: 12, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('reflLinkTrail')}</Text>
            </TouchableOpacity>
          )}
          {r.linkedPlanItemId ? (
            <TouchableOpacity onPress={handleUnlink}
              style={{ flex: 1, backgroundColor: 'rgba(139,92,246,.3)', paddingVertical: 12, borderRadius: 12, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('reflUnlinkTask')}</Text>
            </TouchableOpacity>
          ) : onCreatePlanItem ? (
            <TouchableOpacity onPress={() => { onClose(); onCreatePlanItem(r.id); }}
              style={{ flex: 1, backgroundColor: 'rgba(16,185,129,.3)', paddingVertical: 12, borderRadius: 12, alignItems: 'center' }}>
              <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('reflCreateTask')}</Text>
            </TouchableOpacity>
          ) : null}
          <View style={{ position: 'relative' }}>
            <Pressable onPress={() => setShowMore(!showMore)}
              style={{ backgroundColor: 'rgba(255,255,255,.25)', paddingVertical: 12, paddingHorizontal: 16, borderRadius: 12, alignItems: 'center' }}>
              <MoreHorizontal size={20} color="#fff" />
            </Pressable>
            {showMore && (
              <Pressable style={{ position: 'absolute', bottom: 52, right: 0, backgroundColor: 'rgba(0,0,0,.85)', borderRadius: 12, paddingVertical: 4, minWidth: 140, shadowColor: '#000', shadowOffset: { width: 0, height: 4 }, shadowOpacity: 0.3, shadowRadius: 8, elevation: 8, zIndex: 2 }}>
                <TouchableOpacity onPress={() => { setShowMore(false); onClose(); nav.navigate('RelationMap', { context: { type: 'reflection', id: reflectionId } }); }}
                  style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 12, paddingHorizontal: 16 }}>
                  <Network size={16} color="#fff" />
                  <Text style={{ color: '#fff', fontSize: FONT_BUTTON() }}>{T('reflRelationMap')}</Text>
                </TouchableOpacity>
                {onShare && (
                  <TouchableOpacity onPress={() => { setShowMore(false); onShare(r); }}
                    style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 12, paddingHorizontal: 16 }}>
                    <ExternalLink size={16} color="#fff" />
                    <Text style={{ color: '#fff', fontSize: FONT_BUTTON() }}>{T('reflShare')}</Text>
                  </TouchableOpacity>
                )}
                {isToday && onDelete && (
                  <TouchableOpacity onPress={() => { setShowMore(false); onClose(); onDelete(r.id); }}
                    style={{ flexDirection: 'row', alignItems: 'center', gap: 8, paddingVertical: 12, paddingHorizontal: 16 }}>
                    <Text style={{ color: '#ff6b6b', fontSize: FONT_BUTTON() }}>{T('reflDelete')}</Text>
                  </TouchableOpacity>
                )}
              </Pressable>
            )}
          </View>
        </View>
      </LinearGradient>

      <TrailPickerModal
        visible={showTrailPicker}
        reflectionId={reflectionId}
        linkedTrailIds={new Set(linkedTrails.map(t => t.id))}
        onClose={() => setShowTrailPicker(false)}
      />
    </View>
  );
}

import type { MindReflection } from '@egoless-do/core';
import { formatDate } from '@egoless-do/core';
import { useRoute, useNavigation, RouteProp } from '@react-navigation/native';
import type { StackNavigationProp } from '@react-navigation/stack';
import React, { useCallback, useState } from 'react';
import { Alert, Share } from 'react-native';

import { useT } from '../../../components/UI';
import type { RootStackParamList } from '../../../navigation/types';
import { useShallowStore, type MobileStore } from '../../../store/useAppStore';

import ReflectionDetailContent from './ReflectionDetailContent';
import ShareCard from './ShareCard';


export default function ReflectionDetailScreen() {
  const route = useRoute<RouteProp<RootStackParamList, 'ReflectionDetail'>>();
  const nav = useNavigation<StackNavigationProp<RootStackParamList>>();
  const { reflectionId } = route.params;
  const { reflections, getActivePlan, deleteReflection } = useShallowStore(s => ({ reflections: s.reflections, getActivePlan: s.getActivePlan, deleteReflection: s.deleteReflection }));
  const T = useT();
  const language = useShallowStore((s: MobileStore) => s.language);
  const [shareReflection, setShareReflection] = useState<MindReflection | null>(null);

  const handleEdit = useCallback((r: MindReflection) => {
    // NOTE: Reflections is a MainTab screen, nested navigator type mismatch
    nav.navigate('Reflections' as never, { editId: r.id } as never);
  }, [nav]);

  const handleShare = useCallback(async (r: MindReflection) => {
    Alert.alert(T('reflShare'), '', [
      {
        text: T('shareTextShare'), onPress: async () => {
          try {
            const tagsStr = r.tags?.length ? `\n🏷️ ${r.tags.join(' ')}` : '';
            const moodStr = r.mood ? `\n💭 ${r.mood}` : '';
            const timeStr = formatDate(new Date(r.timestamp ?? 0), language, { year: 'numeric', month: 'long', day: 'numeric' });
            await Share.share({
              message: `「${r.content}」${tagsStr}${moodStr}\n\n📅 ${timeStr}\n— 来自心流纪 · Egoless Do\nhttps://egoless-do.app`,
            });
          } catch { /* Share API unavailable — ignore */ }
        },
      },
      { text: T('shareImageShare'), onPress: () => setShareReflection(r) },
      { text: T('cancel'), style: 'cancel' },
    ]);
  }, [T]);

  const handleCreatePlanItem = useCallback((id: string) => {
    const r = (reflections ?? []).find(x => !x.deleted && x.id === id);
    if (r) {
      const activePlan = getActivePlan?.();
      if (activePlan) {
        nav.navigate('PlanCreate', { planId: activePlan.id, reflectionId: id });
      } else {
        nav.navigate('PlanCreate', { reflectionId: id });
      }
    }
  }, [reflections, getActivePlan, nav]);

  const handleDelete = useCallback((id: string) => {
    Alert.alert(T('confirmDelete'), T('confirmDeleteReflection'), [
      { text: T('cancel'), style: 'cancel' },
      { text: T('delete'), style: 'destructive', onPress: () => {
        deleteReflection(id);
        nav.goBack();
      }},
    ]);
  }, [deleteReflection, nav, T]);

  return (
    <>
      <ReflectionDetailContent
        reflectionId={reflectionId}
        onClose={() => nav.goBack()}
        onEdit={handleEdit}
        onShare={handleShare}
        onCreatePlanItem={handleCreatePlanItem}
        onDelete={handleDelete}
      />
      <ShareCard
        visible={!!shareReflection}
        onClose={() => setShareReflection(null)}
        reflection={shareReflection}
      />
    </>
  );
}

import { MIND_COLORS_EXTENDED, COLORS, FONT_BODY, FONT_LABEL, FONT_SMALL } from '@egoless-do/core';
import { Settings, Link, Plus } from 'lucide-react-native';
import React from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet } from 'react-native';

import { useTheme, useT, PillSelector, PrimaryButton, ThemedInput } from '../../../components/UI';


interface ReflectionFormProps {
  content: string;
  onContentChange: (text: string) => void;
  colorIdx: number;
  onColorIdxChange: (idx: number) => void;
  tags: string[];
  onTagsChange: (tags: string[]) => void;
  mood: string;
  onMoodChange: (mood: string) => void;
  onSave: () => void;
  saveLabel: string;
  allTagOptions: string[];
  allMoodOptions: string[];
  dynamicTagCounts: Record<string, number>;
  onOpenTagManager: () => void;
  onOpenMoodManager: () => void;
  linkedTrailNames?: string[];
  onOpenTrailPicker?: () => void;
}

export default function ReflectionForm({
  content,
  onContentChange,
  colorIdx,
  onColorIdxChange,
  tags,
  onTagsChange,
  mood,
  onMoodChange,
  onSave,
  saveLabel,
  allTagOptions,
  allMoodOptions,
  dynamicTagCounts,
  onOpenTagManager,
  onOpenMoodManager,
  linkedTrailNames = [],
  onOpenTrailPicker,
}: ReflectionFormProps) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;

  return (
    <ScrollView keyboardShouldPersistTaps="handled">
      {/* Card theme color */}
      <View style={styles.colorContainer}>
        {MIND_COLORS_EXTENDED.map((c, i) => {
          const isActive = colorIdx === i;
          return (
            <TouchableOpacity
              key={i}
              onPress={() => onColorIdxChange(i)}
              style={[
                styles.colorButton,
                {
                  width: isActive ? 36 : 32,
                  height: isActive ? 36 : 32,
                  backgroundColor: isActive ? c[0] : 'transparent',
                  padding: isActive ? 2 : 0,
                },
              ]}
            >
              <View
                style={[
                  styles.colorInner,
                  {
                    borderWidth: isActive ? 2 : 0,
                    borderColor: isActive ? '#fff' : 'transparent',
                  },
                ]}
              >
                <View style={[styles.colorBase, { backgroundColor: c[0] }]} />
                <View style={[styles.colorOverlay, { backgroundColor: c[1] }]} />
              </View>
            </TouchableOpacity>
          );
        })}
      </View>

      {/* Content with 200-char limit */}
      <View style={styles.contentContainer}>
        <ThemedInput
          value={content}
          onChangeText={onContentChange}
          placeholder={T('reflPlaceholder')}
          multiline
          numberOfLines={4}
          style={styles.contentInput}
        />
        <Text
          style={[
            styles.charCount,
            { color: content.length > 200 ? COLORS.RED : TH.sub },
          ]}
        >
          {content.length}/200
        </Text>
      </View>

      {/* Tags */}
      <Text style={[styles.sectionLabel, { color: TH.sub }]}>
        {T('reflAddTag')}
      </Text>
      <View style={styles.pillsRow}>
        <PillSelector
          options={allTagOptions}
          selected={tags}
          onChange={(t) =>
            onTagsChange(
              tags.includes(t) ? tags.filter((x) => x !== t) : [...tags, t]
            )
          }
          counts={dynamicTagCounts}
          color={P}
          textActiveColor={P}
          trailing={
            <TouchableOpacity
              onPress={onOpenTagManager}
              style={[styles.managerButton, { borderColor: TH.border }]}
            >
              <Settings size={16} color={TH.sub} />
            </TouchableOpacity>
          }
        />
      </View>

      {/* Mood */}
      <Text style={[styles.sectionLabel, { color: TH.sub }]}>
        {T('reflMood')}
      </Text>
      <View style={styles.pillsRow}>
        <PillSelector
          options={allMoodOptions}
          selected={mood ? [mood] : []}
          onChange={(m) => onMoodChange(mood === m ? '' : m)}
          color={P}
          textActiveColor={P}
          trailing={
            <TouchableOpacity
              onPress={onOpenMoodManager}
              style={[styles.managerButton, { borderColor: TH.border }]}
            >
              <Settings size={16} color={TH.sub} />
            </TouchableOpacity>
          }
        />
      </View>

      {/* Linked Thought Trails */}
      {onOpenTrailPicker && (
        <>
          <Text style={[styles.sectionLabel, { color: TH.sub }]}>
            关联思维脉络
          </Text>
          <View style={styles.trailContainer}>
            {linkedTrailNames.map(name => (
              <View key={name} style={[styles.trailChip, { backgroundColor: `${P}15`, borderColor: P }]}>
                <Link size={12} color={P} />
                <Text style={[styles.trailChipText, { color: P }]}>{name}</Text>
              </View>
            ))}
            <TouchableOpacity
              onPress={onOpenTrailPicker}
              style={[styles.trailAddButton, { borderColor: TH.border }]}
            >
              <Plus size={14} color={TH.sub} />
              <Text style={[styles.trailAddText, { color: TH.sub }]}>加入脉络</Text>
            </TouchableOpacity>
          </View>
        </>
      )}

      <PrimaryButton label={saveLabel} onPress={onSave} />
    </ScrollView>
  );
}

