import { getAIService } from '@egoless-do/core';
import type { TrailInsightCache, TrailReviewCache, ThoughtTrail, MindReflection, TrailNote } from '@egoless-do/core';
import { useCallback, useRef, useMemo, useEffect } from 'react';

import { useAppStore, useShallowStore } from '../../../store/useAppStore';

const CACHE_FRESH_MS = 5 * 60 * 1000;

function isCacheStale(
  cache: { generatedAt: number } | undefined,
  trail: ThoughtTrail | undefined,
  reflections: MindReflection[] | undefined,
  trailNotes: TrailNote[] | undefined,
): boolean {
  if (!trail) return false;
  if (!cache) return true;
  const reflectionTimestamps = trail.reflectionIds
    .map(id => (reflections ?? []).find(r => r.id === id))
    .filter((r): r is NonNullable<typeof r> => r != null && !r.deleted)
    .map(r => r.timestamp);
  const noteTimestamps = (trail.noteIds ?? [])
    .map(id => (trailNotes ?? []).find(n => n.id === id))
    .filter((n): n is NonNullable<typeof n> => n != null && !n.deleted)
    .map(n => n.createdAt);
  const allTimestamps = [...reflectionTimestamps, ...noteTimestamps];
  if (allTimestamps.length === 0) return false;
  const lastModified = Math.max(...allTimestamps);
  return lastModified > cache.generatedAt + CACHE_FRESH_MS;
}

export function useTrailAI(trailId: string, trail: ThoughtTrail | undefined) {
  const reflections = useShallowStore(s => s.reflections);
  const trailNotes = useShallowStore(s => s.trailNotes);
  const aiMode = useShallowStore(s => s.aiMode);
  const setInsightCache = useShallowStore(s => s.setInsightCache);
  const setReviewCache = useShallowStore(s => s.setReviewCache);

  const aiAbortRef = useRef<AbortController | null>(null);

  const insightCacheStale = useMemo(
    () => isCacheStale(trail?.insightCache, trail, reflections, trailNotes),
    [trail?.insightCache, trail, reflections, trailNotes],
  );

  const reviewCacheStale = useMemo(
    () => isCacheStale(trail?.reviewCache, trail, reflections, trailNotes),
    [trail?.reviewCache, trail, reflections, trailNotes],
  );

  const handleGenerateInsight = useCallback(async () => {
    if (!trail) return;
    if (aiAbortRef.current) aiAbortRef.current.abort();
    const controller = new AbortController();
    aiAbortRef.current = controller;

    const aiService = getAIService();
    const trailReflections = trail.reflectionIds
      .map(id => (reflections ?? []).find(r => r.id === id))
      .filter((r): r is NonNullable<typeof r> => r != null && !r.deleted);
    const notes = (trail.noteIds ?? [])
      .map(id => (trailNotes ?? []).find(n => n.id === id))
      .filter((n): n is NonNullable<typeof n> => n != null && !n.deleted);

    try {
      const result = await aiService.generateTrailInsight(
        trailReflections.map(r => ({ content: r.content, mood: r.mood ?? '' })),
        {
          useCloud: aiMode !== 'local',
          signal: controller.signal,
          trailNotes: notes.map(n => ({ content: n.content, source: n.source, guidedQuestion: n.guidedQuestion })),
        }
      );
      if (controller.signal.aborted) return;

      const cache: TrailInsightCache = {
        summary: result.summary,
        keyPoints: result.keyPoints,
        turningPoints: result.turningPoints,
        suggestions: result.suggestions,
        generatedAt: Date.now(),
        source: aiMode === 'local' ? 'local' : 'cloud',
      };
      setInsightCache(trailId, cache);
    } finally {
      if (aiAbortRef.current === controller) aiAbortRef.current = null;
    }
  }, [trail, trailId, reflections, trailNotes, aiMode, setInsightCache]);

  const handleGenerateReview = useCallback(async () => {
    if (!trail) return;
    if (aiAbortRef.current) aiAbortRef.current.abort();
    const controller = new AbortController();
    aiAbortRef.current = controller;

    const aiService = getAIService();
    const trailReflections = trail.reflectionIds
      .map(id => (reflections ?? []).find(r => r.id === id))
      .filter((r): r is NonNullable<typeof r> => r != null && !r.deleted);
    const notes = (trail.noteIds ?? [])
      .map(id => (trailNotes ?? []).find(n => n.id === id))
      .filter((n): n is NonNullable<typeof n> => n != null && !n.deleted);

    const items = [
      ...trailReflections.map(r => ({ content: r.content, mood: r.mood, timestamp: r.timestamp, kind: 'reflection' as const })),
      ...notes.map(n => ({ content: n.content, mood: n.mood, timestamp: n.createdAt, kind: 'note' as const })),
    ].sort((a, b) => a.timestamp - b.timestamp);

    try {
      const result = await aiService.generateTrailReviewGuide(items, {
        useCloud: aiMode !== 'local',
        signal: controller.signal,
      });
      if (controller.signal.aborted) return;

      const cache: TrailReviewCache = {
        perspectives: result.perspectives,
        observations: result.observations,
        suggestions: result.suggestions,
        generatedAt: Date.now(),
        source: aiMode === 'local' ? 'local' : 'cloud',
      };
      setReviewCache(trailId, cache);
    } finally {
      if (aiAbortRef.current === controller) aiAbortRef.current = null;
    }
  }, [trail, trailId, reflections, trailNotes, aiMode, setReviewCache]);

  useEffect(() => {
    return () => aiAbortRef.current?.abort();
  }, []);

  return { handleGenerateInsight, handleGenerateReview, insightCacheStale, reviewCacheStale };
}

import {
  FONT_BODY, FONT_SMALL, FONT_TINY, FONT_BUTTON, MS_PER_DAY, activeOnly,
  computeLocalInsights, formatDateShort, scaleFontSize } from '@egoless-do/core';
import type { HotTag, MindReflection } from '@egoless-do/core';
import React, { useMemo } from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import { useTheme, useT } from '../../../components/UI';

interface Props {
  visible: boolean;
  reflections: MindReflection[];
  onTagPress: (tag: string) => void;
  onMoodPress: (mood: string) => void;
  onGoRecord: () => void;
}

export default function InsightPanel({
  visible,
  reflections,
  onTagPress,
  onMoodPress,
  onGoRecord,
}: Props) {
  const TH = useTheme();
  const T = useT();

  const { filtered, spanDays } = useMemo(() => {
    const active = activeOnly(reflections);
    if (active.length === 0) return { filtered: [], spanDays: 15 };
    const sorted = [...active].sort((a, b) => b.timestamp - a.timestamp);
    const latest = sorted[0].timestamp;
    const cutoff = latest - 15 * MS_PER_DAY;
    return { filtered: sorted.filter(r => r.timestamp >= cutoff), spanDays: 15 };
  }, [reflections]);

  const localInsights = useMemo(() => {
    if (filtered.length < 3) return null;
    return computeLocalInsights(filtered, 'month');
  }, [filtered]);

  if (!visible) return null;

  if (filtered.length < 3) {
    return (
      <View style={{ alignItems: 'center', paddingVertical: 32 }}>
        <Text style={{ fontSize: scaleFontSize(32), marginBottom: 8 }}>📝</Text>
        <Text style={{ fontSize: FONT_BODY(), color: TH.sub, textAlign: 'center' }}>
          {T('insightProfileEmpty')}
        </Text>
        <TouchableOpacity
          onPress={onGoRecord}
          style={{ backgroundColor: TH.primary, borderRadius: 10, paddingVertical: 10, paddingHorizontal: 20, marginTop: 12 }}
        >
          <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>{T('insightProfileGoRecord')}</Text>
        </TouchableOpacity>
      </View>
    );
  }

  if (!localInsights) return null;

  const trendIcon = (t: HotTag['trend']) => t === 'rising' ? '↑' : t === 'declining' ? '↓' : '→';
  const trendColor = (t: HotTag['trend']) => t === 'rising' ? '#4CAF50' : t === 'declining' ? '#F44336' : TH.sub;
  const maxItems = 4;

  const sorted = [...filtered].sort((a, b) => a.timestamp - b.timestamp);
  const rangeStart = formatDateShort(sorted[0].timestamp);
  const rangeEnd = formatDateShort(sorted[sorted.length - 1].timestamp);

  return (
    <View>
      {/* Stats */}
      <View style={{ paddingHorizontal: 16, marginBottom: 16 }}>
        <Text style={{ fontSize: FONT_BODY(), fontWeight: '600', color: TH.text }}>
          {T('insightProfileStats').replace('{days}', String(spanDays)).replace('{count}', String(localInsights.totalCount))}
        </Text>
        <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginTop: 2 }}>
          {rangeStart} ─ {rangeEnd}
        </Text>
        {localInsights.streakDays > 0 && (
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginTop: 2 }}>
            {T('insightProfileStreak').replace('{days}', String(localInsights.streakDays))}
          </Text>
        )}
      </View>

      {/* Hot Tags */}
      {localInsights.hotTags.length > 0 && (
        <View style={{ paddingHorizontal: 16, marginBottom: 16 }}>
          <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.sub, marginBottom: 8 }}>
            {T('insightProfileHotTags')}
          </Text>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>
            {localInsights.hotTags.slice(0, maxItems).map(tag => (
              <TouchableOpacity
                key={tag.tag}
                onPress={() => onTagPress(tag.tag)}
                style={{
                  flexDirection: 'row', alignItems: 'center',
                  backgroundColor: `${TH.primary}12`,
                  borderRadius: 10, paddingHorizontal: 12, paddingVertical: 8,
                  marginRight: 8, marginBottom: 8,
                }}
              >
                <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.text }}>{tag.tag}</Text>
                <Text style={{ fontSize: FONT_TINY(), color: trendColor(tag.trend), marginLeft: 4 }}>{trendIcon(tag.trend)}</Text>
                <Text style={{ fontSize: FONT_TINY(), color: TH.sub, marginLeft: 4 }}>{tag.count}次</Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>
      )}

      {/* Mood Distribution */}
      {localInsights.moodDistribution.length > 0 && (
        <View style={{ paddingHorizontal: 16, marginBottom: 16 }}>
          <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.sub, marginBottom: 8 }}>
            {T('insightProfileMoodDist')}
          </Text>
          <View style={{ flexDirection: 'row', flexWrap: 'wrap' }}>
            {localInsights.moodDistribution.slice(0, maxItems).map(entry => (
              <TouchableOpacity
                key={entry.mood}
                onPress={() => onMoodPress(entry.mood)}
                style={{
                  flexDirection: 'row', alignItems: 'center',
                  backgroundColor: `${TH.primary}12`,
                  borderRadius: 10, paddingHorizontal: 12, paddingVertical: 8,
                  marginRight: 8, marginBottom: 8,
                }}
              >
                <Text style={{ fontSize: FONT_SMALL() }}>{entry.icon}</Text>
                <Text style={{ fontSize: FONT_SMALL(), fontWeight: '600', color: TH.text, marginLeft: 4 }}>{entry.mood}</Text>
                <Text style={{ fontSize: FONT_TINY(), color: TH.sub, marginLeft: 4 }}>{entry.percentage}%</Text>
                <Text style={{ fontSize: FONT_TINY(), color: TH.sub, marginLeft: 4 }}>{entry.count}次</Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>
      )}
    </View>
  );
}

import { FONT_SMALL, FONT_BODY } from '@egoless-do/core';
import type { TrailInsightCache } from '@egoless-do/core';
import { Brain, ChevronDown, ChevronUp } from 'lucide-react-native';
import React, { useState, useCallback, useEffect, useRef } from 'react';
import { View, Text, TouchableOpacity, ActivityIndicator, StyleSheet } from 'react-native';

import { useTheme, useT } from '../../../components/UI';


interface InsightSectionProps {
  insightCache?: TrailInsightCache;
  onGenerate: () => Promise<void>;
  stale?: boolean;
}

export function InsightSection({ insightCache, onGenerate, stale }: InsightSectionProps) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const [loading, setLoading] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const prevCacheRef = useRef(insightCache);

  useEffect(() => {
    if (!prevCacheRef.current && insightCache) {
      setExpanded(true);
    }
    prevCacheRef.current = insightCache;
  }, [insightCache]);

  const handleGenerate = useCallback(async () => {
    setLoading(true);
    try {
      await onGenerate();
    } finally {
      setLoading(false);
    }
  }, [onGenerate]);

  // 无内容时显示生成按钮
  if (!insightCache) {
    return (
      <View style={[styles.container, { backgroundColor: TH.card, borderColor: TH.border }]}>
        <View style={styles.header}>
          <Brain size={18} color={P} />
          <Text style={[styles.title, { color: TH.text }]}>AI 洞察</Text>
        </View>
        {loading ? (
          <View style={styles.skeletonContainer}>
            <View style={[styles.skeletonLine, { width: '80%', backgroundColor: TH.sub + '20' }]} />
            <View style={[styles.skeletonLine, { width: '60%', backgroundColor: TH.sub + '20' }]} />
            <View style={[styles.skeletonLine, { width: '90%', backgroundColor: TH.sub + '15' }]} />
            <View style={[styles.skeletonLine, { width: '45%', backgroundColor: TH.sub + '15' }]} />
            <Text style={[styles.loadingText, { color: TH.sub }]}>
              {T('trailInsightGenerating')}
            </Text>
          </View>
        ) : (
          <TouchableOpacity
            style={[styles.generateButton, { backgroundColor: P }]}
            onPress={handleGenerate}
            disabled={loading}
          >
            <Text style={styles.generateButtonText}>
              {T('trailInsightGenerate')}
            </Text>
          </TouchableOpacity>
        )}
      </View>
    );
  }

  // 有内容时可折叠
  return (
    <TouchableOpacity
      style={[styles.container, { backgroundColor: TH.card, borderColor: TH.border }]}
      onPress={() => setExpanded(prev => !prev)}
      activeOpacity={0.8}
    >
      <View style={styles.header}>
        <Brain size={18} color={P} />
        <Text style={[styles.title, { color: TH.text }]}>AI 洞察</Text>
        <View style={styles.headerRight}>
          {!expanded && (
            <Text style={[styles.preview, { color: TH.sub }]} numberOfLines={1}>
              {insightCache.summary}
            </Text>
          )}
          {expanded
            ? <ChevronUp size={16} color={TH.sub} />
            : <ChevronDown size={16} color={TH.sub} />
          }
        </View>
      </View>

      {expanded && (
        <View style={styles.content}>
          <Text style={[styles.sectionLabel, { color: TH.sub }]}>
            {T('trailInsightSummary')}
          </Text>
          <Text style={[styles.contentText, { color: TH.text }]}>
            {insightCache.summary}
          </Text>

          {insightCache.keyPoints.length > 0 && (
            <>
              <Text style={[styles.sectionLabel, { color: TH.sub }]}>
                {T('trailInsightKeyPoints')}
              </Text>
              {insightCache.keyPoints.map((point, i) => (
                <Text key={i} style={[styles.bulletText, { color: TH.text }]}>
                  • {point}
                </Text>
              ))}
            </>
          )}

          {insightCache.turningPoints.length > 0 && (
            <>
              <Text style={[styles.sectionLabel, { color: TH.sub }]}>
                {T('trailInsightTurningPoints')}
              </Text>
              {insightCache.turningPoints.map((point, i) => (
                <Text key={i} style={[styles.bulletText, { color: TH.text }]}>
                  • {point}
                </Text>
              ))}
            </>
          )}

          {insightCache.suggestions.length > 0 && (
            <>
              <Text style={[styles.sectionLabel, { color: TH.sub }]}>
                {T('trailInsightSuggestions')}
              </Text>
              {insightCache.suggestions.map((s, i) => (
                <Text key={i} style={[styles.bulletText, { color: TH.text }]}>
                  • {s}
                </Text>
              ))}
            </>
          )}

          {stale && (
            <View style={styles.staleRow}>
              <Text style={[styles.staleText, { color: '#F59E0B' }]}>
                已有洞察（可能已过期）
              </Text>
              <TouchableOpacity onPress={handleGenerate} disabled={loading}>
                <Text style={[styles.actionText, { color: P }]}>
                  {T('trailInsightRegenerate')}
                </Text>
              </TouchableOpacity>
            </View>
          )}
          <View style={styles.footerRow}>
            <TouchableOpacity onPress={handleGenerate} disabled={loading}>
              <Text style={[styles.actionText, { color: P }]}>
                {T('trailInsightRegenerate')}
              </Text>
            </TouchableOpacity>
            <Text style={[styles.timeText, { color: TH.sub }]}>
              {new Date(insightCache.generatedAt).toLocaleString()}
            </Text>
          </View>
        </View>
      )}
    </TouchableOpacity>
  );
}

