function MindTrailEntryCard({ onPress }: Props) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { thoughtTrails: rawThoughtTrails } = useShallowStore(s => ({
    thoughtTrails: s.thoughtTrails,
  }));

  const thoughtTrails = useMemo(() =>
    (rawThoughtTrails ?? []).filter(t => !t.deleted),
    [rawThoughtTrails]
  );

  const trailCount = thoughtTrails.length;

  const getDescription = () => {
    if (trailCount === 0) {
      return '串联感念・梳理脉络';
    }
    return `串联感念・梳理脉络 · ${trailCount} 条脉络`;
  };

  return (
    <TouchableOpacity
      onPress={onPress}
      activeOpacity={0.7}
      style={[styles.container, { backgroundColor: TH.card, borderColor: TH.border }]}
    >
      {/* 左侧紫色装饰条 */}
      <View style={[styles.decorator, { backgroundColor: '#8B5CF6' }]} />
      
      <View style={styles.content}>
        <View style={styles.iconContainer}>
          <Brain size={20} color="#8B5CF6" />
        </View>
        
        <View style={styles.textContainer}>
          <Text style={[styles.title, { color: TH.text }]}>
            {T('mindTrail')}
          </Text>
          <Text style={[styles.description, { color: TH.sub }]}>
            {getDescription()}
          </Text>
        </View>
        
        <Text style={[styles.action, { color: '#8B5CF6' }]}>
          {trailCount > 0 ? '查看 →' : '开始 →'}
        </Text>
      </View>
    </TouchableOpacity>
  );
}

