import { FONT_SMALL, FONT_BUTTON } from '@egoless-do/core';
import type { SmartQueryResult } from '@egoless-do/core';
import { X } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';

import { useTheme, useT } from '../../../components/UI';
import { SmartQueryBubble } from '../insights/SmartQueryBubble';


interface Props {
  show: boolean;
  onClose: () => void;
  smartResult: SmartQueryResult | null;
  onSmartAnswer: (answer: string) => void;
  onSmartQuery: () => void;
  isSmartParsing: boolean;
  queryResults: Array<{ id: string }>;
  onQuickCreate: (selectedIds: string[]) => void;
  chatHistory: unknown[];
}

export default function SmartQueryPanel({
  show, onClose,
  smartResult, onSmartAnswer, onSmartQuery,
  isSmartParsing, queryResults, onQuickCreate,
  chatHistory,
}: Props) {
  const TH = useTheme();
  const T = useT();

  if (!show) return null;

  return (
    <View style={{ paddingHorizontal: 16, paddingTop: 12, paddingBottom: 8, borderTopWidth: 1, borderTopColor: TH.border }}>
      <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
        <Text style={{ fontSize: FONT_SMALL(), color: TH.primary, fontWeight: '600' }}>
          🔍 智能查询
        </Text>
        <TouchableOpacity onPress={onClose}>
          <X size={18} color={TH.sub} />
        </TouchableOpacity>
      </View>

      {/* Smart query bubble */}
      {smartResult?.question && chatHistory.length < 3 && (
        <SmartQueryBubble
          question={smartResult.question}
          onAnswer={onSmartAnswer}
          onSkip={() => {
            onSmartQuery();
          }}
        />
      )}

      {/* Loading indicator */}
      {isSmartParsing && (
        <View style={{ paddingVertical: 12, alignItems: 'center' }}>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>🧠 智能解析中...</Text>
        </View>
      )}

      {/* Query results */}
      {!isSmartParsing && queryResults.length > 0 && (
        <View style={{ marginTop: 8 }}>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub, marginBottom: 8 }}>
            找到 {queryResults.length} 条相关感念
          </Text>
          <TouchableOpacity
            onPress={() => {
              onClose();
              onQuickCreate(queryResults.map(r => r.id));
            }}
            style={{
              backgroundColor: TH.primary,
              borderRadius: 10, paddingVertical: 10,
              alignItems: 'center',
            }}
          >
            <Text style={{ color: '#fff', fontSize: FONT_BUTTON(), fontWeight: '600' }}>
              快速创建脉络 →
            </Text>
          </TouchableOpacity>
        </View>
      )}

      {/* No results */}
      {!isSmartParsing && queryResults.length === 0 && !smartResult?.question && (
        <View style={{ paddingVertical: 12, alignItems: 'center' }}>
          <Text style={{ fontSize: FONT_SMALL(), color: TH.sub }}>未找到匹配的感念</Text>
        </View>
      )}
    </View>
  );
}

import { FONT_TITLE, FONT_BODY, FONT_SUB, FONT_SMALL, FONT_BUTTON, getTrailsByReflection, getTrailStats } from '@egoless-do/core';
import { X, Check, Plus, Link } from 'lucide-react-native';
import React, { useMemo, useCallback, useState } from 'react';
import { View, Text, Modal, TouchableOpacity, ScrollView, StyleSheet } from 'react-native';

import { useTheme, useT } from '../../../components/UI';
import { useAppStore, useShallowStore } from '../../../store/useAppStore';


import CreateThoughtTrailModal from './CreateThoughtTrailModal';

interface Props {
  visible: boolean;
  reflectionId: string;
  onClose: () => void;
  /** Override toggle behavior (e.g. for new reflections not yet saved). If provided, linked state comes from parent. */
  onToggle?: (trailId: string, linked: boolean) => void;
  /** External linked trail IDs (used with onToggle for new reflections) */
  linkedTrailIds?: Set<string>;
}

export default function TrailPickerModal({ visible, reflectionId, onClose, onToggle, linkedTrailIds: externalLinkedIds }: Props) {
  const TH = useTheme();
  const T = useT();
  const P = TH.primary;
  const { thoughtTrails: rawThoughtTrails, reflections: rawReflections, removeReflectionFromTrail, addReflectionToTrail } = useShallowStore(s => ({
    thoughtTrails: s.thoughtTrails,
    reflections: s.reflections,
    removeReflectionFromTrail: s.removeReflectionFromTrail,
    addReflectionToTrail: s.addReflectionToTrail,
  }));
  const [showCreate, setShowCreate] = useState(false);

  const trails = useMemo(() =>
    (rawThoughtTrails ?? []).filter(t => !t.deleted),
    [rawThoughtTrails]
  );

  const reflections = useMemo(() =>
    (rawReflections ?? []).filter(r => !r.deleted),
    [rawReflections]
  );

  const linkedTrailIds = useMemo(() => {
    if (externalLinkedIds) return externalLinkedIds;
    const linked = getTrailsByReflection(reflectionId, trails);
    return new Set(linked.map(t => t.id));
  }, [reflectionId, trails, externalLinkedIds]);

  const handleToggle = useCallback((trailId: string) => {
    const isLinked = linkedTrailIds.has(trailId);
    if (onToggle) {
      onToggle(trailId, !isLinked);
    } else {
      if (isLinked) {
        removeReflectionFromTrail(trailId, reflectionId);
      } else {
        addReflectionToTrail(trailId, reflectionId);
      }
    }
  }, [removeReflectionFromTrail, addReflectionToTrail, reflectionId, linkedTrailIds, onToggle]);

  const handleCreateSuccess = useCallback((trailId: string) => {
    if (onToggle) {
      onToggle(trailId, true);
    } else {
      addReflectionToTrail(trailId, reflectionId);
    }
    setShowCreate(false);
  }, [addReflectionToTrail, reflectionId, onToggle]);

  return (
    <Modal visible={visible} transparent animationType="fade">
      <View style={styles.overlay}>
        <View style={[styles.container, { backgroundColor: TH.cardSolid }]}>
          <View style={styles.header}>
