// ─── SleepBarrierPage — Barrier (仪轨) session UI ────────────────
// Shows countdown circle, practice selection, and skip button.

import { Wind, Brain, BellRing, BookOpen } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity, Animated } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useT } from '../../../components/UI';
import { styles } from '../sleepStyles';

/**
 * Props for the {@link SleepBarrierPage} component.
 *
 * @property currentPeriod - The current traditional-Chinese-medicine time
 *   period object containing the period name (`nameZh`) and associated
 *   organ (`organ`).
 * @property remainingSec - Seconds remaining before the barrier countdown
 *   reaches zero.
 * @property barrierDuration - Total barrier duration in minutes, used to
 *   calculate the progress ratio for the countdown display.
 * @property glowAnim - An `Animated.Value` (0-1) driving the pulsing glow
 *   opacity and scale of the countdown circle.
 * @property completedPractice - List of practice type identifiers the user
 *   has already completed during this barrier session (e.g. "breathing").
 * @property awayMin - Total minutes the user spent away from the app
 *   during the barrier session.
 * @property onChoosePractice - Callback invoked when the user taps a
 *   practice option. Receives the practice type string.
 * @property onSkipToGratitude - Callback invoked when the user taps the
 *   skip button to proceed directly to the gratitude phase.
 */
interface Props {
  currentPeriod: { nameZh: string; organ: string };
  remainingSec: number;
  barrierDuration: number;
  glowAnim: Animated.Value;
  completedPractice: string[];
  awayMin: number;
  onChoosePractice: (type: string) => void;
  onSkipToGratitude: () => void;
}

/**
 * Sleep Barrier page component.
 *
 * Renders the active barrier (yigui / ritual) session UI, which consists of:
 *
 * - A **countdown circle** that displays the remaining minutes:seconds and
 *   pulses with a purple glow animation driven by `glowAnim`.
 * - The current TCM time period name and associated organ.
 * - A **practice progress** section listing which practices the user has
 *   completed so far during this barrier session.
 * - A row of four **practice choice buttons** (breathing, meditation,
 *   mantra, reading) that delegate to `onChoosePractice`.
 * - A **skip** button that jumps directly to the gratitude phase via
 *   `onSkipToGratitude`.
 * - A warning showing total away time if the user left the app.
 *
 * @param props - {@link Props}
 * @returns A `SafeAreaView` containing the full barrier session layout
 *   with a dark (#0a0a1a) background.
 */
export default function SleepBarrierPage(props: Props) {
  const { currentPeriod, remainingSec, barrierDuration, glowAnim, completedPractice, awayMin,
    onChoosePractice, onSkipToGratitude } = props;
  const T = useT();

  const min = Math.floor(remainingSec / 60);
  const sec = remainingSec % 60;
  const glowOpacity = glowAnim.interpolate({ inputRange: [0, 1], outputRange: [0.3, 0.8] });
  const glowScale = glowAnim.interpolate({ inputRange: [0, 1], outputRange: [1, 1.05] });

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: '#0a0a1a' }}>
      <View style={styles.barrierCenter}>
        <Text style={styles.barrierPeriod}>{currentPeriod.nameZh} · {currentPeriod.organ}</Text>

        <Animated.View style={[styles.barrierCircle, {
          opacity: glowOpacity,
          transform: [{ scale: glowScale }],
          borderColor: '#8B5CF6',
        }]}>
          <View style={[styles.barrierCircleInner, { borderColor: '#8B5CF6' }]}>
            <Text style={styles.barrierTime}>{min}:{String(sec).padStart(2, '0')}</Text>
            <Text style={styles.barrierLabel}>{T('sleepBarrierActive')}</Text>
          </View>
        </Animated.View>

        {/* Practice progress */}
        {completedPractice.length > 0 && (
          <View style={styles.practiceProgress}>
            <Text style={styles.practiceProgressTitle}>{T('sleepPracticeProgress') || '修行进度'}</Text>
            {completedPractice.map(p => (
              <Text key={p} style={styles.practiceProgressItem}>✓ {p}</Text>
            ))}
          </View>
        )}

        {/* Choose practice */}
        <Text style={styles.barrierStepTitle}>{T('sleepStep1')}</Text>
        <View style={styles.barrierChoiceRow}>
          {[
            { type: 'breathing', Icon: Wind, label: T('sleepChooseBreath') },
            { type: 'meditation', Icon: Brain, label: T('sleepChooseMeditate') },
            { type: 'mantra', Icon: BellRing, label: '持咒' },
            { type: 'reading', Icon: BookOpen, label: '阅读' },
          ].map(({ type, Icon, label }) => (
            <TouchableOpacity key={type} style={styles.barrierChoiceBtn} onPress={() => onChoosePractice(type)}>
              <Icon size={24} color="#8B5CF6" />
              <Text style={styles.barrierChoiceLabel}>{label}</Text>
            </TouchableOpacity>
          ))}
        </View>

        <TouchableOpacity style={styles.barrierSkipBtn} onPress={onSkipToGratitude}>
          <Text style={styles.barrierSkipText}>{T('sleepStep2')} →</Text>
        </TouchableOpacity>

        {awayMin > 0 && (
          <Text style={styles.barrierAwayText}>{T('sleepBarrierAway')} {awayMin}{T('sleepMinutes')}</Text>
        )}
      </View>
    </SafeAreaView>
  );
}

// ─── SleepReportPage — Session report UI ─────────────────────────
// Shows barrier stats, gratitude count, practice log, streak.

import { formatSleepDuration , FONT_LABEL } from '@egoless-do/core';
import { X, Clock, Moon, Star, Heart, Wind } from 'lucide-react-native';
import React from 'react';
import { View, Text, TouchableOpacity } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

import { useTheme, useT } from '../../../components/UI';
import { styles } from '../sleepStyles';

/**
 * Props for the {@link SleepReportPage} component.
 *
 * @property barrierDuration - Configured barrier duration in minutes.
 * @property barrierElapsed - Actual elapsed barrier time in seconds.
 *   Compared against `barrierDuration * 60` to determine whether the
 *   barrier was completed or skipped.
 * @property awayMin - Total minutes the user spent away from the app
 *   during the barrier session.
 * @property quality - Sleep quality rating (1-5 stars) from the gratitude
 *   phase. 0 means not rated.
 * @property gratitude - Array of gratitude strings entered by the user.
 *   Empty strings are filtered out before display.
 * @property completedPractice - List of practice type identifiers the user
 *   completed during the barrier session (e.g. "breathing", "meditation").
 * @property sleepStreak - Current consecutive-day sleep streak count.
 * @property onFinish - Callback invoked when the user taps the "back to
 *   home" button.
 * @property onViewHistory - Callback invoked when the user taps the
 *   "view history" button to navigate to sleep history.
 */
interface Props {
  barrierDuration: number;
  barrierElapsed: number;
  awayMin: number;
  quality: number;
  gratitude: string[];
  completedPractice: string[];
  sleepStreak: number;
  onFinish: () => void;
  onViewHistory: () => void;
}

/**
 * Sleep Report page component.
 *
 * Renders a summary card at the end of a sleep session showing:
 *
 * - Whether the barrier was **completed** (elapsed >= duration) or was
 *   skipped early, with an appropriate title.
 * - **Barrier duration** formatted via `formatSleepDuration` (only shown
 *   if the user spent any time in the barrier).
 * - **Away time** with a red highlight if it exceeded 5 minutes, green
 *   otherwise.
 * - **Sleep quality** as filled star icons (only if rated).
 * - **Gratitude count** showing how many non-empty gratitude entries the
 *   user provided.
 * - **Practice log** listing the completed practice types in purple.
 * - **Sleep streak** in consecutive days with a fire emoji (only if > 0).
 *
 * Below the card are two action buttons:
 * - "Back to home" (`onFinish`)
 * - "View history" (`onViewHistory`)
 *
 * @param props - {@link Props}
 * @returns A `SafeAreaView` containing the session report layout, themed
 *   with the current app theme via `useTheme()`.
 */
export default function SleepReportPage(props: Props) {
  const { barrierDuration, barrierElapsed, awayMin, quality, gratitude, completedPractice, sleepStreak,
    onFinish, onViewHistory } = props;
  const TH = useTheme();
  const T = useT();
  const completed = barrierElapsed >= barrierDuration * 60;
  const validGratitude = gratitude.filter(g => g.trim());

  return (
    <SafeAreaView edges={['top']} style={{ flex: 1, backgroundColor: TH.bg }}>
      <View style={styles.prepHeader}>
        <Text style={[styles.prepTitle, { color: TH.text }]}>{T('sleepReport')}</Text>
        <TouchableOpacity onPress={onFinish}>
          <X size={22} color={TH.sub} />
        </TouchableOpacity>
      </View>
      <View style={{ flex: 1, justifyContent: 'center', padding: 24 }}>
        <View style={[styles.reportCard, { borderColor: `${TH.primary}20` }]}>
          <Text style={[styles.reportTitle, { color: TH.primary }]}>
            {completed ? `🌙 ${T('sleepBarrierComplete')}` : `🌙 ${T('sleepRitual')}`}
          </Text>
          {barrierElapsed > 0 && (
            <View style={styles.reportRow}>
              <Clock size={16} color={TH.sub} />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>{T('sleepDuration')}</Text>
              <Text style={[styles.reportValue, { color: TH.text }]}>{formatSleepDuration(Math.floor(barrierElapsed / 60))}</Text>
            </View>
          )}
          {awayMin > 0 && (
            <View style={styles.reportRow}>
              <Moon size={16} color={TH.sub} />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>{T('sleepAwayTime')}</Text>
              <Text style={[styles.reportValue, { color: awayMin > 5 ? '#EF4444' : '#10B981' }]}>
                {awayMin}{T('sleepMinutes')}
              </Text>
            </View>
          )}
          {quality > 0 && (
            <View style={styles.reportRow}>
              <Star size={16} color="#F59E0B" />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>睡眠质量</Text>
              <Text style={[styles.reportValue, { color: '#F59E0B' }]}>{'★'.repeat(quality)}</Text>
            </View>
          )}
          {validGratitude.length > 0 && (
            <View style={styles.reportRow}>
              <Heart size={16} color={TH.sub} />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>{T('sleepGratitude')}</Text>
              <Text style={[styles.reportValue, { color: TH.text }]}>
                {validGratitude.length}{T('sleepCompleted')}
              </Text>
            </View>
          )}
          {completedPractice.length > 0 && (
            <View style={styles.reportRow}>
              <Wind size={16} color="#8B5CF6" />
              <Text style={[styles.reportLabel, { color: TH.sub }]}>修行记录</Text>
              <Text style={[styles.reportValue, { color: '#8B5CF6' }]}>{completedPractice.join(', ')}</Text>
            </View>
          )}
          {sleepStreak > 0 && (
            <View style={styles.reportRow}>
              <Text style={{ fontSize: FONT_LABEL() }}>🔥</Text>
              <Text style={[styles.reportLabel, { color: TH.sub }]}>连续天数</Text>
              <Text style={[styles.reportValue, { color: '#EF4444' }]}>{sleepStreak} 天</Text>
            </View>
          )}
        </View>

        <View style={styles.reportBtnRow}>
          <TouchableOpacity
            style={[styles.saveBtn, { backgroundColor: TH.primary, flex: 1 }]}
            onPress={onFinish}
          >
            <Text style={styles.saveBtnText}>回到首页</Text>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.saveBtn, { backgroundColor: `${TH.primary}15`, flex: 1, borderWidth: 1, borderColor: `${TH.primary}30` }]}
            onPress={onViewHistory}
          >
            <Text style={[styles.saveBtnText, { color: TH.primary }]}>查看历史</Text>
          </TouchableOpacity>
        </View>
      </View>
    </SafeAreaView>
  );
}

