                {(() => {
                  const Icon = HEADER_TAB_ICONS[key];
                  return Icon ? <Icon size={14} color={key === activeKey ? '#fff' : TH.sub} strokeWidth={key === activeKey ? 2.2 : 1.5} /> : null;
                })()}
