              </View>
            </TouchableOpacity>
          ))}
        </View>
      )}
      <View style={{ paddingHorizontal: 16, paddingTop: 6, paddingBottom: 0, borderBottomWidth: StyleSheet.hairlineWidth, borderBottomColor: TH.border }}>
        <Text style={{ fontSize: FONT_SUB(), color: TH.sub }}>
          {t('today', language)} · {today}
        </Text>
      </View>
    </View>
  );
