  it('不应该重复保存已存在的历史记录', () => {
    const plans = [basePlan];
    const planItems = [basePlanItem];
    const checkins: PlanItemCheckin[] = [];
    const customTodos: DailyCustomTodo[] = [];
    const history: DailyTodoHistory[] = [
      {
        id: 'history-1',
        planId: 'plan-1',
        date: '2026-06-04',
        planItems: [{ id: 'item-1', name: '任务1', link: 'manual', done: false }],
        customTodos: [],
        updatedAt: Date.now(),
        deleted: false,
      },
