import { activeOnly } from '../../utils';
// ─── 感念索引构建 ──────────────────────────────────────────────
import type { MindReflection } from '../../types/reflection';

export interface ReflectionIndex {
  id: string;
  content: string;
  contentLower: string;
  keywords: string[];
  mood: string;
  moodLower: string;
  tags: string[];
  tagsLower: string[];
  timestamp: number;
}

/**
 * 从感念数组构建检索索引，提取关键词、情绪、标签等特征
 */
export function buildIndex(reflections: MindReflection[]): ReflectionIndex[] {
  return reflections
    .filter(r => !r.deleted)
    .map(r => ({
      id: r.id,
      content: r.content,
      contentLower: r.content.toLowerCase(),
      keywords: extractKeywords(r.content),
      mood: r.mood ?? '',
      moodLower: (r.mood ?? '').toLowerCase(),
      tags: r.tags ?? [],
      tagsLower: (r.tags ?? []).map(t => t.toLowerCase()),
      timestamp: r.timestamp,
    }));
}

/**
 * 从文本中提取关键词（简单分词）
 */
function extractKeywords(text: string): string[] {
  // 移除标点符号，按空格和常见分隔符分词
  const cleaned = text.replace(/[，。！？、；：""''（）【】《》\s]+/g, ' ');
  const words = cleaned.split(/\s+/).filter(w => w.length >= 2);
  // 去重并转小写
  return [...new Set(words.map(w => w.toLowerCase()))];
}

// ─── RAG Prompt 构建器 ─────────────────────────────────────────
import type { ReflectionIndex } from './indexer';
import { formatDate } from '../../utils';

const MAX_PROMPT_LENGTH = 800;
const MAX_CONTENT_LENGTH = 60;

/**
 * 将感念格式化为紧凑的摘要格式
 * 格式: [日期] 情绪 内容... [标签]
 */
export function formatReflectionSummary(item: ReflectionIndex, language: string = 'zh'): string {
  const date = formatDate(new Date(item.timestamp), language, {
    month: 'numeric',
    day: 'numeric',
  });
  const mood = item.mood ? ` ${item.mood}` : '';
  const content = item.content.length > MAX_CONTENT_LENGTH
    ? item.content.slice(0, MAX_CONTENT_LENGTH) + '...'
    : item.content;
  const tags = item.tags.length > 0 ? ` [${item.tags.join(',')}]` : '';
  return `[${date}]${mood} ${content}${tags}`;
}

/**
 * 构建推荐 prompt，将 Top-5 感念格式化为精简 prompt（~500 字符）
 */
export function buildRecommendPrompt(
  query: string,
  reflections: ReflectionIndex[],
): string {
  const reflLines = reflections
    .slice(0, 5)
    .map((r, i) => `[${i}] ${formatReflectionSummary(r)}`)
    .join('\n');
  const queryLine = query ? `主题: "${query}"\n` : '';
  const footer = '只输出JSON: [{"name":"","description":"","reflectionIndices":[0,1],"confidence":0.8}]';

  let prompt = `${queryLine}感念:\n${reflLines}\n${footer}`;

  // 截断到限制长度（保留完整的 footer）
  if (prompt.length > MAX_PROMPT_LENGTH) {
    const footerLen = footer.length + 1;
    prompt = prompt.slice(0, MAX_PROMPT_LENGTH - footerLen) + '\n' + footer;
  }

  return prompt;
}

/**
 * 构建查询意图解析 prompt
 */
export function buildQueryParsePrompt(
  input: string,
  reflections: ReflectionIndex[],
  history?: string[],
): string {
  const header = '分析用户查询意图，返回筛选条件JSON。';
  const inputLine = `查询: "${input}"`;
  const reflLines = reflections
    .slice(0, 5)
    .map((r, i) => `[${i}] ${formatReflectionSummary(r)}`)
    .join('\n');

  const historyPart = history && history.length > 0
    ? `\n对话: ${history.join(' | ')}`
    : '';

  const footer = '输出: {"filters":{"timeRange":"month","tags":[],"moods":[]},"intent":"filter","question":null,"topic":"..."}';

  let prompt = `${header}\n${inputLine}${historyPart}\n感念:\n${reflLines}\n${footer}`;

  if (prompt.length > MAX_PROMPT_LENGTH) {
    const footerLen = footer.length + 1;
    prompt = prompt.slice(0, MAX_PROMPT_LENGTH - footerLen) + '\n' + footer;
  }

  return prompt;
}

import { describe, it, expect } from 'vitest';
import { expandTerms, retrieveTopK, SYNONYM_MAP } from './retriever';
import type { ReflectionIndex } from './indexer';

// ─── Test helpers ───────────────────────────────────────────
function makeIndex(overrides: Partial<ReflectionIndex> = {}): ReflectionIndex {
  return {
    id: 'r1',
    content: '',
    contentLower: '',
    keywords: [],
    mood: '',
    moodLower: '',
    tags: [],
    tagsLower: [],
    timestamp: Date.now(),
    ...overrides,
  };
}

// ─── expandTerms ────────────────────────────────────────────
describe('expandTerms', () => {
  it('returns original terms when no synonyms match', () => {
    const result = expandTerms(['xyz123', 'abc456']);
    expect(result).toEqual(expect.arrayContaining(['xyz123', 'abc456']));
  });

  it('expands a main term to include all its synonyms', () => {
    const result = expandTerms(['焦虑']);
    expect(result).toContain('焦虑');
    expect(result).toContain('紧张');
    expect(result).toContain('不安');
    expect(result).toContain('压力');
  });

  it('expands a synonym back to its main term and siblings', () => {
    // '高兴' is a synonym of '开心'
    const result = expandTerms(['高兴']);
    expect(result).toContain('开心');
    expect(result).toContain('快乐');
    expect(result).toContain('高兴');
  });

  it('expands via substring matching (≥2 chars)', () => {
    // '焦' alone (< 2 chars) should NOT trigger substring match
    const short = expandTerms(['焦']);
    // '焦虑' is a main term, so '焦' alone won't match via substring
    // but '虑' is 1 char, also won't match

    // '焦虑' (2 chars, exact match as main term) should expand
    const exact = expandTerms(['焦虑']);
    expect(exact.length).toBeGreaterThan(1);
  });

  it('deduplicates expanded terms', () => {
    const result = expandTerms(['开心', '高兴']);
    // '高兴' is a synonym of '开心', so expansion overlaps
    const uniqueCheck = new Set(result);
    expect(result.length).toBe(uniqueCheck.size);
  });

  it('handles empty input', () => {
    expect(expandTerms([])).toEqual([]);
  });

  it('handles terms that are not in the synonym map', () => {
    const result = expandTerms(['量子力学']);
    expect(result).toContain('量子力学');
    expect(result.length).toBe(1);
  });
});

// ─── retrieveTopK ───────────────────────────────────────────
describe('retrieveTopK', () => {
  const now = Date.now();

  const reflections: ReflectionIndex[] = [
    makeIndex({
      id: 'r1',
      content: '今天很焦虑，工作压力大',
      contentLower: '今天很焦虑，工作压力大',
      mood: '焦虑',
      moodLower: '焦虑',
      tags: ['工作'],
      tagsLower: ['工作'],
      timestamp: now - 1000, // very recent
    }),
    makeIndex({
      id: 'r2',
      content: '心情不错，和朋友吃饭很开心',
      contentLower: '心情不错，和朋友吃饭很开心',
      mood: '开心',
      moodLower: '开心',
      tags: ['社交'],
      tagsLower: ['社交'],
      timestamp: now - 86400000 * 10, // 10 days ago
    }),
    makeIndex({
      id: 'r3',
      content: '今天跑步了，感觉身体好了很多',
      contentLower: '今天跑步了，感觉身体好了很多',
      mood: '平静',
      moodLower: '平静',
      tags: ['健康', '运动'],
      tagsLower: ['健康', '运动'],
      timestamp: now - 86400000 * 60, // 60 days ago (older)
    }),
    makeIndex({
      id: 'r4',
      content: '无内容',
      contentLower: '无内容',
      mood: '',
      moodLower: '',
      tags: [],
      tagsLower: [],
      timestamp: now,
    }),
  ];

  it('returns empty array for empty query', () => {
    expect(retrieveTopK('', reflections)).toEqual([]);
    expect(retrieveTopK('   ', reflections)).toEqual([]);
  });

  it('returns empty array for empty index', () => {
    expect(retrieveTopK('焦虑', [])).toEqual([]);
  });

  it('returns results sorted by score descending', () => {
    const results = retrieveTopK('焦虑', reflections, 10);
    expect(results.length).toBeGreaterThan(0);
    for (let i = 1; i < results.length; i++) {
      expect(results[i - 1].score).toBeGreaterThanOrEqual(results[i].score);
    }
  });

  it('finds reflections matching by keyword in content', () => {
    const results = retrieveTopK('焦虑', reflections, 10);
    const ids = results.map(r => r.index.id);
    expect(ids).toContain('r1'); // contains '焦虑' in content
  });

  it('finds reflections matching by mood', () => {
    const results = retrieveTopK('焦虑', reflections, 10);
    const r1 = results.find(r => r.index.id === 'r1');
    expect(r1).toBeDefined();
    expect(r1!.score).toBeGreaterThan(0);
  });

  it('finds reflections matching by tag', () => {
    const results = retrieveTopK('工作', reflections, 10);
    const ids = results.map(r => r.index.id);
    expect(ids).toContain('r1'); // has tag '工作'
  });

  it('respects the k limit', () => {
    const results = retrieveTopK('焦虑', reflections, 1);
    expect(results.length).toBeLessThanOrEqual(1);
  });

  it('ranks recent reflections higher than old ones for same match', () => {
    // Both r1 and r3 match '运动' partially, but r3 has it as tag
    const results = retrieveTopK('运动', reflections, 10);
    // r3 should be found (has tag '运动')
    const r3 = results.find(r => r.index.id === 'r3');
    expect(r3).toBeDefined();
  });

  it('returns low scores for unmatched queries (time decay still applies)', () => {
    const results = retrieveTopK('量子力学', reflections, 10);
    // No keyword/mood/tag match, but time score > 0 for all items
    // Results exist but with low scores (only time component)
    if (results.length > 0) {
      expect(results[0].score).toBeLessThan(0.2); // only time weight (0.1) contributes
    }
  });

  it('handles multi-term queries', () => {
    const results = retrieveTopK('焦虑 工作', reflections, 10);
    const r1 = results.find(r => r.index.id === 'r1');
    expect(r1).toBeDefined();
    // r1 matches both '焦虑' (content+mood) and '工作' (tag)
    expect(r1!.score).toBeGreaterThan(0);
  });

  it('expands query terms via synonyms', () => {
    // '紧张' is a synonym of '焦虑'
    const results = retrieveTopK('紧张', reflections, 10);
    const r1 = results.find(r => r.index.id === 'r1');
    // Should find r1 because '紧张' expands to include '焦虑'
    expect(r1).toBeDefined();
    expect(r1!.score).toBeGreaterThan(0);
  });
});

// ─── 本地检索与多维评分（支持语义同义词扩展）─────────────────────
import type { ReflectionIndex } from './indexer';

export interface ScoredReflection {
  index: ReflectionIndex;
  score: number;
}

// 评分权重
const WEIGHTS = {
  keyword: 0.35,
  synonym: 0.25,
  mood: 0.2,
  time: 0.1,
  tag: 0.1,
};

// 时间衰减：30天半衰期
const TIME_DECAY_HALF_LIFE = 30 * 86400000;

// ─── 语义同义词表 ──────────────────────────────────────────────
export const SYNONYM_MAP: Record<string, string[]> = {
  // 情绪类
  '焦虑': ['紧张', '不安', '担心', '忧虑', '压力', '压力大', '睡不着', '失眠', '烦躁', '恐慌'],
  '开心': ['高兴', '快乐', '愉快', '喜悦', '满足', '幸福', '不错', '很好', '挺好', '棒'],
  '平静': ['安宁', '放松', '淡定', '从容', '安心', '踏实', '舒服'],
  '沮丧': ['失落', '难过', '悲伤', '低落', '郁闷', '烦', '不开心', '不高兴', '消沉'],
  '愤怒': ['生气', '恼火', '烦躁', '气愤', '不满', '火大', '暴躁'],
  '疲惫': ['累', '疲倦', '疲劳', '困', '没精神', '没力气', '精力不足', '倦怠'],
  '孤独': ['寂寞', '孤单', '一个人', '没人', '无聊', '空虚'],
  '迷茫': ['困惑', '不知道', '不确定', '纠结', '犹豫', '徘徊'],
  '感恩': ['感谢', '感激', '珍惜', '知足', '幸运'],
  '成长': ['进步', '提升', '学习', '领悟', '明白', '懂了', '学会'],
  // 主题类
  '工作': ['上班', '加班', '项目', 'deadline', '会议', '开会', '老板', '同事', '职场', '公司'],
  '学习': ['读书', '看书', '课程', '考试', '复习', '知识', '技能', '培训'],
  '感情': ['恋爱', '爱情', '对象', '男朋友', '女朋友', '伴侣', '婚姻', '分手'],
  '家庭': ['父母', '家人', '爸妈', '家里', '回家', '亲人'],
  '健康': ['运动', '锻炼', '跑步', '身体', '生病', '医院', '吃药', '睡眠'],
  '金钱': ['钱', '工资', '收入', '消费', '存钱', '理财', '投资', '花销'],
  '未来': ['计划', '目标', '梦想', '规划', '方向', '前途'],
  '压力': ['压力大', '焦虑', '紧张', '负担', '承受', '喘不过气'],
};

// 构建反向索引：同义词 → 主词
const REVERSE_SYNONYM: Record<string, string> = {};
for (const [main, synonyms] of Object.entries(SYNONYM_MAP)) {
  for (const syn of synonyms) {
    REVERSE_SYNONYM[syn] = main;
  }
}

// ─── 预构建子串索引（消除 expandTerms 中的 O(n²) 循环）────────
// 将每个主词/同义词的所有 ≥2 字符子串映射到其主词
const SUBSTRING_TO_MAINS = new Map<string, Set<string>>();
for (const [main, synonyms] of Object.entries(SYNONYM_MAP)) {
  const allWords = [main, ...synonyms];
  for (const word of allWords) {
    for (let len = 2; len <= word.length; len++) {
      for (let start = 0; start <= word.length - len; start++) {
        const sub = word.substring(start, start + len);
        let set = SUBSTRING_TO_MAINS.get(sub);
        if (!set) { set = new Set(); SUBSTRING_TO_MAINS.set(sub, set); }
        set.add(main);
      }
    }
  }
}

/** 查找与 term 有子串关系的所有主词（O(1) 查表替代 O(S×L) 遍历） */
function findSubstringMains(term: string): Set<string> | undefined {
  // term 作为子串命中
  const direct = SUBSTRING_TO_MAINS.get(term);
  // term 包含更长的词（反向：某个词是 term 的子串）
  // 对于中文短查询词（2-4字），SUBSTRING_TO_MAINS 已覆盖主要场景
  return direct;
}

/**
 * 扩展查询词：将查询中的词替换/扩展为包含同义词
 */
export function expandTerms(terms: string[]): string[] {
  const expanded = new Set<string>(terms);
  for (const term of terms) {
    // 如果是某个主词的同义词，加入主词和所有同义词
    const main = REVERSE_SYNONYM[term];
    if (main) {
      expanded.add(main);
      for (const syn of SYNONYM_MAP[main]) expanded.add(syn);
    }
    // 如果是主词，加入所有同义词
    if (SYNONYM_MAP[term]) {
      for (const syn of SYNONYM_MAP[term]) expanded.add(syn);
    }
    // 部分匹配：通过预构建的子串索引 O(1) 查找
    if (term.length >= 2) {
      const matchedMains = findSubstringMains(term);
      if (matchedMains) {
        for (const m of matchedMains) {
          expanded.add(m);
          for (const syn of SYNONYM_MAP[m]) expanded.add(syn);
        }
      }
    }
  }
  return Array.from(expanded);
}

/**
 * 多维评分检索，返回 Top-K 相关感念
 */
export function retrieveTopK(
  query: string,
  index: ReflectionIndex[],
  k: number = 5,
): ScoredReflection[] {
  if (!query.trim() || index.length === 0) return [];

  const queryTerms = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (queryTerms.length === 0) return [];

  // 扩展查询词（加入同义词）
  const expandedTerms = expandTerms(queryTerms);

  const now = Date.now();

  const scored: ScoredReflection[] = index.map(item => {
    const keywordScore = calcKeywordScore(queryTerms, item);
    const synonymScore = calcSynonymScore(expandedTerms, item);
    const moodScore = calcMoodScore(queryTerms, item);
    const timeScore = calcTimeScore(item.timestamp, now);
    const tagScore = calcTagScore(queryTerms, item);

    const total =
      keywordScore * WEIGHTS.keyword +
      synonymScore * WEIGHTS.synonym +
      moodScore * WEIGHTS.mood +
      timeScore * WEIGHTS.time +
      tagScore * WEIGHTS.tag;

    return { index: item, score: total };
  });

  return scored
    .filter(s => s.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, k);
}

/**
 * 原始关键词匹配评分（0-1）
 */
function calcKeywordScore(terms: string[], item: ReflectionIndex): number {
  let matchCount = 0;
  for (const term of terms) {
    if (
      item.contentLower.includes(term) ||
      item.tagsLower.some(t => t.includes(term)) ||
      item.moodLower.includes(term)
    ) {
      matchCount++;
    }
  }
  return terms.length > 0 ? matchCount / terms.length : 0;
}

/**
 * 同义词扩展匹配评分（0-1）
 */
function calcSynonymScore(expandedTerms: string[], item: ReflectionIndex): number {
  let matchCount = 0;
  for (const term of expandedTerms) {
    if (
      item.contentLower.includes(term) ||
      item.tagsLower.some(t => t.includes(term)) ||
      item.moodLower.includes(term)
    ) {
      matchCount++;
    }
  }
  // 归一化：扩展词数量可能很多，用原始词数量归一化
  return Math.min(1, matchCount / Math.max(3, Math.min(expandedTerms.length, 10) / 3));
}

/**
 * 情绪匹配评分（0-1）
 */
function calcMoodScore(terms: string[], item: ReflectionIndex): number {
  if (!item.mood) return 0;
  for (const term of terms) {
    if (item.moodLower.includes(term)) return 1;
    // 通过同义词表匹配
    const main = REVERSE_SYNONYM[term];
    if (main && (item.moodLower.includes(main) || SYNONYM_MAP[main]?.some(s => item.moodLower.includes(s)))) {
      return 0.8;
    }
  }
  return 0;
}

/**
 * 时间衰减评分（0-1），越近越高
 */
function calcTimeScore(timestamp: number, now: number): number {
  const age = now - timestamp;
  if (age <= 0) return 1;
  return Math.exp(-age / TIME_DECAY_HALF_LIFE);
}

/**
 * 标签匹配评分（0-1）
 */
function calcTagScore(terms: string[], item: ReflectionIndex): number {
  if (item.tags.length === 0) return 0;
  let matchCount = 0;
  for (const term of terms) {
    if (item.tagsLower.some(t => t.includes(term) || term.includes(t))) {
      matchCount++;
    }
  }
  return Math.min(1, matchCount / Math.max(1, terms.length));
}

