// ─── Shared Zustand store (platform-agnostic logic) ──────────────
import { uid, dateStr } from './utils';
import { MIND_COLORS_EXTENDED } from './constants';
import type { MindReflection, Habit, FoodEntry, CheckinEntry, MedHistoryEntry, UserProfile, AppState, FastingSession, ExerciseEntry, CustomFoodPreset, Plan, PlanItem, PlanItemCheckin, RecycleBinItem, GraceHistoryEntry, DailyCustomTodo, DailyTodoHistory, ThoughtTrail, TrailNote, ReflectionLink, CheckinReview } from './types';
import type { AIMode, ModelConfig } from './ai/types';
import { defaultAuthState } from './types';

// ── Initial seed data ─────────────────────────────────────────────
// ── Pure action creators ──────────────────────────────────────────
export function createHabitFromForm(form: {
  name: string;
  startDate?: string;
  targetDays?: number;
  goal?: string;
  insight?: string;
  createTag?: boolean;
  alarmEnabled?: boolean;
  alarmHour?: number;
  alarmMinute?: number;
  link?: import('./types').HabitLink;
  linkConfig?: { targetHours?: number; targetMinutes?: number };
  visionId?: string;
}): Habit {
  return {
    id: uid(),
    name: form.name,
    startDate: form.startDate ?? dateStr(),
    targetDays: form.targetDays ?? 21,
    goal: form.goal ?? '',
    insight: form.insight ?? '',
    createTag: form.createTag ?? false,
    doneDays: 0,
    streak: 0,
    interrupted: 0,
    status: 'notStarted',
    checkedDates: [],
    pauseReason: '',
    abandonReason: '',
    alarmEnabled: form.alarmEnabled ?? false,
    alarmHour: form.alarmHour ?? 8,
    alarmMinute: form.alarmMinute ?? 0,
    link: form.link ?? 'none',
    linkConfig: form.linkConfig,
    visionId: form.visionId ?? undefined,
    updatedAt: Date.now(),
    deleted: false,
  };
}

export function createReflection(params: { content: string; tags: string[]; mood: string; colorIdx?: number; link?: string }): MindReflection {
  const idx = Math.min(Math.max(params.colorIdx ?? 0, 0), MIND_COLORS_EXTENDED.length - 1);
  return {
    id: uid(), timestamp: Date.now(),
    content: params.content, tags: params.tags,
    mood: params.mood,
    link: params.link || undefined,
    colors: MIND_COLORS_EXTENDED[idx] as unknown as readonly [string, string],
    isPinned: false, isPublished: false,
    updatedAt: Date.now(),
    deleted: false,
  };
}

export function createFastingSession(targetHours: number): FastingSession {
  return { id: uid(), targetHours, startedAt: Date.now(), updatedAt: Date.now(), deleted: false };
}

// ── Resettable data state (everything except auth/theme/language) ─
export const defaultDataState = {
  streak: 0,
  waterMl: 0,
