  habits: [] as Habit[],
  activeFasting: null as FastingSession | null,
  userProfile: {} as UserProfile,
  plans: [] as Plan[],
  planItems: [] as PlanItem[],
  planItemCheckins: [] as PlanItemCheckin[],
  dailyCustomTodos: [] as DailyCustomTodo[],
  dailyTodoHistory: [] as DailyTodoHistory[],
