export type { I18nKeys, I18nKey } from './types';
export { zh } from './zh';
export { en } from './en';
export { zhHant } from './zh-Hant';

import type { I18nKeys, I18nKey } from './types';
import { zh } from './zh';
import { en } from './en';
import { zhHant } from './zh-Hant';

export const translations: Record<string, I18nKeys> = {
  zh,
  'zh-Hant': zhHant,
  en,
};

export const getT = (lang: string): I18nKeys => translations[lang] ?? zh;

/**
 * Type-safe translation lookup.
 * @param key - Must be a valid key from I18nKeys (compile-time checked).
 *                If you need dynamic keys, use getT(lang)[key as I18nKey].
 * @param lang - Language code ('zh', 'en', 'zh-Hant'). Defaults to 'zh'.
 * @returns Translated string, or the key itself if translation is missing.
 */
export const t = (key: I18nKey, lang: string = 'zh', params?: Record<string, string | number>): string => {
  const dict = translations[lang] ?? translations['zh'];
  let text = (dict as unknown as Record<string, string>)?.[key]
    ?? (translations['en'] as unknown as Record<string, string>)?.[key]
    ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(`{${k}}`, String(v));
    }
  }
  return text;
};

export interface I18nKeys {
  appName: string; streak: string; days: string; home: string;
  fasting: string; meditation: string; reflections: string; exercise: string;
  habits: string; stats: string; settings: string;
  linkWorld: string; todayCheckin: string; openCheckin: string;
  done: string; notDone: string; cancel: string; save: string;
  submit: string; note: string; freeCheckin: string;
  startFasting: string; quickStart: string; stopFasting: string;
  accMed: string; bgMusic: string;
  medMusicFocus: string; medMusicMeditate: string; medMusicExercise: string; medMusicUser: string;
  medSelectMusic: string; medTapToSelect: string; medNoMusic: string;
  startMed: string; stopMed: string;
  shareMed: string; shareCardTitle: string; shareCardSession: string;
  shareCardDownload: string; mindPulse: string; newReflection: string;
  saveReflection: string; myHabits: string; addHabit: string;
  startDate: string; targetDays: string; createTag: string;
  createHabit: string; editHabit: string; allStatus: string;
