/** No-op adapter for unit tests — all persistence calls are silently ignored. */
const noopAdapter: StorageAdapter = {
  persistChange: async () => {},
  markDeleted: async () => {},
  batchDelete: async () => {},
  persistSettings: async () => {},
  getSettings: async () => null,
